local config = {
  ui_story_5020_50200101_1_dialog_content = "Mungkin semua ini dimulai sekitar sepuluh tahun yang lalu...",
  ui_story_5020_50200101_2_dialog_content = "Dengan kelahiran ketiga gadis itu.",
  ui_story_5020_50200101_3_dialog_content = "Mereka tidak mengenal satu sama lain, masing-masing terikat pada nasib mereka sendiri.",
  ui_story_5020_50200101_4_dialog_content = "Waktu berlalu ketika mereka tanpa sadar mengalir masuk dan keluar dari kehidupan satu sama lain ...",
  ui_story_5020_50200101_5_dialog_content = "Melayang di jalan masing-masing, berjuang melawan perubahan hidup.",
  ui_story_5020_50200101_6_dialog_content = "Namun tanpa sepengetahuan ketiga gadis itu, jalan mereka akan segera bergabung menjadi satu... Dalam waktu yang tidak lama lagi.",
  ui_story_5020_50200101_7_dialog_content = "Gadis pertama kehilangan ingatannya.",
  ui_story_5020_50200101_8_dialog_content = "Sifatnya yang berani dan saleh membentuknya menjadi ksatria pengembara yang tak kenal takut dan sopan saat dia mengembara melintasi negeri.",
  ui_story_5020_50200101_9_dialog_content = "Dia akhirnya kembali ke kampung halamannya untuk mencari ingatannya yang hilang.",
  ui_story_5020_50200101_10_dialog_content = "Di sana, dia mendapat teman baru dan berhubungan kembali dengan yang lama.",
  ui_story_5020_50200101_11_dialog_content = "Namun dia harus mempertaruhkan nyawanya untuk menyelamatkan teman-teman ini dari bahaya dan akhirnya terjebak di dalam kastil utama.",
  ui_story_5020_50200101_12_dialog_content = "Hingga sekarang, keberadaannya tetap menjadi misteri...",
  ui_story_5020_50200101_13_dialog_content = "Gadis kedua kehilangan bimbingannya.",
  ui_story_5020_50200101_14_dialog_content = "Dia menjalani cobaan demi cobaan untuk menjadi ninja yang hebat setelah tuannya tidak ada.",
  ui_story_5020_50200101_15_dialog_content = "Dia belajar sendiri untuk memikul tanggung jawab tuannya.",
  ui_story_5020_50200101_16_dialog_content = "Hingga suatu hari, dia menemukan kesempatan untuk menyelamatkan tuannya.",
  ui_story_5020_50200101_17_dialog_content = "Dia menginjak wilayah musuhnya dan akhirnya, menemukan mentor yang dia rindukan selama sepuluh tahun di Sealed Ground.",
  ui_story_5020_50200101_18_dialog_content = "Tapi kemudian, tuannya memilih untuk pergi ke pengasingan.",
  ui_story_5020_50200101_19_dialog_content = "Beruntungnya, setidaknya kali ini ada siluet di depannya untuk dikejar...",
  ui_story_5020_50200101_20_dialog_content = "Gadis ketiga kehilangan kesadaran dirinya.",
  ui_story_5020_50200101_21_dialog_content = "Mengindahkan keinginan ayah angkatnya, dia melakukan perjalanan ke negeri yang jauh untuk menjadi seorang pendeta.",
  ui_story_5020_50200101_22_dialog_content = "Dia percaya sepenuh hati bahwa membersihkan dunia dari hantu dan iblis adalah tugasnya.",
  ui_story_5020_50200101_23_dialog_content = "Namun, artefak yang disebut Cermin Awan membuka matanya pada sebagian kebenaran.",
  ui_story_5020_50200101_24_dialog_content = "Akhirnya, dia berdiri di Paviliun Awan dan mengarahkan pedangnya ke langit di atas...",
  ui_story_5020_50200101_25_dialog_content = "Mengambil tanggung jawab untuk mengembalikan kedamaian Koufu-jou yang telah dihancurkan oleh ayah angkatnya.",
  ui_story_5020_50200101_26_dialog_content = "...",
  ui_story_5020_50200101_27_dialog_content = "Namun ada satu kisah lagi yang terjalin di antara kisah ketiga gadis ini.",
  ui_story_5020_50200101_28_dialog_content = "Seseorang yang mengantar sang kesatria pengelana itu pulang untuk memulihkan ingatannya.",
  ui_story_5020_50200101_29_dialog_content = "Seseorang yang menolong sang ninja meskipun mereka bermusuhan.",
  ui_story_5020_50200101_30_dialog_content = "Seseorang yang setia pada sang pendeta dan menjadi saksi atas kebenaran terakhir.",
  ui_story_5020_50200101_31_dialog_content = "Orang itu...",
  ui_story_5020_50200101_32_dialog_content = "...",
  ui_story_5020_50200101_33_dialog_content = "Tunggu, apa yang orang itu lakukan lagi?",
  ui_story_5020_50200101_34_dialog_content = "Hei! Kenapa sih kau selalu lupa kalau sampai bagianku?!",
  ui_story_5020_50200101_35_dialog_content = "Oh, aduh... Biar kucoba lagi...",
  ui_story_5020_50200101_36_dialog_content = "Caelestite, yang terakhir dari jenisnya, melakukan perjalanan ribuan mil dari tanah Astra untuk membantu Lady Yao pulihkan ingatannya...",
  ui_story_5020_50200101_37_dialog_content = "Saya punya nama, Anda tahu ... Itu PlayerName, jika Anda lupa.",
  ui_story_5020_50200101_38_dialog_content = "Ah iya... PlayerName, dengan teman di belakangnya, masuk ke Sealed Ground setelah menyusup ke kastil utama Koufu-jou...",
  ui_story_5020_50200101_39_dialog_content = "Yang memungkinkan Pedang Dunia Bawah untuk membebaskan diri setelah bertahun-tahun dipenjara, terus menghilang di malam hari...",
  ui_story_5020_50200101_40_dialog_content = "Tunggu, kenapa kau membuatnya terdengar seperti kami orang jahat?",
  ui_story_5020_50200101_41_dialog_content = "Demi melindungi semua orang, pendeta itu menggunakan Cloud Mirror tanpa izin untuk mengusir para roh jahat.",
  ui_story_5020_50200101_42_dialog_content = "Akibatnya, dia justru memancing Jenderal Fujikumo dari Sealed Ground untuk muncul di hadapan mereka.",
  ui_story_5020_50200101_43_dialog_content = "Dalam kemarahannya yang tak ada habisnya, Jenderal Fujikumo terlibat dalam pertempuran yang menakutkan dengan PlayerName.",
  ui_story_5020_50200101_44_dialog_content = "Lalu?",
  ui_story_5020_50200101_45_dialog_content = "Tidak ada apa-apa. Di situlah cerita berakhir, setidaknya sampai sekarang.",
  ui_story_5020_50200101_46_dialog_content = "Yao tetap di Main Castle, dan Amemori pergi untuk mencari masternya.",
  ui_story_5020_50200101_47_dialog_content = "Dan kami di sini, bersembunyi untuk menghindari penangkapan.",
  ui_story_5020_50200101_48_dialog_content = "Dan menunggu pertemuan sesaat kita dengan Yao.",
  ui_story_5020_50200101_49_dialog_content = "Kalian paham?",
  ui_story_5020_50200101_50_dialog_content = "Tentu saja! Nah, sekarang yang kita butuhkan adalah judul kisahnya, lalu kita bisa menceritakannya pada para tamu!",
  ui_story_5020_50200101_51_dialog_content = "Hmm... Bagaimana dengan \"Perjalanan Caelestite ke Timur Jauh\"?",
  ui_story_5020_50200101_52_dialog_content = "Ya ... saya tidak berpikir begitu. Perlu sedikit lebih banyak daya tarik dan detail emosional, sesuatu untuk benar-benar menarik perhatian orang!",
  ui_story_5020_50200101_53_dialog_content = "Bagaimana dengan \"Star-Crossed Wanderers: Kisah Cinta dan Kebencian\"?",
  ui_story_5020_50200101_54_dialog_content = "Apa???",
  ui_story_5020_50200101_55_dialog_content = "Di mana cinta dan kebencian dalam cerita kita?!",
  ui_story_5020_50200101_56_dialog_content = "Tidak ada!!",
  ui_story_5020_50200101_57_dialog_content = "Eh, barusan aku melihat dari celah di pintu...",
  ui_story_5020_50200101_58_dialog_content = "Sangat sunyi di luar sana.",
  ui_story_5020_50200101_59_dialog_content = "Bukankah seharusnya samurai sedang mencari Sakai dari atas ke bawah sekarang? Betapa anehnya...",
  ui_story_5020_50200101_60_dialog_content = "Ini pertama kalinya kami menjadi buronan, tapi kami bahkan tidak melihat banyak aksi.",
  ui_story_5020_50200101_61_dialog_content = "Kenapa kedengarannya kau sangat kecewa, sih?!",
  ui_story_5020_50200101_62_dialog_content = "Apa jangan-jangan karena <color=#FFB400>Night Festivities</color> hampir dimulai, ya?",
  ui_story_5020_50200101_63_dialog_content = "Perayaan Malam?",
  ui_story_5020_50200101_64_dialog_content = "Persiapan terakhir sebelum Festival Kasuga: <color=#FFB400>Perayaan Malam</color>.",
  ui_story_5020_50200101_65_dialog_content = "<color=#e8d9bb>Gong...!</color>",
  ui_story_5020_50200101_66_dialog_content = "<color=#e8d9bb>Gong, gong...!</color>",
  ui_story_5020_50200101_67_dialog_content = "Bunyi taiko jadi penandanya...",
  ui_story_5020_50200101_68_dialog_content = "Ayo pergi! Ayo pergi!",
  ui_story_5020_50200101_69_dialog_content = "Jalanan penuh dengan pelanggan yang berharga! <size=45>Majuuuu!</size>",
  ui_story_5020_50200101_70_dialog_content = "<size=45>Chaaarge! Mari kita menghasilkan uang!</size>",
  ui_story_5020_50200101_71_dialog_content = "Di luar sana benar-benar tampak meriah, ya.",
  ui_story_5020_50200101_72_dialog_content = "Iya... Mungkin kita bisa menggunakan kerumunan untuk melarikan diri.",
  ui_story_5020_50200101_73_dialog_content = "Jenderal tidak akan membiarkan anak buahnya melakukan perburuan saat orang-orang keluar, agar tidak menimbulkan kepanikan.",
  ui_story_5020_50200101_74_dialog_content = "Ini juga waktu untuk bertemu dengan Yao.",
  ui_story_5020_50200101_75_dialog_content = "Dia terlalu lama ... Saya khawatir dia mungkin mengalami masalah.",
  ui_story_5020_50200101_76_dialog_content = "Nah, karena ini Yao yang sedang kita bicarakan, mau tak mau aku berpikir dia mungkin tersesat dalam perjalanan ke sini...",
  ui_story_5020_50200101_77_dialog_content = "Hmm... Yao memang suka begitu, sih.",
  ui_story_5020_50200101_78_dialog_content = "Kalau begitu, sebaiknya kita membuat rencana untuk menemukannya.",
  ui_story_5020_50200101_79_dialog_content = "Ayo, kita akan mulai dengan mencari di jalanan.",
  ui_story_5020_50200101_80_dialog_content = "Wuu-huu!!",
  ui_story_5020_50200101_81_dialog_content = "Ayah! Ayah! Lihat ke sana!",
  ui_story_5020_50200101_82_dialog_content = "Hei, pelan-pelan! Aku tidak akan bisa menemukanmu dengan topeng itu!",
  ui_story_5020_50200101_83_dialog_content = "Menurut Ayah begitu?",
  ui_story_5020_50200101_84_dialog_content = "Kalau begitu, kita main petak umpet saja!",
  ui_story_5020_50200101_85_dialog_content = "Ha, kena! Jangan keluyuran. Paham?",
  ui_story_5020_50200101_86_dialog_content = "Ha ha ha ha! Hentikan, ayah! Aku berjanji tidak akan kabur lagi!",
  ui_story_5020_50200101_87_dialog_content = "Mengapa semua orang memakai topeng? Tapi mereka agak lucu. Mereka terlihat seperti...",
  ui_story_5020_50200101_88_dialog_content = "Kucing.",
  ui_story_5020_50200101_89_dialog_content = "Kucing adalah makhluk nokturnal, dan dipandang sebagai pembawa pesan antara dunia orang hidup dan orang mati.",
  ui_story_5020_50200101_90_dialog_content = "Apa ini karena orang-orang di sini ingin berhubungan dengan orang-orang yang sudah mati?",
  ui_story_5020_50200101_91_dialog_content = "Di satu sisi, ya. Ini adalah tradisi yang lahir dari keinginan untuk melihat kembali orang tersayang yang telah meninggal.",
  ui_story_5020_50200101_92_dialog_content = "Orang-orang terkasih yang sudah meninggal, ya...?",
  ui_story_5020_50200101_93_dialog_content = "PlayerName?",
  ui_story_5020_50200101_94_dialog_content = "Apa?",
  ui_story_5020_50200101_95_dialog_content = "Topeng ini sangat lucu! Mengapa kita tidak mendapatkan satu untuk diri kita sendiri juga?",
  ui_story_5020_50200101_96_dialog_content = "Sekarang bukan saatnya, Vice. Kita harus...",
  ui_story_5020_50200101_97_dialog_content = "Vice memiliki titik. Topeng bisa membantu menyamarkan wajah kita.",
  ui_story_5020_50200101_98_dialog_content = "Mari kita ikuti kerumunan untuk saat ini.",
  ui_story_5020_50200101_99_dialog_content = "Kami akan membeli beberapa jika kami menemukan kios topeng.",
  ui_story_5020_50200101_100_dialog_content = "Baiklah.",
  ui_story_5020_50200101_101_dialog_content = "Hah? Sebentar, PlayerName...",
  ui_story_5020_50200101_102_dialog_content = "Ada apa, Vice?",
  ui_story_5020_50200101_103_dialog_content = "Kenapa ada kacang polong di rambutmu...?",
  ui_story_5020_50200101_104_dialog_content = "Kacang polong? Barusan aku memang merasa ada yang mengenai kepalaku, sih...",
  ui_story_5020_50200101_105_dialog_content = "Dari mana asal kacang polong ini?",
  ui_story_5020_50200101_106_dialog_content = "Pergilah, arwah. Semoga kebahagiaan melimpah!",
  ui_story_5020_50200101_107_dialog_content = "Hah!?",
  ui_story_5020_50200101_108_dialog_content = "K-kenapa kalian melempariku dengan kacang polong?!",
  ui_story_5020_50200101_109_dialog_content = "Kacang tersebut untuk mengusir hantu jahat yang mungkin menyusup ke dalam perayaan. Ini adalah tradisi kami yang lain.",
  ui_story_5020_50200101_110_dialog_content = "Apa aku benar-benar terlihat seperti hantu...?",
  ui_story_5020_50200101_111_dialog_content = "Mereka hanya berusaha melindungimu dari kejahatan... Itu hal yang baik, aku janji.",
  ui_story_5020_50200101_112_dialog_content = "Ah, begitu.",
  ui_story_5020_50200101_113_dialog_content = "Oh, aku minta maaf tentang itu! Anak-anak kadang-kadang bisa sedikit lepas kendali.",
  ui_story_5020_50200101_114_dialog_content = "Tidak apa-apa! Itu semua adalah bagian dari perayaan, bukan?",
  ui_story_5020_50200101_115_dialog_content = "Itu benar! Mereka melakukannya untuk melindungi kita, jadi tidak ada salahnya dilakukan.",
  ui_story_5020_50200101_116_dialog_content = "Nih, sekantung kacang polong untuk kalian! Sekarang kalian juga bisa melindungi orang lain!",
  ui_story_5020_50200101_117_dialog_content = "Katakan dengan saya! Roh pergi, semoga kebahagiaan datang!",
  ui_story_5020_50200101_118_dialog_content = "... Roh pergi, semoga kebahagiaan datang!",
  ui_story_5020_50200101_119_dialog_content = "Kau belajar dengan cepat, PlayerName.",
  ui_story_5020_50200101_120_dialog_content = "...",
  ui_story_5020_50200101_121_dialog_content = "Hei, lihat ke sana.",
  ui_story_5020_50200101_122_dialog_content = "Orang yang bertopeng itu...",
  ui_story_5020_50200101_123_dialog_content = "Amemori?",
  ui_story_5020_50200101_124_dialog_content = "Apa yang kau...",
  ui_story_5020_50200101_125_dialog_content = "Ssst—",
  ui_story_5020_50200101_126_dialog_content = "Malam ini, kalian harus menjauh dari jalanan.",
  ui_story_5020_50200101_127_dialog_content = "Hah?",
  ui_story_5020_50200101_128_dialog_content = "Sembunyi atau pergilah ke tempat yang jauh. Paham?",
  ui_story_5020_50200101_129_dialog_content = "Koufu-jou...",
  ui_story_5020_50200101_130_dialog_content = "Akan terlahir kembali di tengah api penderitaan.",
  ui_story_5020_50200101_131_dialog_content = "Maksudmu?",
  ui_story_5020_50200101_132_dialog_content = "Apa yang kaurencanakan, Amemori?",
  ui_story_5020_50200101_133_dialog_content = "Dia menghilang!",
  ui_story_5020_50200101_134_dialog_content = "Nona Ninja itu tak banyak omong seperti biasa.",
  ui_story_5020_50200101_135_dialog_content = "Tapi...",
  ui_story_5020_50200101_136_dialog_content = "Apakah benar-benar perlu baginya untuk datang sejauh ini hanya untuk menyampaikan pesan yang begitu jarang...?",
  ui_story_5020_50200101_137_dialog_content = "Ayah, lihat ke sana! Topeng mereka sangat keren!",
  ui_story_5020_50200101_138_dialog_content = "Itu…?",
  ui_story_5020_50200101_139_dialog_content = "<anim type=Shake><size=45>Graaah!!</size></anim>",
  ui_story_5020_50200101_140_dialog_content = "Itu hantu! Hantu ada di sini!",
  ui_story_5020_50200101_141_dialog_content = "Hantu! Ada hantu di kota!",
  ui_story_5020_50200101_142_dialog_content = "Lari!",
  ui_story_5020_50200101_143_dialog_content = "Tolong kami!!",
  ui_story_5020_50200101_144_dialog_content = "?!",
  ui_story_5020_50200101_145_dialog_content = "PlayerName! Musuh datang! Bersiaplah untuk bertempur!",
  ui_story_5020_50200202_1_dialog_content = "<anim type=Shake>Coo...</anim>",
  ui_story_5020_50200202_2_dialog_content = "Ahh! M-menjauhlah dariku!",
  ui_story_5020_50200202_3_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5020_50200202_4_dialog_content = "Kau terluka?",
  ui_story_5020_50200202_5_dialog_content = "T-Tidak... *Hendus* Aku baik-baik saja. Terima kasih.",
  ui_story_5020_50200202_6_dialog_content = "<anim type=Shake>Grah, grah...</anim>",
  ui_story_5020_50200202_7_dialog_content = "Sial... Tidak ada habisnya bagi mereka...",
  ui_story_5020_50200202_8_dialog_content = "Apa yang harus kita lakukan?",
  ui_story_5020_50200202_9_dialog_content = "Jalankan ke sana secepat mungkin, dan jangan melihat ke belakang.",
  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>Uraaagh...</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName? Apa yang kaulakukan?",
  ui_story_5020_50200202_12_dialog_content = "Anda telah bergumam aneh pada diri sendiri untuk sementara waktu sekarang.",
  ui_story_5020_50200202_13_dialog_content = "Saya telah melempar kacang ke hantu ... Tas dan tas dari mereka.",
  ui_story_5020_50200202_14_dialog_content = "Selama ini aku berteriak:",
  ui_story_5020_50200202_15_option_content = "Pergilah, arwah. Semoga kebahagiaan melimpah!",
  ui_story_5020_50200202_16_dialog_content = "<color=#e8d9bb>Wuush...</color>",
  ui_story_5020_50200202_17_option_content = "Pergilah, arwah. Semoga kebahagiaan melimpah!!",
  ui_story_5020_50200202_18_dialog_content = "<color=#e8d9bb>Wuush...</color>",
  ui_story_5020_50200202_19_option_content = "Thpirith pergi!! May kebahagiaan datang!!",
  ui_story_5020_50200202_20_dialog_content = "Aduh... Aku berteriak begitu keras sehingga aku menggigit lidahku.",
  ui_story_5020_50200202_21_dialog_content = "Berhasil, tidak?",
  ui_story_5020_50200202_22_dialog_content = "Nah, seperti yang Anda lihat... kita mungkin akan membutuhkan keterampilan tempur semua orang untuk menangani hal-hal di sini.",
  ui_story_5020_50200202_23_dialog_content = "<size=45>Aaaahhhh!</size>",
  ui_story_5020_50200202_24_dialog_content = "Kalian semua, mundur! Jangan mendekat...!",
  ui_story_5020_50200202_25_dialog_content = "Rapid Torrent!",
  ui_story_5020_50200202_26_dialog_content = "Bagaimana mereka bisa masuk ke Sakai? Di mana penjaga kota sang jenderal?",
  ui_story_5020_50200202_27_dialog_content = "Tidak mungkin mereka semua menjaga gerbang kota, kan?",
  ui_story_5020_50200202_28_dialog_content = "Tidak mungkin... Pelarian kita seharusnya tidak membutuhkan banyak perhatian.",
  ui_story_5020_50200202_29_dialog_content = "Tempat ini tidak aman. Kita perlu menemukan cara untuk membantu penduduk kota mengungsi.",
  ui_story_5020_50200202_30_dialog_content = "PlayerName, bawa semua orang keluar dari sini dulu.",
  ui_story_5020_50200202_31_dialog_content = "Semuanya, lewat sini! Ikuti aku!",
  ui_story_5020_50200202_32_dialog_content = "Hei... Bukankah itu pendeta?",
  ui_story_5020_50200202_33_dialog_content = "Ditambah sekelompok orang luar juga.",
  ui_story_5020_50200202_34_dialog_content = "Apa sebaiknya kita mengikuti mereka?",
  ui_story_5020_50200202_35_dialog_content = "Mereka sepertinya tidak mempercayai kita... Apa yang harus kita lakukan?",
  ui_story_5020_50200202_36_dialog_content = "Untuk apa kalian ragu-ragu segala?! Ini situasi genting!",
  ui_story_5020_50200202_37_dialog_content = "<size=45>Apa yang para hantu ini lakukan di sini?!</size>",
  ui_story_5020_50200202_38_dialog_content = "Hai! PlayerName! Mengapa Anda dan yang lainnya belum melarikan diri?",
  ui_story_5020_50200202_39_dialog_content = "Mereka membalik semua kios! Mundur! Mundur!",
  ui_story_5020_50200202_40_dialog_content = "Tunggu! Kembali kemari, kalian berdua!",
  ui_story_5020_50200202_41_dialog_content = "Momo! Anzu! Kami benar-benar butuh bantuan kalian sekarang!",
  ui_story_5020_50200202_42_dialog_content = "Aku yakin kita bisa bicara nanti, kan!?",
  ui_story_5020_50200202_43_dialog_content = "Itu benar! Saat ini, yang terpenting adalah berlari!!",
  ui_story_5020_50200202_44_dialog_content = "Cukup! Tenangkan diri kalian!",
  ui_story_5020_50200202_45_dialog_content = "Kalian ingin bisnis tetap berjalan lancar, 'kan?",
  ui_story_5020_50200202_46_dialog_content = "<size=45>Benar!</size>",
  ui_story_5020_50200202_47_dialog_content = "Anda ingin menjadi pemilik restoran terbaik di seluruh Cloud Island, bukan?",
  ui_story_5020_50200202_48_dialog_content = "<size=45>Benar!</size>",
  ui_story_5020_50200202_49_dialog_content = "Kalau begitu, gunakan semangatmu yang biasa... ehem... untuk memimpin semua orang ini ke tempat yang aman.",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>Lewat sini, semuanya! Ayo cepat!!!</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "Aduh, telingaku...",
  ui_story_5020_50200301_1_dialog_content = "Kubou-sama, ada beberapa pedagang yang menunggu di luar kastil utama. Mereka mencari audiens Anda.",
  ui_story_5020_50200301_2_dialog_content = "Sekarang, sepanjang masa? Bukankah seharusnya mereka menjajakan dagangannya di jalanan malam ini?",
  ui_story_5020_50200301_3_dialog_content = "Baiklah, suruh mereka masuk.",
  ui_story_5020_50200301_4_dialog_content = "Jenderal Kubou! Anda harus menyelamatkan kami!",
  ui_story_5020_50200301_5_dialog_content = "Tidak usah bersikap formal, katakan apa yang terjadi.",
  ui_story_5020_50200301_6_dialog_content = "Tuanku, Anda pasti belum dengar! Sakai diserang hantu!",
  ui_story_5020_50200301_7_dialog_content = "Itu benar! Itu benar!",
  ui_story_5020_50200301_8_dialog_content = "Kios kami hancur berkeping-keping! Kita semua kehilangan banyak uang malam ini...",
  ui_story_5020_50200301_9_dialog_content = "Festival Kasuga tidak akan sama tahun ini...",
  ui_story_5020_50200301_10_dialog_content = "*Berdehem* Apa ini benar-benar waktu yang tepat untuk keluh kesah sepele kalian? Diam, kalian semua!",
  ui_story_5020_50200301_11_dialog_content = "Maafkan kami, Jenderal Kubou. Tapi, kami datang untuk melapor sesegera mungkin.",
  ui_story_5020_50200301_12_dialog_content = "Benarkah itu?",
  ui_story_5020_50200301_13_dialog_content = "Maafkan aku, Kubou-sama, tapi para penjaga saat ini—",
  ui_story_5020_50200301_14_dialog_content = "Kirim mereka ke Sakai, sekarang!",
  ui_story_5020_50200301_15_dialog_content = "Jika masalah terus berlanjut, nyawa kalian taruhannya!",
  ui_story_5020_50200301_16_dialog_content = "Ya!",
  ui_story_5020_50200301_17_dialog_content = "Terima kasih banyak, Tuanku!",
  ui_story_5020_50200301_18_dialog_content = "Kegagalan bawahanku adalah tanggung jawabku. Justru aku yang harus meminta maaf kepada kalian semua.",
  ui_story_5020_50200301_19_dialog_content = "Sama sekali tidak!",
  ui_story_5020_50200301_20_dialog_content = "Sebenarnya, aku ingat betul tadi aku melihat Rinne di kota, mengevakuasi orang-orang ke tempat yang aman.",
  ui_story_5020_50200301_21_dialog_content = "Oh? Rinne ada di kota?",
  ui_story_5020_50200301_22_dialog_content = "Ya! Rinne-sama pasti telah mempersiapkan Perayaan Malam, karena dia telah menanggapi serangan itu dengan sangat cepat.",
  ui_story_5020_50200301_23_dialog_content = "Kehadiran heroiknya menyentuh kita semua!",
  ui_story_5020_50200301_24_dialog_content = "Karena terharu, kami jadi tergerak untuk membantu.",
  ui_story_5020_50200301_25_dialog_content = "Saking sibuknya menolong kami, sepertinya dia jadi tidak sempat melapor. Karena itu, kami memutuskan untuk memberi tahu Anda. Mohon maafkan kami, Jenderal Kubou!",
  ui_story_5020_50200301_26_dialog_content = "Tak ada yang perlu dimaafkan. Tindakan kalian semua sudah benar.",
  ui_story_5020_50200301_27_dialog_content = "Saya yakin pasukan pemberontak yang harus disalahkan karena memimpin hantu ke kota. Mereka harus berusaha menggunakan kekacauan untuk melanjutkan rencana mereka, bahkan dengan mengorbankan keselamatan rakyat.",
  ui_story_5020_50200301_28_dialog_content = "Tapi, jangan takut. Para penjaga sedang dalam perjalanan, keselamatan kalian akan terjamin.",
  ui_story_5020_50200301_29_dialog_content = "Cloud Island diberkati memilikimu, Kubou-sama!",
  ui_story_5020_50200301_30_dialog_content = "Kami akan pergi sekarang.",
  ui_story_5020_50200301_31_dialog_content = "Orang-orang di Cloud Island tidak mengerti arti perdamaian... yang mereka tahu hanyalah menuntut tanpa henti.",
  ui_story_5020_50200301_32_dialog_content = "Untuk mewujudkan keinginannya, pengorbanan tertentu harus dilakukan.",
  ui_story_5020_50200301_33_dialog_content = "Namun, yang lebih mengejutkan adalah bahwa <color=#FFB400>Gumpalan</color> belum bergerak.",
  ui_story_5020_50200301_34_dialog_content = "Apa Nagi sudah ditemukan?",
  ui_story_5020_50200301_35_dialog_content = "Belum.",
  ui_story_5020_50200301_36_dialog_content = "<size=45>Dasar orang-orang bodoh tak berguna!</size>",
  ui_story_5020_50200301_37_dialog_content = "Maafkan saya, Kubou-sama.",
  ui_story_5020_50200301_38_dialog_content = "Bawa pasukan hantu ke Sakai. Itu seharusnya menarik mereka keluar.",
  ui_story_5020_50200301_39_dialog_content = "Kita harus mengakhirinya hari ini untuk selamanya.",
  ui_story_5020_50200301_40_dialog_content = "Festival Kasuga harus terus berlanjut tanpa insiden.",
  ui_story_5020_50200301_41_dialog_content = "Aku mengerti.",
  ui_story_5020_50200301_42_dialog_content = "Rinne benar-benar seperti dirimu.",
  ui_story_5020_50200301_43_dialog_content = "Kalau saja kamu masih di sini... Aku yakin kamu akan sangat menyukainya.",
  ui_story_5020_50200301_44_dialog_content = "Sejak hari kepergianmu, aku menaruh semua harapanku untuk membesarkan seorang pendeta baru.",
  ui_story_5020_50200301_45_dialog_content = "Tapi, mau dilihat dari sudut mana pun, seluruh usahaku jelas sia-sia.",
  ui_story_5020_50200301_46_dialog_content = "Bagaimanapun, Anda adalah orang yang spesial.",
  ui_story_5020_50200301_47_dialog_content = "Tapi, tenang saja. Akan kupenuhi janjiku padamu.",
  ui_story_5020_50200301_48_dialog_content = "Ini keinginanmu... Dan juga keinginanku.",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>Graah!</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "Jumlah mereka terlalu banyak!",
  ui_story_5020_50200301_51_dialog_content = "Apa Jenderal Fujikumo benar-benar hanya mau diam saja dan menyaksikan semua orang tewas?",
  ui_story_5020_50200301_52_dialog_content = "Rapid Torrent—",
  ui_story_5020_50200301_53_dialog_content = "Para hantu ini makin kuat...",
  ui_story_5020_50200301_54_dialog_content = "Harus fokus... Prioritas utama kita adalah mengeluarkan warga sipil dari sini.",
  ui_story_5020_50200301_55_dialog_content = "Rinne... Vice... Bertahanlah sebentar lagi!",
  ui_story_5020_50200302_1_dialog_content = "Kuharap keadaan Momo dan Anzu lebih baik...",
  ui_story_5020_50200302_2_dialog_content = "<size=33>PlayerName!</size>",
  ui_story_5020_50200302_3_dialog_content = "Apa barusan ada yang memanggilku?",
  ui_story_5020_50200302_4_dialog_content = "Hah? Saya tidak mendengar apa-apa.",
  ui_story_5020_50200302_5_dialog_content = "PlayerName!!",
  ui_story_5020_50200302_6_dialog_content = "Sebentar, sepertinya aku dengar.",
  ui_story_5020_50200302_7_dialog_content = "Tampaknya ada orang yang berusaha kemari!",
  ui_story_5020_50200302_8_dialog_content = "<size=50>PlayerName!!!</size>",
  ui_story_5020_50200302_9_option_content = "Momo?!",
  ui_story_5020_50200302_10_dialog_content = "Bukankah Anda seharusnya mengevakuasi warga sipil dengan Anzu?",
  ui_story_5020_50200302_11_option_content = "Anzu?!",
  ui_story_5020_50200302_12_dialog_content = "Bukankah kamu seharusnya mengevakuasi warga sipil dengan Momo?",
  ui_story_5020_50200302_13_dialog_content = "TIDAK, PlayerName! Saya Momo!",
  ui_story_5020_50200302_14_dialog_content = "Oh! M-Maaf soal itu... Hanya saja kalian berdua terlihat sangat mirip.",
  ui_story_5020_50200302_15_dialog_content = "Apa yang kamu lakukan di sini? Di mana Anzu dan warga sipil?",
  ui_story_5020_50200302_16_dialog_content = "Aku disini!",
  ui_story_5020_50200302_17_dialog_content = "Kenapa kalian berdua malah membawa semua orang kembali kemari?!",
  ui_story_5020_50200302_18_dialog_content = "Kami tak bisa pergi! Saat kalian menjaga bagian belakang, lebih banyak hantu muncul di depan kami!",
  ui_story_5020_50200302_19_dialog_content = "Kami benar-benar terkepung!",
  ui_story_5020_50200302_20_dialog_content = "\"Dalam masa-masa sulit ini, kita semua harus memotong jalan kita sendiri menuju kemenangan!\"",
  ui_story_5020_50200302_21_dialog_content = "Kenapa rasanya aku pernah dengar, ya?",
  ui_story_5020_50200302_22_dialog_content = "Benarkah?",
  ui_story_5020_50200302_23_dialog_content = "Saya membolak-balik Panduan Perjalanan Pulau Cloud Yao beberapa waktu lalu.",
  ui_story_5020_50200302_24_dialog_content = "Ini adalah salah satu slogan yang digunakan di bagian Mode brosur.",
  ui_story_5020_50200302_25_dialog_content = "Untuk mengatakan yang sebenarnya, Rinne... Saya tidak berpikir itu benar-benar gaya Anda ...",
  ui_story_5020_50200302_26_dialog_content = "Benarkah? Padahal tadinya kupikir itu terdengar sangat keren!",
  ui_story_5020_50200302_27_dialog_content = "Hanya saja untuk beberapa alasan aneh ...",
  ui_story_5020_50200302_28_dialog_content = "Saya tidak bisa mendapatkan gambarannya Sinsa berpakaian seperti samurai Cloud Island yang nakal dari kepalaku.",
  ui_story_5020_50200302_29_dialog_content = "Kalau dipikir-pikir... aku juga bisa membayangkannya.",
  ui_story_5020_50200302_30_dialog_content = "Baiklah! Saatnya membuka jalan kita sendiri menuju kemenangan!",
  ui_story_5020_50200302_31_dialog_content = "Ayo tangkap mereka, prajurit!",
  ui_story_5020_50200302_32_dialog_content = "Serang!!!",
  ui_story_5020_50200302_33_dialog_content = "A-apa-apaan ini...?!",
  ui_story_5020_50200302_34_dialog_content = "Benarkah bantuan seperti ini yang bisa diberikan Jenderal Fujikumo?",
  ui_story_5020_50200302_35_dialog_content = "Menilai dari pakaian mereka, saya kira mereka orang biasa.",
  ui_story_5020_50200302_36_dialog_content = "Mereka pemberontak.",
  ui_story_5020_50200302_37_dialog_content = "Itu <color=#FFB400>Gumpalan</color> untuk Anda, terima kasih banyak!",
  ui_story_5020_50200302_38_dialog_content = "Sekarang siapa kamu?",
  ui_story_5020_50200302_39_dialog_content = "Kami...",
  ui_story_5020_50200302_40_dialog_content = "Seorang pendeta dan dua orang asing, ya?",
  ui_story_5020_50200302_41_dialog_content = "Tangkap mereka!",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>Hatsyiii!</anim>",
  ui_story_5020_50200401_2_dialog_content = "Aduh... Pasti ada orang yang menjelek-jelekanku sekarang.",
  ui_story_5020_50200401_3_dialog_content = "Kakiku jadi mati rasa gara-gara jongkok terus... Tapi, sepertinya sekarang di luar sudah cukup aman.",
  ui_story_5020_50200401_4_dialog_content = "Ah, jauh lebih baik! Sedikit peregangan selalu berhasil!",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50200401_6_dialog_content = "Bagaimana hantu-hantu ini bisa masuk ke dalam Main Castle?",
  ui_story_5020_50200401_7_dialog_content = "<size=45>Hoo-ah!</size>",
  ui_story_5020_50200401_8_dialog_content = "Si tua bangka itu kenapa, sih? Memangnya melindungi Main Castle saja dia tidak becus?",
  ui_story_5020_50200401_9_dialog_content = "Dan sekarang tatanan rambutku hancur! Kutukan... Apa kau tahu berapa lama untuk mengikatnya seperti ini?!",
  ui_story_5020_50200401_10_dialog_content = "Selain itu... sekarang aku di mana, sih?",
  ui_story_5020_50200401_11_dialog_content = "Kastel ini sangat besar... Kenapa setiap lantai terasa sama persis?",
  ui_story_5020_50200401_12_dialog_content = "Apa aku sudah ke lorong ini tadi?",
  ui_story_5020_50200401_13_dialog_content = "Ugh, tidak ada gunanya... Aku harus meninggalkan spidol atau semacamnya.",
  ui_story_5020_50200401_14_dialog_content = "Wah, ini salah satu hantu yang kekar... Kamu pasti makan banyak di waktu luangmu, ya?",
  ui_story_5020_50200401_15_dialog_content = "Nah, kalau aku membuatnya berdiri seperti ini... Membuat lengannya jadi seperti itu... Dan membuat jari-jarinya menunjuk ke arah itu...",
  ui_story_5020_50200401_16_dialog_content = "Voila! Sekarang aku tahu ke arah mana aku pergi!",
  ui_story_5020_50200401_17_dialog_content = "Tapi... Aduh, baunya sangat busuk.",
  ui_story_5020_50200401_18_dialog_content = "... Dimana pintu keluarnya?! Aku tidak ingin menyentuh hantu lagi!!",
  ui_story_5020_50200401_19_dialog_content = "Argh, ini sangat menjijikkan! Aku bersumpah, aku akan mandi setidaknya sepuluh kali begitu aku kembali!",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>Gong...!</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>Gong, Gong...!</color>",
  ui_story_5020_50200401_22_dialog_content = "Sial... Apakah itu suara dari drum taiko Rinne bicarakan sebelumnya?",
  ui_story_5020_50200401_23_dialog_content = "Sudah berapa lama aku terjebak di sini?!",
  ui_story_5020_50200401_24_dialog_content = "Grr... Kumpulkan, Yao! Ayo otak, kita harus memikirkan sesuatu!",
  ui_story_5020_50200401_25_dialog_content = "PlayerName selalu berkata bahwa aku harus mengandalkan intuisiku.",
  ui_story_5020_50200401_26_dialog_content = "Intuisiku bilang aku harus ke arah ini...",
  ui_story_5020_50200401_27_dialog_content = "Sekarang ia bilang aku harus belok kiri...",
  ui_story_5020_50200401_28_dialog_content = "J-Hanya harus terus belok kanan! Aku yakin aku belum pernah seperti ini sebelumnya...",
  ui_story_5020_50200401_29_dialog_content = "...",
  ui_story_5020_50200401_30_dialog_content = "PlayerName, kamu pembohong! Intuisiku sama sekali tidak berguna!!",
  ui_story_5020_50200401_31_dialog_content = "Ah, sudahlah.",
  ui_story_5020_50200401_32_dialog_content = "Daripada membentur-benturkan kepalaku ke dinding begini, sebaiknya kuikuti tindakan Master dan terjun saja dari Cloud Pavillion.",
  ui_story_5020_50200401_33_dialog_content = "Baiklah! Sepertinya itu rencana yang bagus!",
  ui_story_5020_50200401_34_dialog_content = "Benar... Dari atas sini...",
  ui_story_5020_50200401_35_dialog_content = "Sama sekali tidak terlihat tinggi!",
  ui_story_5020_50200401_36_dialog_content = "Tuan mungkin menggunakan pohon ceri itu untuk mematahkan kejatuhannya ... kan?",
  ui_story_5020_50200401_37_dialog_content = "Baiklah, pohon sakura... Siap atau tidak, aku datang!",
  ui_story_5020_50200401_38_dialog_content = "...",
  ui_story_5020_50200401_39_dialog_content = "Aku... aku tidak bisa melakukannya!!",
  ui_story_5020_50200401_40_dialog_content = "Saya tidak tahu bagaimana Guru melakukannya, tapi saya yakin tidak bisa!",
  ui_story_5020_50200401_41_dialog_content = "Maksudku, lihat seberapa jauh aku...",
  ui_story_5020_50200401_41X1_dialog_content = "Prajurit sejati tidak akan pernah melakukan apa pun yang mereka tidak yakin!",
  ui_story_5020_50200401_41X2_dialog_content = "B-biar kuperiksa kalau-kalau ada tali atau sesuatu yang bisa kupakai turun...",
  ui_story_5020_50200401_41X3_dialog_content = "Ahh... Satu-satunya tempat untuk menyembunyikan sesuatu di ruang ini adalah...",
  ui_story_5020_50200401_41X4_dialog_content = "Lemari!",
  ui_story_5020_50200401_41X5_dialog_content = "Hmm?",
  ui_story_5020_50200401_41X6_dialog_content = "Apa katamu?",
  ui_story_5020_50200401_41X7_dialog_content = "Kenapa rasanya sangat <color=#FFB400>familiar</color>, ya?",
  ui_story_5020_50200401_41X8_dialog_content = "Ah, sudahlah! Biar kubuka dulu saja lemari itu. Siapa tahu ada tali!",
  ui_story_5020_50200401_42_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5020_50200401_44_dialog_content = "Hah?!",
  ui_story_5020_50200401_45_dialog_content = "Kagura Bell?",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding!</color>",
  ui_story_5020_50200401_47_dialog_content = "Ohh... Ada <color=#FFB400>genta angin</color> di dalam lemari?",
  ui_story_5020_50200401_48_dialog_content = "Aneh... Kenapa suaranya terdengar seperti Kagura Bell?",
  ui_story_5020_50200401_49_dialog_content = "Sebentar... Ini...",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>Sepuluh tahun lalu.</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5020_50200401_52_dialog_content = "Ssst! Diam, Yao! Tetap di dalam, dan jangan bersuara!",
  ui_story_5020_50200401_53_dialog_content = "Apa yang terjadi di luar, Tsuki? Saya ketakutan...",
  ui_story_5020_50200401_54_dialog_content = "Anda tidak akan meninggalkan saya di sini sendirian, bukan?",
  ui_story_5020_50200401_55_dialog_content = "Kumohon, Tsuki...",
  ui_story_5020_50200401_56_dialog_content = "Tidurlah sebentar di dalam ini <color=#FFB400>pakaian</color>, dan semuanya akan baik-baik saja saat Anda bangun. Saya berjanji.",
  ui_story_5020_50200401_57_dialog_content = "Tsuki...",
  ui_story_5020_50200401_58_dialog_content = "<size=45>Buka!</size>",
  ui_story_5020_50200401_58X1_dialog_content = "(Ada orang yang berusaha masuk!)",
  ui_story_5020_50200401_58X2_dialog_content = "Ayo! Jaga gerbangnya! Jangan sampai ada energi jahat yang masuk kemari!",
  ui_story_5020_50200401_58X3_dialog_content = "\"Sebuah ode untuk orang mati dan hidup. Semoga lagu ini membimbing jiwamu kembali ke tempat yang seharusnya...\"",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>Ding... Ding...</color>",
  ui_story_5020_50200401_58X5_dialog_content = "(Nyanyian Kagura Bell itu mengusir hantu...!)",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5020_50200401_59_dialog_content = "Berhenti! Siapa kau?! Kau tidak boleh...",
  ui_story_5020_50200401_60_dialog_content = "<size=45>Pergi!</size>",
  ui_story_5020_50200401_61_dialog_content = "(Suara itu... Master?)",
  ui_story_5020_50200401_62_dialog_content = "Nagi?",
  ui_story_5020_50200401_63_dialog_content = "Jangan berani-berani memanggilku seperti itu, <color=#FFB400>Nyonya Pendeta</color>.",
  ui_story_5020_50200401_64_dialog_content = "Anda tidak pantas mendapatkannya.",
  ui_story_5020_50200401_65_dialog_content = "Katakan... Kenapa kau membujuk Wisp untuk menyerah?",
  ui_story_5020_50200401_66_dialog_content = "Kau berjanji padaku akan menjadi pendeta demi semua orang! Agar semua orang di Cloud Island hidup makmur!",
  ui_story_5020_50200401_67_dialog_content = "...",
  ui_story_5020_50200401_68_dialog_content = "Aku bertanya padamu!",
  ui_story_5020_50200401_69_dialog_content = "?!",
  ui_story_5020_50200401_70_dialog_content = "Tsuki!",
  ui_story_5020_50200401_71_dialog_content = "Kau sudah gila, Nagi?!",
  ui_story_5020_50200401_72_dialog_content = "Dia kakakmu!",
  ui_story_5020_50200401_73_dialog_content = "Penjaga! Bunuh dia sekarang!",
  ui_story_5020_50200401_74_dialog_content = "Tidak...!",
  ui_story_5020_50200401_75_dialog_content = "Kumohon, Jenderal Kubou... Jangan lakukan ini...",
  ui_story_5020_50200401_76_dialog_content = "Sungai di bawah kaki kita mengalir melalui ladang-ladang padi di barat kota...",
  ui_story_5020_50200401_77_dialog_content = "Taman yang terletak di kaki bukit sebelah barat... Bunga sakura putih di sana pasti sudah mekar penuh sekarang...",
  ui_story_5020_50200401_78_dialog_content = "Tolong jangan menodai kelopak indah mereka dengan warna darah...",
  ui_story_5020_50200401_79_dialog_content = "Kalau aku mati... kuburkan aku di bawah bunga sakura putih itu...",
  ui_story_5020_50200401_80_dialog_content = "Berjanjilah padaku... Mengerti?",
  ui_story_5020_50200401_81_dialog_content = "Bertahanlah, Tsuki! Aku berjanji, aku akan...",
  ui_story_5020_50200401_82_dialog_content = "\"Sebuah ode... untuk orang mati dan hidup...\"",
  ui_story_5020_50200401_83_dialog_content = "Tunggu... Apa yang kaulakukan?!",
  ui_story_5020_50200401_84_dialog_content = "Tsuki, tidak! Tubuhmu tidak akan kuat!",
  ui_story_5020_50200401_85_dialog_content = "\"Semoga lagu ini...\"",
  ui_story_5020_50200401_86_dialog_content = "\"Membimbing rohku kembali ke tempat yang seharusnya.\"",
  ui_story_5020_50200401_87_dialog_content = "Argh...!",
  ui_story_5020_50200401_88_dialog_content = "...",
  ui_story_5020_50200401_89_dialog_content = "...",
  ui_story_5020_50200401_90_dialog_content = "Bahkan setelah segala hal yang terjadi, kau masih ingin melindunginya...?",
  ui_story_5020_50200401_91_dialog_content = "Penjaga...",
  ui_story_5020_50200401_92_dialog_content = "Mulai sekarang, pasukan hantu akan menjaga wilayah ini untuk selama-lamanya.",
  ui_story_5020_50200401_93_dialog_content = "Kurung wanita ini selama sisa hidupnya yang menyedihkan agar dia tak pernah melihat cahaya matahari dengan matanya sendiri!",
  ui_story_5020_50200401_94_dialog_content = "Ya!",
  ui_story_5020_50200401_95_dialog_content = "Sisanya... akan dilakukan sesuai permintaan Tsuki.",
  ui_story_5020_50200401_96_dialog_content = "Siap, laksanakan.",
  ui_story_5020_50200401_97_dialog_content = "Nah, sekarang kau...",
  ui_story_5020_50200401_98_dialog_content = "Dia hanya ingin melindungimu, dan kau justru membunuhnya... Apa kau tak punya malu? Apa kau tak punya perasaan?!",
  ui_story_5020_50200401_99_dialog_content = "Aku tak pernah butuh perlindungannya, dan kau juga akan mati di tanganku, seperti dia.",
  ui_story_5020_50200401_100_dialog_content = "Selama ini kau pasti tidak bisa memahami kebenarannya, Nagi...",
  ui_story_5020_50200401_101_dialog_content = "Kau tidak bisa memahami alasan kenapa dia memutuskan untuk berpihak padaku.",
  ui_story_5020_50200401_102_dialog_content = "Justru karena aku memberinya semacam persetujuan diam-diam, dia jadi belajar tentang hal-hal yang seharusnya tak pernah dia ketahui.",
  ui_story_5020_50200401_103_dialog_content = "Perbedaan antara mengusir hantu dan mengendalikan mereka tidak sehebat kelihatannya, tapi hukum dan kebiasaan Cloud Island bisa dipahami melalui perbedaan ini.",
  ui_story_5020_50200401_104_dialog_content = "Menjaga perdamaian di Cloud Island adalah upaya seumur hidup. Dia memahami ini, serta posisiku, dan dengan patuh memercayaiku.",
  ui_story_5020_50200401_105_dialog_content = "Meskipun mengetahui apa yang dia pahami, dia memilih untuk melindungimu walau kau tak tahu apa-apa.",
  ui_story_5020_50200401_106_dialog_content = "Tidak... Kau salah!",
  ui_story_5020_50200401_107_dialog_content = "Tapi, memangnya ada kemungkinan lain?",
  ui_story_5020_50200401_108_dialog_content = "Ikatan persaudaraan yang sudah kauhancurkan?!",
  ui_story_5020_50200401_109_dialog_content = "Dia seumuran denganmu, namun matanya selalu penuh kasih sayang dan pengertian, kebijaksanaan yang jauh melampaui usianya...",
  ui_story_5020_50200401_110_dialog_content = "Namun... Anda membunuhnya!!!",
  ui_story_5020_50200401_111_dialog_content = "Anda mengambil nyawanya, dan harapan serta impiannya untuk Cloud Island bersamanya!!!",
  ui_story_5020_50200401_112_dialog_content = "Apa hakmu untuk hidup di dunia ini lebih lama lagi?!?!",
  ui_story_5020_50200401_113_dialog_content = "...",
  ui_story_5020_50200401_114_dialog_content = "<size=33>Kenapa dia memilih untuk melindungimu meski harus mengorbankan nyawanya...?!</size>",
  ui_story_5020_50200401_115_dialog_content = "Sungguh suatu kehormatan bagiku karena bisa mendengar pidato mengagumkan semacam itu!",
  ui_story_5020_50200401_116_dialog_content = "Memutar narasi eksploitasi Anda terhadapnya, menjadi kisah kepercayaan dan pengertian...",
  ui_story_5020_50200401_117_dialog_content = "Begitukah caramu memperdayanya?!",
  ui_story_5020_50200401_118_dialog_content = "Dia punya kebijaksanaan yang luar biasa.",
  ui_story_5020_50200401_119_dialog_content = "Di dalam hatinya, dia tahu bahwa tujuan kami berdua adalah untuk melindungi tempat ini dengan segala cara. Dengan demikian, kata eksploitasi tidak ada di antara kami.",
  ui_story_5020_50200401_120_dialog_content = "... Begitu rupanya. Segel yang dia pasang padamu memang hukuman yang setimpal.",
  ui_story_5020_50200401_121_dialog_content = "Semoga kau menghabiskan sisa umurmu di sini dengan seluruh kebencian dan amarahmu.",
  ui_story_5020_50200401_122_dialog_content = "Aku bersumpah akan membunuhmu suatu hari nanti!",
  ui_story_5020_50200401_123_dialog_content = "Yah, kita buktikan saja apakah hari itu akan tiba.",
  ui_story_5020_50200401_124_dialog_content = "Tsuki...?",
  ui_story_5020_50200401_125_dialog_content = "Masterku... adalah orang yang <size=45>membunuh pendeta itu?!</size>",
  ui_story_5020_50200401_126_dialog_content = "Tapi, masterku bukan orang semacam itu...",
  ui_story_5020_50200401_127_dialog_content = "Apa dulu kau juga memanfaatkannya seperti ini?",
  ui_story_5020_50200401_128_dialog_content = "Gadis kecil... Kau tak lebih dari sekadar alat untuk dimanfaatkan.",
  ui_story_5020_50200401_129_dialog_content = "Tahukah kau, apa yang terjadi pada pendeta terakhir sebelum dirimu?",
  ui_story_5020_50200401_130_dialog_content = "Tutup mulutmu!",
  ui_story_5020_50200401_131_dialog_content = "Penjaga, tangkap dia!",
  ui_story_5020_50200401_132_dialog_content = "Tidak... Pasti ada kesalahan.",
  ui_story_5020_50200401_133_dialog_content = "Argh... Kepalaku...",
  ui_story_5020_50200401_134_dialog_content = "Aku harus menemui PlayerName, dan memberi tahu mereka semua soal ini!",
  ui_story_5020_50200501_1_dialog_content = "Hai! Mari kita pergi! Tidak bisakah kita menggunakan kata-kata kita saja?",
  ui_story_5020_50200501_2_dialog_content = "Benar! Ini pasti salah paham!",
  ui_story_5020_50200501_3_dialog_content = "...",
  ui_story_5020_50200501_4_dialog_content = "Untuk sekarang, sepertinya kita aman di sini.",
  ui_story_5020_50200501_5_dialog_content = "Bantu semua orang beradaptasi.",
  ui_story_5020_50200501_6_dialog_content = "Ya!",
  ui_story_5020_50200501_7_dialog_content = "Nah, soal orang-orang cerewet itu...",
  ui_story_5020_50200501_8_dialog_content = "Ikat saja mereka di suatu tiang.",
  ui_story_5020_50200501_9_dialog_content = "Apa!?",
  ui_story_5020_50200501_10_dialog_content = "Ya!",
  ui_story_5020_50200501_11_dialog_content = "Hei! Berhenti menggeliat-geliut!",
  ui_story_5020_50200501_12_dialog_content = "Aduh... Orang-orang ini...",
  ui_story_5020_50200501_13_dialog_content = "Sebentar, ada yang tidak kumengerti!",
  ui_story_5020_50200501_14_dialog_content = "Kalian melindungi warga sipil, kan? Kita juga! Bukankah itu berarti kita berada di halaman yang sama?",
  ui_story_5020_50200501_15_dialog_content = "Sama sekali tidak.",
  ui_story_5020_50200501_16_dialog_content = "Kalian berada di pihak pendeta itu, jadi artinya kita adalah musuh.",
  ui_story_5020_50200501_17_dialog_content = "Pendeta? Memangnya apa hubungannya dia dengan ini...?",
  ui_story_5020_50200501_18_dialog_content = "Aku mengerti.",
  ui_story_5020_50200501_19_dialog_content = "Kalau aku tidak salah, Amemori adalah anggota kalian. Benar, 'kan?",
  ui_story_5020_50200501_20_dialog_content = "Ingat posisimu, Pendeta.",
  ui_story_5020_50200501_21_dialog_content = "Anda tidak dalam posisi untuk mengajukan pertanyaan apa pun kepada kami.",
  ui_story_5020_50200501_22_dialog_content = "Heh... Sepertinya ini bukan giliranku untuk bicara.",
  ui_story_5020_50200501_23_dialog_content = "Mungkin kami harus menunggu Anda memperkenalkan diri?",
  ui_story_5020_50200501_24_dialog_content = "Atau mungkin mendengar pidato rekrutmenmu...?",
  ui_story_5020_50200501_25_dialog_content = "Hahahaha! Wah, wah, rupanya pendeta ini punya selera humor, ya?",
  ui_story_5020_50200501_26_dialog_content = "Siapa yang tahu suatu hari akan tiba ketika seorang pendeta Cloud Island bahkan tidak tahu siapa Wisp itu.",
  ui_story_5020_50200501_27_dialog_content = "Siapa tahu, mungkin dalam beberapa generasi, bahkan Cloud Island sendiri akan dilupakan!",
  ui_story_5020_50200501_28_dialog_content = "Pada akhirnya, tidak ada yang penting bagi Anda.",
  ui_story_5020_50200501_29_dialog_content = "Tugasmu sebagai pendeta hanyalah berdiam di kastel besar yang nyaman, dan menghabiskan waktu dengan mengkhawatirkan pendapat Jenderal Kubou-mu.",
  ui_story_5020_50200501_30_dialog_content = "...",
  ui_story_5020_50200501_31_dialog_content = "Itu berlebihan!",
  ui_story_5020_50200501_32_dialog_content = "Selama ini Rinne melindungi penduduk Koufu-jou! Kalian juga melihatnya sendiri!",
  ui_story_5020_50200501_33_dialog_content = "Melindungi? Hentikan omonganmu yang muluk-muluk itu, orang asing.",
  ui_story_5020_50200501_34_dialog_content = "Dia tidak lebih dari kucing rumahan, mengejar dan membunuh tikus rumahan.",
  ui_story_5020_50200501_35_dialog_content = "Itu bukan perlindungan. Ini pertunjukan.",
  ui_story_5020_50200501_36_dialog_content = "Pertunjukan? Maksudmu apa, hah...?",
  ui_story_5020_50200501_37_dialog_content = "Biar kutanya, menurutmu dari mana hantu-hantu ini berasal?",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_39_dialog_content = "Anda ahli dalam hal ini, bukan, pendeta? Ingin menjelaskan?",
  ui_story_5020_50200501_40_dialog_content = "... Ketika ada kelimpahan energi Yin, jiwa orang mati tidak dapat dikuburkan, dan sebaliknya kembali sebagai hantu pendendam.",
  ui_story_5020_50200501_41_dialog_content = "Jadi beri tahu kami, dari mana datangnya energi Yin yang melimpah ini? Kehabisan udara?",
  ui_story_5020_50200501_42_dialog_content = "...",
  ui_story_5020_50200501_43_dialog_content = "Diam saja, ya? Jangan khawatir, aku sudah tahu jawabannya: ada <color=#FFB400>dalang</color> di baliknya.",
  ui_story_5020_50200501_44_dialog_content = "Sejak zaman kuno, Cloud Island telah menjadi rumah bagi tiga orang <color=#FFB400>artefak spiritual</color>.",
  ui_story_5020_50200501_45_dialog_content = "<color=#FFB400>Sepotong Surga</color>, pedang pembunuh hantu dan sumber energi Yang, saat ini hilang.",
  ui_story_5020_50200501_46_dialog_content = "<color=#FFB400>Pemberontakan dan Ryojin</color>, batu giok yang menyeimbangkan Yin dan Yang, dimiliki Wisp.",
  ui_story_5020_50200501_47_dialog_content = "Dan <color=#FFB400>Cermin Awan</color>, sumber energi Yin, selalu berada di tangan sang jenderal.",
  ui_story_5020_50200501_48_dialog_content = "Itu cermin yang Jenderal curi dari Rinne...",
  ui_story_5020_50200501_49_dialog_content = "\"Saat awan gelap menutupi matahari, para penghuni neraka menyeberang ke dunia orang hidup.\"",
  ui_story_5020_50200501_50_dialog_content = "Yang bisa memanggil hantu sebanyak itu untuk mengamuk di kota... hanyalah <color=#FFB400>Cloud Mirror</color>.",
  ui_story_5020_50200501_51_dialog_content = "Katakan, menurutmu siapa dalang di balik semua ini? Sekarang kalian pasti juga bisa menebaknya.",
  ui_story_5020_50200501_52_dialog_content = "... Sebenarnya, kami juga berpikir demikian.",
  ui_story_5020_50200501_53_dialog_content = "Tapi, masih ada sesuatu yang tak bisa kupahami.",
  ui_story_5020_50200501_54_dialog_content = "Jika Fujikumo bisa mengendalikan hantu sesuai keinginannya, mengapa dia terus membesarkan dan melatih para pendeta untuk mengusir mereka?",
  ui_story_5020_50200501_55_dialog_content = "Bukannya aku sudah bilang? Itu hanya sekadar pertunjukan.",
  ui_story_5020_50200501_56_dialog_content = "Kemunculan para hantu itu di sini adalah karena perintahnya. Si pendeta hanya boneka yang dimanfaatkan untuk mendapatkan hati rakyat dan mengendalikan mereka.",
  ui_story_5020_50200501_57_dialog_content = "Mengendalikan mereka?",
  ui_story_5020_50200501_58_dialog_content = "Jenderal itu mengendalikan para hantu, yang dia gunakan untuk menakuti-nakuti penduduk Cloud Island.",
  ui_story_5020_50200501_59_dialog_content = "Tapi, rasa takut bukanlah cara untuk menguasai Cloud Island. Pemimpin sejati mana pun juga tahu.",
  ui_story_5020_50200501_60_dialog_content = "Nah, lalu di situlah peran si pendeta. Mereka dilatih untuk menghadapi rasa takut ini demi rakyat.",
  ui_story_5020_50200501_61_dialog_content = "Orang-orang mengandalkan si pendeta, dan dia hanya tunduk pada Jenderal. Begitulah caranya menguasai kami semua.",
  ui_story_5020_50200501_62_dialog_content = "Sial baginya, dia melebih-lebihkan dirinya sendiri.",
  ui_story_5020_50200501_63_dialog_content = "Penduduk Cloud Island tidak bodoh. Kami tak akan tertipu oleh penyesatan tindakan yang tidak penting seperti ini.",
  ui_story_5020_50200501_64_dialog_content = "Kalian, para pendeta, beranggapan bahwa mengusir hantu bisa mengembalikan stabilitas negeri ini... Tapi, kenapa ancaman para hantu tak pernah mereda setelah sekian lama?",
  ui_story_5020_50200501_65_dialog_content = "...",
  ui_story_5020_50200501_66_dialog_content = "Tempat ini tidak selalu bernama Koufu-jou. Kami belum lupa.",
  ui_story_5020_50200501_67_dialog_content = "Tak peduli berapa banyak kastel yang mereka dirikan, atau berapa besar kekayaan yang mereka tawarkan...",
  ui_story_5020_50200501_68_dialog_content = "Bagi kami, mereka akan selalu jadi penjajah.",
  ui_story_5020_50200501_69_dialog_content = "Wisp adalah satu-satunya penjaga Cloud Island yang sebenarnya.",
  ui_story_5020_50200501_70_dialog_content = "Karena hanya kami asli tanah ini.",
  ui_story_5020_50200501_71_dialog_content = "Penjajah? Begitukah pendapat kalian tentang orang-orang di pulau utama...?",
  ui_story_5020_50200501_72_dialog_content = "Kurasa kalian belum banyak mempelajari sejarah Cloud Island.",
  ui_story_5020_50200501_73_dialog_content = "Dan itu masuk akal. Maksud saya, di mana Anda bisa mempelajarinya?",
  ui_story_5020_50200501_74_dialog_content = "(Aku sedikit mempelajari sejarah Cloud Island dari Anzu dan Momo...)",
  ui_story_5020_50200501_75_dialog_content = "(Tapi, mungkin ada perbedaan penting dalam versi Wisp?)",
  ui_story_5020_50200501_76_dialog_content = "Kamu benar. Kami sama sekali tidak tahu banyak tentang Cloud Island, karena kami berasal dari suatu tempat yang jauh.",
  ui_story_5020_50200501_77_dialog_content = "Sudah kuduga. Biar kujelaskan beberapa poinnya yang lebih penting. Anggap saja ini sedikit tindakan belas kasihan.",
  ui_story_5020_50200501_78_dialog_content = "Bertahun-tahun yang lalu, sebelum samurai dari pulau utama menginjakkan kaki di Cloud Island, itu adalah tempat yang jauh lebih indah daripada sekarang.",
  ui_story_5020_50200501_79_dialog_content = "Tempat yang makmur, bebas konflik, dan jarang ada hantu muncul untuk meneror negeri.",
  ui_story_5020_50200501_80_dialog_content = "Asal-usul Wisp bisa dilacak hingga ke masa itu. Dulu, melawan para hantu dan menjaga kedamaian di Cloud Island adalah misi suci kami.",
  ui_story_5020_50200501_81_dialog_content = "Tapi yang akhirnya merusak kedamaian itu bukanlah hantu, tapi yang hidup.",
  ui_story_5020_50200501_82_dialog_content = "Tidak pernah puas dengan tanah yang sudah mereka duduki, pulau utama mengirimkan jenderal pertamanya untuk menaklukkan tempat ini.",
  ui_story_5020_50200501_83_dialog_content = "Wisp belum pernah mengobarkan perang melawan yang hidup sebelumnya, tetapi mereka tetap mempertaruhkan nyawa mereka.",
  ui_story_5020_50200501_84_dialog_content = "Jenderal meluncurkan kampanye melawan Cloud Island, namun dia tidak pernah bisa mencaplok kami sepenuhnya.",
  ui_story_5020_50200501_85_dialog_content = "Tapi suatu hari, mereka menyusun rencana mereka yang paling tercela. Mereka mulai belajar bagaimana mengendalikan hantu, sehingga mereka bisa menggunakan kekuatan jahat mereka dalam pertempuran.",
  ui_story_5020_50200501_86_dialog_content = "Di masa-masa itu, jumlah hantu yang bergentayangan sangat banyak.",
  ui_story_5020_50200501_87_dialog_content = "Kami hancur di bawah ancaman hantu, bersama dengan kedaulatan Cloud Island. Segera setelah itu, sang jenderal membangun Koufu-jou di sepanjang lautan, dan menetapkannya sebagai pusat kekuasaannya.",
  ui_story_5020_50200501_88_dialog_content = "Karena tak punya pilihan lain, sisa-sisa Wisp terpaksa bersembunyi. Mereka menyembunyikan kemarahan pada para penjajah dan menyebarkan kebencian itu dari generasi ke generasi.",
  ui_story_5020_50200501_89_dialog_content = "Ada satu hal yang kami pelajari dari perang, yaitu menunggu kesempatan yang tepat. Hanya dengan begitu Cloud Island bisa mendapatkan kembali segala hal yang hilang darinya bertahun-tahun lalu.",
  ui_story_5020_50200501_90_dialog_content = "(Jadi begitulah konflik di Cloud Island terjadi...?)",
  ui_story_5020_50200501_91_dialog_content = "(Dari luar, ini adalah perang antara manusia dan hantu. Tapi, kenyataannya ini adalah perang antara dua bangsa yang berbeda...)",
  ui_story_5020_50200501_92_dialog_content = "Dan kesempatan ini...",
  ui_story_5020_50200501_93_dialog_content = "Mungkin akan segera datang.",
  ui_story_5020_50200501_94_dialog_content = "Sekarang semua orang sudah aman, Pak.",
  ui_story_5020_50200501_95_dialog_content = "Selanjutnya, kita harus...",
  ui_story_5020_50200501_96_dialog_content = "Aku mengerti. Kita bicara di sana saja.",
  ui_story_5020_50200501_97_dialog_content = "...",
  ui_story_5020_50200501_98_dialog_content = "Menurutmu, apa dia mengatakan yang sebenarnya tentang sejarah Cloud Island?",
  ui_story_5020_50200501_99_dialog_content = "Entahlah... Banyak yang dikatakannya. Aku belum mencerna semuanya...",
  ui_story_5020_50200501_100_dialog_content = "Saya selalu berpikir saya mengindahkan urutan yang paling sederhana.",
  ui_story_5020_50200501_101_dialog_content = "Untuk mematuhi ayah angkatku, dan untuk melindungi rakyat Koufu-jou.",
  ui_story_5020_50200501_102_dialog_content = "Tapi, kalau perkataannya benar...",
  ui_story_5020_50200501_103_dialog_content = "Maka, ada keanehan di antara dua perintah itu.",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_105_dialog_content = "Segala yang telah kulakukan... Apa itu tidak lebih dari sekadar pertunjukan?",
  ui_story_5020_50200501_106_dialog_content = "K-kita tak perlu memercayai seluruh omongannya, 'kan?",
  ui_story_5020_50200501_107_dialog_content = "Maksudku, dia bahkan tak bisa membedakan kawan dan lawan. Lihat saja caranya mengikat kita!",
  ui_story_5020_50200501_108_dialog_content = "Iya, 'kan, PlayerName?",
  ui_story_5020_50200501_109_dialog_content = "Mengapa Anda terlihat seperti sedang zonasi?",
  ui_story_5020_50200501_110_dialog_content = "Ssst—",
  ui_story_5020_50200501_111_dialog_content = "Aku sedang berusaha menguping pembicaraan mereka...",
  ui_story_5020_50200501_112_dialog_content = "Menguping?!",
  ui_story_5020_50200501_113_dialog_content = "Kedengarannya seru! Aku ikut, dong!",
  ui_story_5020_50200501_114_dialog_content = "Baiklah. Sini, mendekatlah.",
  ui_story_5020_50200501_115_dialog_content = "Mm-hmm!",
  ui_story_5020_50200501_116_dialog_content = "Kita terjebak, Pak.",
  ui_story_5020_50200501_117_dialog_content = "Jalanan penuh hantu. Kami tak bisa menghubungi para anggota di tempat-tempat lain...",
  ui_story_5020_50200501_118_dialog_content = "Jadi begitu. Kami tidak akan kemana-mana, dan kami akan mempertahankan tempat ini dengan nyawa kami.",
  ui_story_5020_50200501_119_dialog_content = "Pak, Anda bilang Komandan Amemori berhasil menyelamatkan Komandan lama?",
  ui_story_5020_50200501_120_dialog_content = "Apa menurutmu... mereka akan datang untuk membantu kita?",
  ui_story_5020_50200501_121_dialog_content = "Tidak ada alasan untuk takut. Selama Pedang Dunia Bawah masih hidup dan sehat, apalagi hantu lagi?",
  ui_story_5020_50200501_122_dialog_content = "(Rupanya Amemori ada di pihak mereka!)",
  ui_story_5020_50200501_123_dialog_content = "(Benar... Kedengarannya dia punya jabatan tinggi dalam Wisp.)",
  ui_story_5020_50200501_124_dialog_content = "Dengar, Nak. Wisp belum pernah membutuhkan bantuan siapa pun dalam pertempuran.",
  ui_story_5020_50200501_125_dialog_content = "Bahkan jika Anda yang terakhir bertahan, Anda harus berjuang sampai titik darah penghabisan.",
  ui_story_5020_50200501_126_dialog_content = "Apa itu artinya...",
  ui_story_5020_50200501_127_dialog_content = "Ada urusan lain yang harus ditangani oleh Komandan lama dan Komandan Amemori.",
  ui_story_5020_50200501_128_dialog_content = "Aku tidak mencemaskannya, dan seharusnya begitu juga denganmu.",
  ui_story_5020_50200501_129_dialog_content = "(Oh, benar... Bagaimana keadaan Amemori sekarang, ya...?)",
  ui_story_5020_50200501_130_dialog_content = "(Tenang, dia pasti baik-baik saja. Lagi pula dia kan sangat kuat.)",
  ui_story_5020_50200501_131_dialog_content = "...",
  ui_story_5020_50200501_132_dialog_content = "Semua orang lega karena Komandan selamat, Pak.",
  ui_story_5020_50200501_133_dialog_content = "Hanya saja... kami belum pernah melihat wajah Komandan.",
  ui_story_5020_50200501_134_dialog_content = "Beberapa anggota kita mulai mempertanyakan kebenaran kabar itu.",
  ui_story_5020_50200501_135_dialog_content = "Beberapa orang bahkan berkata...",
  ui_story_5020_50200501_136_dialog_content = "Bahwa setelah sepuluh tahun, dia hampir melupakan Wisp...",
  ui_story_5020_50200501_137_dialog_content = "...",
  ui_story_5020_50200501_138_dialog_content = "Cukup.",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5020_50200501_140_dialog_content = "(?!)",
  ui_story_5020_50200501_141_dialog_content = "Ada apa?",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5020_50200501_143_dialog_content = "(Suaranya dekat! Sepertinya berasal dari sisi lain dinding!)",
  ui_story_5020_50200501_144_dialog_content = "Bersiaplah untuk bertempur.",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>Graaaah!!</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "Bagaimana mereka menemukan kita begitu cepat...?",
  ui_story_5020_50200501_148_dialog_content = "Ah, itu hanya masalah waktu, kurasa.",
  ui_story_5020_50200501_149_dialog_content = "Prajurit Wisp!",
  ui_story_5020_50200501_150_dialog_content = "Siap, Pak!!!",
  ui_story_5020_50200501_151_dialog_content = "Kerahkan keberanian kalian!",
  ui_story_5020_50200501_152_dialog_content = "Kita kembalikan setiap hantu itu ke bawah tanah!",
  ui_story_5020_50200501_153_dialog_content = "Celaka... Para hantu menemukan kita!",
  ui_story_5020_50200501_154_dialog_content = "Aku tahu! Sekarang kita harus bagaimana?!",
  ui_story_5020_50200501_155_dialog_content = "Kita tidak bisa melakukan apa-apa kalau terikat begini!",
  ui_story_5020_50200501_156_dialog_content = "<size=45>Hei! Cepat lepaskan kami!!!</size>",
  ui_story_5020_50200501_157_dialog_content = "<size=45>Kami bisa membantu kalian mengalahkan mereka!!!</size>",
  ui_story_5020_50200501_158_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200501_159_dialog_content = "Hei... Kalian dengar tidak?",
  ui_story_5020_50200501_160_dialog_content = "Bagaimana kalau kau memakai kemampuan psikismu?",
  ui_story_5020_50200501_161_dialog_content = "Oh, benar juga! Aku...",
  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50200501_164_dialog_content = "Gawat! Kenapa malah sekarang, sih...?",
  ui_story_5020_50200501_165_dialog_content = "Mereka makin dekat!",
  ui_story_5020_50200501_166_dialog_content = "Bahkan kalau aku memanggil petarung Wisp... Apakah mereka akan tiba tepat waktu?",
  ui_story_5020_50200501_167_dialog_content = "Coba saja!",
  ui_story_5020_50200501_168_dialog_content = "Heh... Kita hanya butuh mencari orang untuk membebaskan kita, 'kan?",
  ui_story_5020_50200501_169_dialog_content = "Kalau Wisp tidak mau membantu, kita terpaksa mengandalkan dia.",
  ui_story_5020_50200501_170_dialog_content = "Itu? Tunggu, kau tidak bermaksud...",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>Coo...</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "Serahkan pada hantu untuk memotong talinya?! Saya pikir kita akan dicabik-cabik dulu!",
  ui_story_5020_50200501_170X3_dialog_content = "Nah, maka Anda harus tetap rendah sejenak.",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>Uraaagh...</anim>",
  ui_story_5020_50200501_173_dialog_content = "Lihat, 'kan?",
  ui_story_5020_50200501_174_dialog_content = "Terkadang hantu lebih patuh ketimbang orang.",
  ui_story_5020_50200502_1_dialog_content = "Pak! Para hantu berdatangan dari segala arah!",
  ui_story_5020_50200502_2_dialog_content = "Kita terkepung!",
  ui_story_5020_50200502_3_dialog_content = "Serangan mendadak mereka barusan adalah untuk mengulur waktu untuk mengatur pengepungan mereka...",
  ui_story_5020_50200502_4_dialog_content = "Dengan taktik seperti itu, pasti ada sesuatu di balik semua ini.",
  ui_story_5020_50200502_5_dialog_content = "Apa maksud Anda, Pak...?",
  ui_story_5020_50200502_6_dialog_content = "Setelah bertahun-tahun melawan hantu, apakah Wisp pernah terdesak?",
  ui_story_5020_50200502_7_dialog_content = "Hantu bukan makhluk yang cerdas. Mereka memang tertarik pada pertarungan, tapi tidak pernah secepat ini.",
  ui_story_5020_50200502_8_dialog_content = "Apalagi sampai membuat kita terdesak begini... Mereka harus mengetahui lokasi kita dulu, lalu bersatu untuk mengepung kita sebelum akhirnya menyerang secara serentak.",
  ui_story_5020_50200502_9_dialog_content = "Pasti ada seseorang yang mengendalikan mereka.",
  ui_story_5020_50200502_10_dialog_content = "Sepertinya Jenderal... akhirnya bertindak.",
  ui_story_5020_50200502_11_dialog_content = "Apa yang harus kita lakukan, Pak?",
  ui_story_5020_50200502_12_dialog_content = "Kita perlu mengetahui situasinya terlebih dahulu, jadi kita bisa mencari jalan melalui barisan mereka.",
  ui_story_5020_50200502_13_dialog_content = "Paling tidak, kita perlu mengeluarkan warga sipil dengan aman dari Koufu-jou...",
  ui_story_5020_50200502_14_dialog_content = "(Awas, di belakang kalian!)",
  ui_story_5020_50200502_15_dialog_content = "?!",
  ui_story_5020_50200502_16_dialog_content = "Siapa yang mengatakannya barusan?!",
  ui_story_5020_50200502_17_dialog_content = "(Aku! Salah satu orang asing yang kalian ikat tadi!)",
  ui_story_5020_50200502_18_dialog_content = "Bagaimana kau bisa kabur?",
  ui_story_5020_50200502_19_dialog_content = "Kalau kau memang berani bicara padaku, berhenti menyelinap dan tunjukkan dirimu!",
  ui_story_5020_50200502_20_dialog_content = "(Anu... Saat ini aku tidak berada di dekatmu.)",
  ui_story_5020_50200502_21_dialog_content = "(Saya menggunakan kemampuan psikis saya untuk berkomunikasi dengan Anda.)",
  ui_story_5020_50200502_22_dialog_content = "Maksudmu?",
  ui_story_5020_50200502_23_dialog_content = "(Yah, begini... Eh, sudahlah. Itu tidak penting.)",
  ui_story_5020_50200502_24_dialog_content = "(Pokoknya, aku dan teman-temanku bisa membantumu!)",
  ui_story_5020_50200502_25_dialog_content = "Membantu? Hah! Wisp tak pernah minta bantuan, terutama dari tawanan seperti kalian!",
  ui_story_5020_50200502_26_dialog_content = "(Dengan semua hantu yang menyerang di sini, apakah ini benar-benar waktunya untuk bertindak tinggi dan perkasa?)",
  ui_story_5020_50200502_27_dialog_content = "Apa-apaan kau...!",
  ui_story_5020_50200502_28_dialog_content = "(Para hantu bergerak mendekat dari jalan di sebelah kanan!)",
  ui_story_5020_50200502_29_dialog_content = "Dari kanan?",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50200502_31_dialog_content = "Kau berkata jujur...",
  ui_story_5020_50200502_32_dialog_content = "Mata ke kanan! Prajurit, serang!",
  ui_story_5020_50200502_33_dialog_content = "(Uh, sebenarnya... Mereka datang dari kiri juga.)",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50200502_35_dialog_content = "Apa-apaan ini...? Kenapa tidak bilang dari tadi?!",
  ui_story_5020_50200502_36_dialog_content = "(Karena kami bisa menangani situasi di sisi ini.)",
  ui_story_5020_50200502_37_dialog_content = "Sama-sama!",
  ui_story_5020_50200502_38_dialog_content = "Kenapa kalian membantu kami?",
  ui_story_5020_50200502_39_dialog_content = "Jenderal tak akan menyakiti kalian selama kalian bersama si pendeta.",
  ui_story_5020_50200502_40_dialog_content = "(Ceritanya panjang, tapi kami tidak berada dalam kondisi terbaik dengan sang jenderal saat ini...)",
  ui_story_5020_50200502_41_dialog_content = "Apa maksudmu?",
  ui_story_5020_50200502_42_dialog_content = "(Kami bertarung satu sama lain beberapa waktu lalu... Sulit menjelaskannya.)",
  ui_story_5020_50200502_43_dialog_content = "(Setelah mendengar penjelasanmu, aku jadi menyadari bahwa sejarah Cloud Island jauh lebih rumit dari dugaanku.)",
  ui_story_5020_50200502_44_dialog_content = "(Sebagai orang luar, kami tak berhak ikut campur masalahmu.)",
  ui_story_5020_50200502_45_dialog_content = "(Tapi, melawan hantu untuk melindungi orang lain adalah pilihan tepat.)",
  ui_story_5020_50200502_46_dialog_content = "(Itu sebabnya, setidaknya saat ini, kita harus bekerja sama untuk mengalahkan mereka!)",
  ui_story_5020_50200502_47_dialog_content = "...",
  ui_story_5020_50200502_48_dialog_content = "Baiklah.",
  ui_story_5020_50200502_49_dialog_content = "Kuterima kalian sebagai sekutu dalam pertempuran, setidaknya untuk saat ini.",
  ui_story_5020_50200502_50_dialog_content = "Rinne! Kau baik-baik saja?",
  ui_story_5020_50200502_51_dialog_content = "... Iya, terima kasih.",
  ui_story_5020_50200502_52_dialog_content = "Kau terluka, Rinne?",
  ui_story_5020_50200502_53_dialog_content = "Biasanya, Anda sudah mengusir semua hantu ini.",
  ui_story_5020_50200502_54_dialog_content = "...",
  ui_story_5020_50200502_55_dialog_content = "Maaf karena sudah membuatmu cemas.",
  ui_story_5020_50200502_56_dialog_content = "Hanya saja... aku sedang tidak fokus.",
  ui_story_5020_50200502_57_dialog_content = "Apa ini gara-gara cerita anggota Wisp itu?",
  ui_story_5020_50200502_58_dialog_content = "... Iya.",
  ui_story_5020_50200502_59_dialog_content = "Aku tak bisa melupakan perkataannya... \"Pertunjukan\"...",
  ui_story_5020_50200502_60_dialog_content = "Itu terus mengganggu pikiranku, dan aku tidak bisa bertarung dengan kekuatan penuhku.",
  ui_story_5020_50200502_61_dialog_content = "A-aku... merasa kehilangan semangat juang.",
  ui_story_5020_50200502_62_dialog_content = "Tapi, kupikir kau sudah mengetahuinya setelah pertarungan kita dengan Jenderal di Main Castle...",
  ui_story_5020_50200502_63_dialog_content = "Saat itu aku hanya sedang marah. Aku tidak benar-benar memahami situasinya...",
  ui_story_5020_50200502_64_dialog_content = "Tapi, kurasa aku paham sekarang.",
  ui_story_5020_50200502_65_dialog_content = "Paham apa?",
  ui_story_5020_50200502_66_dialog_content = "Sejak awal, dia tidak pernah ingin aku mengusir hantu.",
  ui_story_5020_50200502_67_dialog_content = "Dia justru ingin memanfaatkanku... Dia memaksaku menjadi pendeta agar aku bisa menipu rakyat dalam sandiwara yang dirancangnya.",
  ui_story_5020_50200502_68_dialog_content = "Selama ini, dengan bangga kujalankan peran sebagai pendeta yang bisa menyingkirkan segala rasa takut.",
  ui_story_5020_50200502_69_dialog_content = "Tapi sekarang saya tidak lagi tampil di atas panggung, tiba-tiba saya mendengar cerita saya sendiri, melalui mulut orang lain.",
  ui_story_5020_50200502_70_dialog_content = "A-aku tidak begitu tahu lagi siapa diriku...",
  ui_story_5020_50200502_71_dialog_content = "Haruskah aku jadi diri sendiri, atau jadi yang masterku inginkan...?",
  ui_story_5020_50200601_1_dialog_content = "Semuanya, ikuti aku!",
  ui_story_5020_50200601_2_dialog_content = "Hah? Kita harus pergi lagi? Kali ini ke mana?",
  ui_story_5020_50200601_3_dialog_content = "Kita makin jauh dari Sakai!",
  ui_story_5020_50200601_4_dialog_content = "Kita benar-benar harus meninggalkan Koufu-jou.",
  ui_story_5020_50200601_5_dialog_content = "Apa? Kenapa?!",
  ui_story_5020_50200601_6_dialog_content = "Bagaimana kami bisa berbisnis di negeri antah-berantah?",
  ui_story_5020_50200601_7_dialog_content = "Para hantu menyerang kota atas perintahnya. Sekarang, tempat mana pun di luar kota lebih aman daripada di dalam.",
  ui_story_5020_50200601_8_dialog_content = "Oh...",
  ui_story_5020_50200601_9_dialog_content = "Momo... Maksudnya, Jenderal yang memanggil para hantu itu?",
  ui_story_5020_50200601_10_dialog_content = "Kurasa begitu, Anzu. Tapi, kenapa, ya?",
  ui_story_5020_50200601_11_dialog_content = "Jenderal bermaksud... *glek* menghabisi semua orang...?",
  ui_story_5020_50200601_12_dialog_content = "Kurasa tidak... Lagi pula, dia kan penguasa Koufu-jou.",
  ui_story_5020_50200601_13_dialog_content = "Siapa yang mau dia pimpin kalau semua orang dibunuh?",
  ui_story_5020_50200601_14_dialog_content = "Jangan-jangan dia... ingin mengendalikan para hantu?",
  ui_story_5020_50200601_15_dialog_content = "J-jangan bilang begitu, dong! Aku jadi takut!",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5020_50200601_17_dialog_content = "?!",
  ui_story_5020_50200601_18_dialog_content = "<size=45>Hei, kalian semua! Berhenti!</size>",
  ui_story_5020_50200601_19_dialog_content = "!!!",
  ui_story_5020_50200601_20_dialog_content = "Sial...",
  ui_story_5020_50200601_21_dialog_content = "Mau ke mana kalian tengah malam begini?",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>Atap di atas jalanan Koufu-jou</color>",
  ui_story_5020_50200601_21X2_dialog_content = "I-Ini sangat tinggi! Pelan-pelan, teman-teman!",
  ui_story_5020_50200601_21X3_dialog_content = "Sedikit lagi. Saat ini jalan keluar tercepat dan teraman adalah lewat atap.",
  ui_story_5020_50200601_22_dialog_content = "Jalannya buntu, PlayerName!",
  ui_story_5020_50200601_23_dialog_content = "Bagaimana ini?",
  ui_story_5020_50200601_24_dialog_content = "Sepertinya kita tak punya pilihan...",
  ui_story_5020_50200601_25_dialog_content = "Kita akan lompat?",
  ui_story_5020_50200601_26_dialog_content = "Ya...",
  ui_story_5020_50200601_27_dialog_content = "Bagus!",
  ui_story_5020_50200601_28_dialog_content = "Hei! Jangan asal lompat begitu!",
  ui_story_5020_50200601_29_dialog_content = "Siapa yang mau membantuku sekarang...?",
  ui_story_5020_50200601_30_dialog_content = "Cepat, PlayerName!",
  ui_story_5020_50200601_31_dialog_content = "Anda tidak akan bisa melompat jika hantu menangkap Anda!",
  ui_story_5020_50200601_32_dialog_content = "Iya, iya!",
  ui_story_5020_50200601_33_dialog_content = "Fyuh...",
  ui_story_5020_50200601_34_dialog_content = "Ini dia!!!",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>Aaaaaahhh!</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5020_50200601_37_dialog_content = "A-aku masih hidup, 'kan?",
  ui_story_5020_50200601_38_dialog_content = "Tidak mungkin menemukan ruang aman untuk mendarat dengan mata tertutup, lho.",
  ui_story_5020_50200601_39_dialog_content = "Untung aku menangkapmu!",
  ui_story_5020_50200601_40_dialog_content = "Kau memang hebat, Vice...",
  ui_story_5020_50200601_41_dialog_content = "Tentu saja, tapi... Apa kau bisa berdiri sendiri sekarang?",
  ui_story_5020_50200601_42_dialog_content = "O-oh, maaf...",
  ui_story_5020_50200601_43_dialog_content = "Baiklah...",
  ui_story_5020_50200601_44_dialog_content = "Kita bertemu lagi, orang-orang asing.",
  ui_story_5020_50200601_45_dialog_content = "Jadi, selama ini kalian sembunyi di atap?",
  ui_story_5020_50200601_46_dialog_content = "Hmm...",
  ui_story_5020_50200601_47_dialog_content = "Aku tahu sebaiknya kita jaga jarak dari satu sama lain...",
  ui_story_5020_50200601_48_dialog_content = "Tapi, kurasa saat ini kita tak punya pilihan.",
  ui_story_5020_50200601_49_dialog_content = "Maksudmu, kau mau minta bantuan kami?",
  ui_story_5020_50200601_50_dialog_content = "Ini benar-benar bukan waktunya bersikap seperti itu...",
  ui_story_5020_50200601_51_dialog_content = "Aku tak mau tambah merepotkanmu.",
  ui_story_5020_50200601_52_dialog_content = "Saya hanya mencoba menunjukkan bahwa hantu akan segera muncul di sini.",
  ui_story_5020_50200601_53_dialog_content = "Kalau kau dan pasukanmu mau berhenti, kami mau melanjutkan pelarian.",
  ui_story_5020_50200601_54_dialog_content = "Kalau kau masih mau melawan hantu, kami juga bersedia membantu.",
  ui_story_5020_50200601_55_dialog_content = "Tch, kamu orang yang cerdas, bukan...",
  ui_story_5020_50200601_56_dialog_content = "Mari kita lihat apakah Anda bisa melakukan pembicaraan dalam perkelahian.",
  ui_story_5020_50200601_57_dialog_content = "Anda akan melihat sendiri sebentar lagi!",
  ui_story_5020_50200601_58_dialog_content = "Satu hal lagi. Suruh wanita itu jauh-jauh dari kami.",
  ui_story_5020_50200601_59_dialog_content = "Kami tidak ingin bertarung bersama pendeta. Tidak sekarang, tidak selamanya.",
  ui_story_5020_50200601_60_dialog_content = "...",
  ui_story_5020_50200601_61_dialog_content = "Eh... Sebenarnya, Rinne adalah...",
  ui_story_5020_50200601_62_dialog_content = "Saya baik-baik saja dengan itu.",
  ui_story_5020_50200601_63_dialog_content = "Melihatmu dan pasukanmu mau bertindak di situasi seperti ini.",
  ui_story_5020_50200601_64_dialog_content = "Aku senang bisa membantu.",
  ui_story_5020_50200601_65_dialog_content = "Kau...!",
  ui_story_5020_50200601_66_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5020_50200601_67_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50200601_68_dialog_content = "Cih... Sudahlah.",
  ui_story_5020_50200601_69_dialog_content = "Wisp! Bersiaplah untuk bertempur!",
  ui_story_5020_50200602_1_dialog_content = "Berapa sisanya?",
  ui_story_5020_50200602_2_dialog_content = "Hampir selesai... Aku bisa merasakan energi di sekitar kita sudah melemah.",
  ui_story_5020_50200602_3_dialog_content = "Vice!",
  ui_story_5020_50200602_4_dialog_content = "Baik!",
  ui_story_5020_50200602_5_dialog_content = "Kau masih bisa bertarung?",
  ui_story_5020_50200602_6_dialog_content = "Memangnya kaukira aku ini siapa, Nak?",
  ui_story_5020_50200602_7_dialog_content = "Khawatirkan saja keadaanmu sendiri.",
  ui_story_5020_50200602_8_dialog_content = "Aku bisa merasakannya... Tenagamu sudah mencapai batas.",
  ui_story_5020_50200602_9_dialog_content = "Jika Anda seintuitif yang Anda pikirkan, Anda akan tahu bahwa semangat saya sedang bersiap untuk pergi.",
  ui_story_5020_50200602_10_dialog_content = "Apa gunanya rohmu kalau ragamu saja sudah kelelahan?",
  ui_story_5020_50200602_11_dialog_content = "Perhatikan baik-baik, nak. Hal-hal yang kita lawan bahkan tidak memiliki tubuh, tetapi mereka terus mendatangi kita!",
  ui_story_5020_50200602_12_dialog_content = "Itu karena mereka masih memiliki sedikit semangat yang tersisa di dalam diri mereka.",
  ui_story_5020_50200602_13_dialog_content = "Kami percaya bahwa roh jauh lebih penting daripada raga.",
  ui_story_5020_50200602_14_dialog_content = "Kita mungkin kalah dalam pertempuran, dan bahkan nyawa kita, tapi kita tidak akan pernah menyerah.",
  ui_story_5020_50200602_15_dialog_content = "Mengerikan juga keyakinan kalian...",
  ui_story_5020_50200602_16_dialog_content = "Tapi kali ini tidak perlu.",
  ui_story_5020_50200602_17_dialog_content = "Ini akan segera berakhir.",
  ui_story_5020_50200602_18_dialog_content = "Hmmm...",
  ui_story_5020_50200602_19_dialog_content = "Ini yang terakhir!",
  ui_story_5020_50200602_20_dialog_content = "Fyuh... Capek juga.",
  ui_story_5020_50200602_21_dialog_content = "Selanjutnya ke mana, Nak?",
  ui_story_5020_50200602_22_dialog_content = "Kita harus bergegas menemui sisa penduduk.",
  ui_story_5020_50200602_23_dialog_content = "Tunggu... Jangan lengah dulu!",
  ui_story_5020_50200602_24_dialog_content = "Ada segelintir orang yang mendekat...",
  ui_story_5020_50200602_25_dialog_content = "Rakyat? Orang seperti apa?",
  ui_story_5020_50200602_26_dialog_content = "<color=#e8d9bb>Duk, duk, duk...</color>",
  ui_story_5020_50200602_27_dialog_content = "Jika saya tidak salah, saya tidak berpikir mereka adalah orang-orang yang akan membuat Anda senang melihatnya...",
  ui_story_5020_50200602_28_dialog_content = "<color=#e8d9bb>Duk, duk, duk...</color>",
  ui_story_5020_50200602_29_dialog_content = "Dasar pemberontak tengik!",
  ui_story_5020_50200602_30_dialog_content = "Momok di seluruh Koufu-jou!",
  ui_story_5020_50200602_31_dialog_content = "Hari ini...",
  ui_story_5020_50200602_32_dialog_content = "<size=40>Kami akan menyingkirkan kota kami dari hadapanmu untuk selamanya!</size>",
  ui_story_5020_50200602_33_dialog_content = "Samurai? Dan banyak dari mereka!!",
  ui_story_5020_50200602_34_dialog_content = "Huh, anjing-anjing peliharaan Jenderal memang suka lari berombongan.",
  ui_story_5020_50200602_35_dialog_content = "Gonggongan mereka lebih parah daripada gigitannya.",
  ui_story_5020_50200602_36_dialog_content = "Maju, semuanya!",
  ui_story_5020_50200602_37_dialog_content = "Tunggu!",
  ui_story_5020_50200602_38_dialog_content = "Ada orang lain di belakang mereka ...",
  ui_story_5020_50200602_39_dialog_content = "Seseorang?",
  ui_story_5020_50200602_40_dialog_content = "Wow! Vice! PlayerName!",
  ui_story_5020_50200602_41_dialog_content = "Kalian baik-baik saja?",
  ui_story_5020_50200602_42_dialog_content = "Anzu? Momo??",
  ui_story_5020_50200602_43_dialog_content = "Bukankah Anda seharusnya bersama warga sipil?",
  ui_story_5020_50200602_44_dialog_content = "Ayah...",
  ui_story_5020_50200602_45_dialog_content = "Hush",
  ui_story_5020_50200602_46_dialog_content = "S-sungguh hina!",
  ui_story_5020_50200602_47_dialog_content = "Berani-beraninya kalian menangkap para penduduk yang tak bersalah!",
  ui_story_5020_50200602_48_dialog_content = "Seharusnya aku yang mengatakannya!",
  ui_story_5020_50200602_49_dialog_content = "Kau bedebah Wisp berencana kabur dengan para penduduk kota yang dijadikan sandera!",
  ui_story_5020_50200602_50_dialog_content = "Itu adalah pelanggaran pertama Anda.",
  ui_story_5020_50200602_51_dialog_content = "Sandera? Kau sudah gila, ya?!",
  ui_story_5020_50200602_52_dialog_content = "Di mana Anda saat jalanan dipenuhi hantu? Dan sekarang Anda pikir Anda bisa memainkan para pahlawan ?!",
  ui_story_5020_50200602_53_dialog_content = "Membantah Jenderal, dan diam-diam membentuk faksi pemberontak...",
  ui_story_5020_50200602_54_dialog_content = "Itu adalah pelanggaranmu yang kedua.",
  ui_story_5020_50200602_55_dialog_content = "Apa-apaan kau...!",
  ui_story_5020_50200602_56_dialog_content = "Dan meskipun kau gagal menggulingkan kekuasaan Jenderal...",
  ui_story_5020_50200602_57_dialog_content = "Kau mencoba-coba seni terlarang, dan memanggil para hantu ke kota untuk mengacaukan keadaan.",
  ui_story_5020_50200602_58_dialog_content = "Itu adalah pelanggaran ketiga Anda.",
  ui_story_5020_50200602_59_dialog_content = "Apa maksudmu?!",
  ui_story_5020_50200602_60_dialog_content = "The Wisps telah melawan hantu selama ini!",
  ui_story_5020_50200602_61_dialog_content = "Hmm...",
  ui_story_5020_50200602_62_dialog_content = "Saya pikir dia mengatakan semua ini untuk didengar oleh penduduk kota.",
  ui_story_5020_50200602_63_dialog_content = "Tuan Samurai, apakah ini benar?",
  ui_story_5020_50200602_64_dialog_content = "Apakah Wisp benar-benar memanggil hantu?",
  ui_story_5020_50200602_65_dialog_content = "Tapi merekalah yang baru saja menyelamatkan kita...",
  ui_story_5020_50200602_66_dialog_content = "Tentu saja, tapi siapa tahu apa yang sebenarnya terjadi?",
  ui_story_5020_50200602_67_dialog_content = "Itu benar. Kami hanya sekelompok warga sipil yang tak berdaya, apa yang akan kami ketahui...",
  ui_story_5020_50200602_68_dialog_content = "Menurutku, sebaiknya kita percaya pada orang yang paling bisa melindungi kita...",
  ui_story_5020_50200602_69_dialog_content = "...",
  ui_story_5020_50200602_70_dialog_content = "Dulu kukira samurai seharusnya mematuhi kode kehormatan...",
  ui_story_5020_50200602_71_dialog_content = "Tapi sepertinya saya memberi Anda terlalu banyak kredit.",
  ui_story_5020_50200602_72_dialog_content = "Apakah Anda dengan jujur berpikir Anda dapat memutarbalikkan kebenaran demi kebaikan Anda dengan begitu mudah? Apakah Anda benar-benar menganggap publik sebagai orang bodoh ?!",
  ui_story_5020_50200602_73_dialog_content = "Mereka punya mata! Ada saksi.",
  ui_story_5020_50200602_74_dialog_content = "Yang berjuang sampai mati melawan hantu...",
  ui_story_5020_50200602_75_dialog_content = "Dan siapa yang bersembunyi di balik tembok kastil mereka, meringkuk ketakutan... Kebenarannya sangat jelas!",
  ui_story_5020_50200602_76_dialog_content = "Yang mereka lihat hari ini adalah gerombolan pengkhianat yang melanggar peraturan demi kepentingan mereka sendiri.",
  ui_story_5020_50200602_77_dialog_content = "Antar para penduduk kembali ke Main Castle! Jangan ambil risiko menimbulkan lebih banyak korban dalam pertempuran yang akan datang...",
  ui_story_5020_50200602_78_dialog_content = "Aduh, lagi-lagi bertarung...",
  ui_story_5020_50200602_79_dialog_content = "Ayo, kita pergi dari sini...",
  ui_story_5020_50200602_80_dialog_content = "Ada apa dengan dunia...",
  ui_story_5020_50200602_81_dialog_content = "Hai! Kami punya dua teman di sana, jangan sakiti mereka!",
  ui_story_5020_50200602_82_dialog_content = "Vice! PlayerName! Cepat ikut kami...!",
  ui_story_5020_50200602_83_dialog_content = "Sepertinya orang-orang di Cloud Island akan bertarung di antara mereka sendiri... Apa yang harus kita lakukan?",
  ui_story_5020_50200602_84_dialog_content = "Tunggu... Sepertinya tidak semudah itu.",
  ui_story_5020_50200602_85_dialog_content = "Sekarang kita lihat saja situasinya...",
  ui_story_5020_50200602_86_dialog_content = "Setidaknya untuk yang satu ini kita sepakat. Keselamatan penduduk kota adalah yang paling penting.",
  ui_story_5020_50200602_87_dialog_content = "Benar. Lagi pula, menjaga kedamaian Koufu-jou adalah tugas kami.",
  ui_story_5020_50200602_88_dialog_content = "Benar-benar? Dan di sini saya pikir itu adalah pekerjaan Wisp selama ini...",
  ui_story_5020_50200602_89_dialog_content = "Kalau kau memang ingin menegakkan keadilan, letakkan senjatamu dan terimalah hukuman atas kejahatanmu.",
  ui_story_5020_50200602_90_dialog_content = "<size=45>Hahahahaha!</size>",
  ui_story_5020_50200602_91_dialog_content = "Hukum Jenderal tidak berlaku padaku!",
  ui_story_5020_50200602_92_dialog_content = "Dasar keras kepala... Kalau begitu, bersiaplah untuk menuai apa yang kautabur.",
  ui_story_5020_50200602_93_dialog_content = "Huh! Aku setuju!",
  ui_story_5020_50200602_94_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5020_50200602_95_dialog_content = "?!?",
  ui_story_5020_50200602_96_dialog_content = "!!!",
  ui_story_5020_50200602_97_dialog_content = "Maaf menyela percakapan yang hidup ini...",
  ui_story_5020_50200602_98_dialog_content = "Tapi saya punya beberapa pertanyaan untuk ditanyakan sebelum Anda saling menghancurkan.",
  ui_story_5020_50200602_99_dialog_content = "Yang Mulia Pendeta?!",
  ui_story_5020_50200602_100_dialog_content = "Rupanya kau juga ditangkap oleh para pemberontak ini!",
  ui_story_5020_50200602_101_dialog_content = "Maaf karena datang terlambat. Aku berjanji akan menyelamatkanmu bagaimanapun caranya...",
  ui_story_5020_50200602_102_dialog_content = "Katamu... hantu-hantu itu dipanggil ke sini oleh Wisps, ya?",
  ui_story_5020_50200602_103_dialog_content = "Mana buktinya?",
  ui_story_5020_50200602_104_dialog_content = "... Bukti?",
  ui_story_5020_50200602_105_dialog_content = "Kapan mereka memanggil hantu? Di mana? Dengan metode apa?",
  ui_story_5020_50200602_106_dialog_content = "...",
  ui_story_5020_50200602_107_dialog_content = "Y-Yang Mulia Pendeta, aku hanya prajurit biasa. Aku tidak tahu rahasia atasan...",
  ui_story_5020_50200602_108_dialog_content = "Tapi yakinlah, ini adalah kata-kata sang jenderal sendiri.",
  ui_story_5020_50200602_109_dialog_content = "Oh?",
  ui_story_5020_50200602_110_dialog_content = "Kauyakin Jenderal yang mengatakannya? Bukan kebohongan dari orang lain?",
  ui_story_5020_50200602_111_dialog_content = "Benar, Yang Mulia. Aku berani jamin.",
  ui_story_5020_50200602_112_dialog_content = "...",
  ui_story_5020_50200602_113_dialog_content = "Ha... aku mengerti.",
  ui_story_5020_50200602_114_dialog_content = "Sampaikan ucapan terima kasihku kepada Jenderal karena sudah menyadarkanku.",
  ui_story_5020_50200602_115_dialog_content = "Terima kasih atas pengertianmu, Yang Mulia Pendeta.",
  ui_story_5020_50200602_116_dialog_content = "Sekarang, tolong berdiri di belakangku. Tak akan kubiarkan siapa pun menyakitimu dalam pertempuran nanti.",
  ui_story_5020_50200602_117_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5020_50200602_118_dialog_content = "Tidak usah.",
  ui_story_5020_50200602_119_dialog_content = "Aku sudah berada di tempat yang seharusnya.",
  ui_story_5020_50200602_120_dialog_content = "...",
  ui_story_5020_50200602_121_dialog_content = "Yang Mulia Pendeta... Kautahu apa yang akan terjadi jika menghalangi kami?",
  ui_story_5020_50200602_122_dialog_content = "Aku tidak tahu.",
  ui_story_5020_50200602_123_dialog_content = "Aku tidak mau berpindah. Apa yang kaulakukan dan ke mana kau pergi... itu bukan urusanku.",
  ui_story_5020_50200602_124_dialog_content = "Jika berdiri di tengah medan tempur, kau akan dianggap sebagai musuh.",
  ui_story_5020_50200602_125_dialog_content = "Dengan kata lain... Musuh Jenderal.",
  ui_story_5020_50200602_126_dialog_content = "Aku adalah pendeta. Aku tak pernah menganggap siapa pun sebagai musuh.",
  ui_story_5020_50200602_127_dialog_content = "Tapi, mungkin ada orang-orang yang akan menganggapku musuh.",
  ui_story_5020_50200602_128_dialog_content = "Maksudmu, ini semua kesalahan Jenderal?",
  ui_story_5020_50200602_129_dialog_content = "Sama sekali tidak. Saya akhirnya melihat dia apa adanya.",
  ui_story_5020_50200602_130_dialog_content = "Semua berkat Anda menyampaikan pesannya bahwa Wisps bertanggung jawab untuk memanggil hantu di sini.",
  ui_story_5020_50200602_131_dialog_content = "...",
  ui_story_5020_50200602_132_dialog_content = "Saat melihat para hantu di Cloud Pavillion, aku tidak paham.",
  ui_story_5020_50200602_133_dialog_content = "Dan ketika Cloud Mirror entah bagaimana menghidupkan kembali hantu, saya juga tidak mengerti.",
  ui_story_5020_50200602_134_dialog_content = "Pertentangan antara ucapan Jenderal dan tindakannya membuatku bingung... Aku tidak bisa memahaminya.",
  ui_story_5020_50200602_135_dialog_content = "Tapi, akhirnya kau dan anak buahmu memberiku jawaban yang kucari.",
  ui_story_5020_50200602_136_dialog_content = "Pendeta dan hantu telah melihat satu sama lain sebagai musuh selama beberapa generasi... Namun di mata sang jenderal, kita adalah sama.",
  ui_story_5020_50200602_137_dialog_content = "Kami tidak berbeda, karena kami berdua hanya senjata untuk digunakan.",
  ui_story_5020_50200602_138_dialog_content = "Jika butuh kekuatan, dia menggunakan hantu untuk melumat musuhnya.",
  ui_story_5020_50200602_139_dialog_content = "Jika ingin mengambil hati masyarakat, dia mengutus pendeta untuk melawan hantu yang dia panggil.",
  ui_story_5020_50200602_140_dialog_content = "Aku yakin masih ada banyak hal yang tidak kau ketahui, Yang Mulia Pendeta.",
  ui_story_5020_50200602_141_dialog_content = "Mungkin... Dan karena alasan ini, saya memilih untuk percaya hanya pada apa yang dapat saya pahami.",
  ui_story_5020_50200602_142_dialog_content = "Itulah yang telah saya pelajari selama ini... Saya memilih untuk percaya pada tugas saya sebagai pendeta.",
  ui_story_5020_50200602_143_dialog_content = "Hantu adalah musuh abadiku.",
  ui_story_5020_50200602_144_dialog_content = "...",
  ui_story_5020_50200602_145_dialog_content = "Ini juga alasan saya berdiri di tempat saya sekarang.",
  ui_story_5020_50200602_146_dialog_content = "Samurai di belakangmu...",
  ui_story_5020_50200602_147_dialog_content = "<color=#FFB400>Tak satu pun dari mereka yang masih hidup</color>, 'kan?",
  ui_story_5020_50200602_148_dialog_content = "...",
  ui_story_5020_50200602_149_dialog_content = "Sepertinya sudah waktunya kabar itu menyebar.",
  ui_story_5020_50200602_150_dialog_content = "...",
  ui_story_5020_50200602_151_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5020_50200602_152_dialog_content = "\"Sebuah ode untuk orang mati dan hidup. Semoga lagu ini membimbing jiwamu kembali ke tempat yang seharusnya.\"",
  ui_story_5020_50200701_1_dialog_content = "(Saat kami melihat samurai hantu mendekat, tubuh kami mati rasa karena tekanan yang kuat.)",
  ui_story_5020_50200701_2_dialog_content = "(Gelombang besar seolah-olah bersiap menghancurkan kami.)",
  ui_story_5020_50200701_3_dialog_content = "(Tapi di sana, di tengah jalan, berdiri Rinne, sendirian dan sama sekali tidak terpengaruh oleh gelombang yang akan datang.)",
  ui_story_5020_50200701_4_dialog_content = "(Dia menatap lekat-lekat perut neraka itu, membelakangi dunia orang hidup.)",
  ui_story_5020_50200701_5_dialog_content = "Oh...?",
  ui_story_5020_50200701_6_dialog_content = "Tadinya kukira Wisp tak mau bertarung bersama pendeta?",
  ui_story_5020_50200701_7_dialog_content = "...",
  ui_story_5020_50200701_8_dialog_content = "Akan jauh lebih menyebalkan kalau kau melindungi kami.",
  ui_story_5020_50200701_9_dialog_content = "Heh, sayang sekali.",
  ui_story_5020_50200701_10_dialog_content = "Kalau kalian semua ikut bertempur, siapa yang akan menyaksikan... pertunjukanku?",
  ui_story_5020_50200701_11_dialog_content = "Mau coba-coba menyindirku, ya? Aku tidak suka...",
  ui_story_5020_50200701_12_dialog_content = "Kau yang mengatakannya lebih dulu.",
  ui_story_5020_50200701_13_dialog_content = "Wah, kau ini memang pendendam... Omonganmu, atau omonganku tadi, memang ada benarnya.",
  ui_story_5020_50200701_14_dialog_content = "Hmm. Betul sekali.",
  ui_story_5020_50200701_15_dialog_content = "Karena menjadi musuh pendeta, kau jelas lebih paham daripada aku.",
  ui_story_5020_50200701_16_dialog_content = "Kalau pemahaman kita sama... kau pasti akan lebih membenci dirimu karena sudah menjadi pendeta.",
  ui_story_5020_50200701_17_dialog_content = "Ah... Jangan terlalu cepat menghakimi.",
  ui_story_5020_50200701_18_dialog_content = "Terlalu kasar kalau disebut pertunjukan, tapi aku tidak keberatan.",
  ui_story_5020_50200701_19_dialog_content = "Kalau begitu, kau masih mau jadi boneka?",
  ui_story_5020_50200701_20_dialog_content = "Yang menjadi perhatian Anda dan anak buah Anda hanyalah siapa yang menarik tali boneka itu.",
  ui_story_5020_50200701_21_dialog_content = "Sedangkan aku... aku hanya ingin menampilkan pertunjukan yang bagus.",
  ui_story_5020_50200701_22_dialog_content = "Boneka-boneka sebelumnya tak ada yang bisa melakukannya.",
  ui_story_5020_50200701_23_dialog_content = "Oh, ya? Kalau begitu, apa menurutmu aku bisa?",
  ui_story_5020_50200701_24_dialog_content = "...",
  ui_story_5020_50200701_25_dialog_content = "Apa itu sebabnya kau selalu ingin membunuh pendeta?",
  ui_story_5020_50200701_26_dialog_content = "Amemori sudah membuatku kerepotan, tahu?",
  ui_story_5020_50200701_27_dialog_content = "Ame...",
  ui_story_5020_50200701_28_dialog_content = "Panggil dia Komandan Amemori. Paham? Jangan kurang ajar!",
  ui_story_5020_50200701_29_dialog_content = "Oh?",
  ui_story_5020_50200701_30_dialog_content = "Tapi, Amemori selalu gagal membunuhku... Kupikir akhirnya dia menyerah agar tidak menjadi aib.",
  ui_story_5020_50200701_31_dialog_content = "Apa-apaan kau...!",
  ui_story_5020_50200701_32_dialog_content = "Apa Amemori ke Wisp?",
  ui_story_5020_50200701_33_dialog_content = "Amemori-sama adalah murid dari komandan kami.",
  ui_story_5020_50200701_34_dialog_content = "Bertahun-tahun setelah komandan kami dipenjara, dia menjadi pemimpin tidak resmi di Wisp.",
  ui_story_5020_50200701_35_dialog_content = "Begitu rupanya... Amemori tidak suka banyak omong, jadi aku tidak tahu.",
  ui_story_5020_50200701_36_dialog_content = "Komandan kalian dikenal sebagai Sword of the Underworld, 'kan?",
  ui_story_5020_50200701_37_dialog_content = "Mengapa? Pernahkah Anda melihatnya?",
  ui_story_5020_50200701_38_dialog_content = "Ya. Kami bahkan juga bertempur.",
  ui_story_5020_50200701_39_dialog_content = "Sebagai seseorang yang bisa bertarung di tempat yang sama dengan sang jenderal... Dia sangat kuat.",
  ui_story_5020_50200701_40_dialog_content = "Pasti cukup sulit bagi Amemori untuk menggantikan posisinya selama bertahun-tahun...",
  ui_story_5020_50200701_41_dialog_content = "Komandan Amemori benar-benar mirip Komandan lama. Dia berhasil menjalankan tugas-tugasnya dengan luar biasa.",
  ui_story_5020_50200701_42_dialog_content = "Dalam beberapa hal... dia bahkan lebih cakap daripada Komandan lama.",
  ui_story_5020_50200701_43_dialog_content = "Benarkah?",
  ui_story_5020_50200701_44_dialog_content = "Harus kuakui, kemampuannya membunuh pendeta sangat tidak memuaskan.",
  ui_story_5020_50200701_45_dialog_content = "Berarti, komandan kalian jauh lebih payah daripada Amemori?",
  ui_story_5020_50200701_46_dialog_content = "...",
  ui_story_5020_50200701_47_dialog_content = "Kupikir kau sudah tahu jawabannya.",
  ui_story_5020_50200701_48_dialog_content = "Coba ingat-ingat lagi alasanmu menjadi pendeta dulu.",
  ui_story_5020_50200701_49_dialog_content = "...",
  ui_story_5020_50200701_50_dialog_content = "Heh... Begitu, ya.",
  ui_story_5020_50200701_51_dialog_content = "Tidakkah Anda mengatakan bahwa membunuh pendeta adalah versi pertunjukan Anda sendiri?",
  ui_story_5020_50200701_52_dialog_content = "Jangan bandingkan kami dengan dirimu sendiri.",
  ui_story_5020_50200701_53_dialog_content = "Tapi kita di sini, berjuang bersama, bukan?",
  ui_story_5020_50200701_54_dialog_content = "Kau dan pasukanmu sudah terlibat dalam masalah ini.",
  ui_story_5020_50200702_1_dialog_content = "Ada lebih banyak samurai hantu yang mendekat dari belakang!",
  ui_story_5020_50200702_2_dialog_content = "Mereka membawa bala bantuan!",
  ui_story_5020_50200702_3_dialog_content = "... Begitu, ya.",
  ui_story_5020_50200702_4_dialog_content = "Kalau terus begini, kita tak akan selamat, Pak!",
  ui_story_5020_50200702_5_dialog_content = "Apa perintah Anda?",
  ui_story_5020_50200702_6_dialog_content = "...",
  ui_story_5020_50200702_7_dialog_content = "Aku khawatir ini bukan pertempuran yang bisa kita menangkan.",
  ui_story_5020_50200702_8_dialog_content = "Pak...",
  ui_story_5020_50200702_9_dialog_content = "Apa ini benar-benar sudah berakhir...?",
  ui_story_5020_50200702_10_dialog_content = "Bahkan kalau memang begitu, kita tak boleh menyerah tanpa bertarung!",
  ui_story_5020_50200702_11_dialog_content = "Kita... mungkin bisa memenangkan <color=#FFB400>pertarungan berikutnya</color>.",
  ui_story_5020_50200702_12_dialog_content = "Pertarungan berikutnya?",
  ui_story_5020_50200702_13_dialog_content = "Tapi, kalau kita kalah di sini sekarang, tak akan ada yang namanya pertarungan berikutnya!",
  ui_story_5020_50200702_14_dialog_content = "Saya ingin mencoba sesuatu yang belum pernah kami lakukan sebelumnya.",
  ui_story_5020_50200702_15_dialog_content = "Hei, orang asing! Kemarilah!!!",
  ui_story_5020_50200702_16_dialog_content = "T-tidak perlu teriak-teriak segala... Aku berdiri di dekatmu, kok...",
  ui_story_5020_50200702_17_dialog_content = "Aku ingin bertanya. Menurutmu, apa kita punya peluang kabur dari sini?",
  ui_story_5020_50200702_18_dialog_content = "Kabur?",
  ui_story_5020_50200702_19_dialog_content = "Jumlah samurai hantunya terlalu banyak... Peluang untuk kabur sangat kecil.",
  ui_story_5020_50200702_20_dialog_content = "Bagaimana jika Wisp menutupi Anda dari belakang? Bisakah Anda melarikan diri saat itu?",
  ui_story_5020_50200702_21_dialog_content = "Hah?",
  ui_story_5020_50200702_22_dialog_content = "Dengarkan. Saat ini, kalian berdua orang luar harus keluar dari sini, dan membawa pendeta itu bersamamu.",
  ui_story_5020_50200702_23_dialog_content = "Kami akan melindungi pelarian kalian, tapi kami tak akan bisa menahan mereka terlalu lama.",
  ui_story_5020_50200702_24_dialog_content = "Kau harus menggunakan kekuatanmu yang mengerikan.",
  ui_story_5020_50200702_25_dialog_content = "Paham?",
  ui_story_5020_50200702_26_dialog_content = "Aku paham. Hanya saja...",
  ui_story_5020_50200702_27_dialog_content = "Kenapa kau melakukannya?",
  ui_story_5020_50200702_28_dialog_content = "...",
  ui_story_5020_50200702_29_dialog_content = "Pendeta, lebih banyak orang harus menyaksikan penampilanmu ini.",
  ui_story_5020_50200702_30_dialog_content = "...",
  ui_story_5020_50200702_31_dialog_content = "Dalam situasi ini, Wisp tidak cukup kuat untuk melawan Jenderal.",
  ui_story_5020_50200702_32_dialog_content = "Tapi dengan kalian bertiga... Mungkin masih ada harapan.",
  ui_story_5020_50200702_33_dialog_content = "Karena kami pun sudah kalah tempur, aku lebih suka ambil risiko daripada menunggu ajal.",
  ui_story_5020_50200702_34_dialog_content = "Jangan menyerah, teman-teman! Jangan beri mereka ampun!",
  ui_story_5020_50200702_35_dialog_content = "Tapi, apa yang akan terjadi pada kalian setelah kami kabur?",
  ui_story_5020_50200702_36_dialog_content = "<size=45>Cepat pergi dari sini, Nak!</size>",
  ui_story_5020_50200702_37_dialog_content = "...",
  ui_story_5020_50200702_38_dialog_content = "Ayo, PlayerName.",
  ui_story_5020_50200702_39_dialog_content = "Mereka sudah membuat keputusan yang tepat.",
  ui_story_5020_50200702_40_dialog_content = "Kau berutang budi pada kami, Nak! Jangan lupa!",
  ui_story_5020_50200702_41_dialog_content = "Kau harus membayarnya.",
  ui_story_5020_50200702_42_dialog_content = "Wow!",
  ui_story_5020_50200702_43_dialog_content = "Besar sekali drumnya!",
  ui_story_5020_50200702_44_dialog_content = "Itu sih raksasa!",
  ui_story_5020_50200702_45_dialog_content = "Untuk apa benda itu, Ayah?",
  ui_story_5020_50200702_46_dialog_content = "Itu menjadi penanda dimulainya Festival Kasuga.",
  ui_story_5020_50200702_47_dialog_content = "Saking kerasnya, seluruh kota Koufu-jou bisa mendengarnya. Nah, dari suara itulah semua orang tahu bahwa Festival Kasuga sudah resmi dimulai.",
  ui_story_5020_50200702_48_dialog_content = "Woah!",
  ui_story_5020_50200702_49_dialog_content = "Lalu, kenapa drumnya ada di sini? Mana penabuhnya?",
  ui_story_5020_50200702_50_dialog_content = "Mungkin sembunyi dari para hantu?",
  ui_story_5020_50200702_51_dialog_content = "Sayang sekali...",
  ui_story_5020_50200702_52_dialog_content = "Bolehkah aku menabuhnya?",
  ui_story_5020_50200702_53_dialog_content = "Jangan sekarang, Nak. Kita harus tetap bersama yang lain.",
  ui_story_5020_50200702_54_dialog_content = "Kalau drum itu masih ada di sini besok, Ayah akan mengajakmu kemari untuk menabuhnya.",
  ui_story_5020_50200702_55_dialog_content = "Hei, Momo!",
  ui_story_5020_50200702_56_dialog_content = "Ya.",
  ui_story_5020_50200702_57_dialog_content = "Drum ini... sudah tidak bertuan, 'kan?",
  ui_story_5020_50200702_58_dialog_content = "Sepertinya sih begitu!",
  ui_story_5020_50200702_59_dialog_content = "Kalau kita mengambilnya...",
  ui_story_5020_50200702_60_dialog_content = "Dan menaruhnya di dekat kedai...",
  ui_story_5020_50200702_61_dialog_content = "Kita bisa menggunakannya untuk mengembangkan bisnis!",
  ui_story_5020_50200702_62_dialog_content = "<size=40>Tangkap mereka!</size>",
  ui_story_5020_50200702_63_dialog_content = "<size=40>Cepat!</size>",
  ui_story_5020_50200702_64_dialog_content = "Hah? Ada apa?",
  ui_story_5020_50200702_65_dialog_content = "Sepertinya...",
  ui_story_5020_50200702_66_dialog_content = "Ada seseorang yang berlari kemari!",
  ui_story_5020_50200702_67_dialog_content = "Anzu! Momo! Tolong!",
  ui_story_5020_50200702_68_dialog_content = "Aduh...",
  ui_story_5020_50200702_69_dialog_content = "Astaga...",
  ui_story_5020_50200702_70_dialog_content = "M-maaf, aku tidak mengerem tepat waktu.",
  ui_story_5020_50200702_71_dialog_content = "Lagi pula, kita dalam masalah besar! Sekelompok samurai mencoba membunuh kita!",
  ui_story_5020_50200702_72_dialog_content = "Samurai? Membunuh kalian?",
  ui_story_5020_50200702_73_dialog_content = "Apa yang telah kauperbuat, PlayerName?!",
  ui_story_5020_50200702_74_dialog_content = "Tidak ada waktu untuk menjelaskan! Apakah Anda tahu di mana kita bisa bersembunyi untuk saat ini?",
  ui_story_5020_50200702_75_dialog_content = "Cepat! Mereka makin dekat!",
  ui_story_5020_50200702_76_dialog_content = "Persembunyian? Aduh, kok mendadak, sih?!",
  ui_story_5020_50200702_77_dialog_content = "Yah, karena kau bertanya...",
  ui_story_5020_50200702_78_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200702_79_dialog_content = "<size=40>Anu...</size>",
  ui_story_5020_50200702_80_dialog_content = "PlayerName, geser, dong...",
  ui_story_5020_50200702_81_dialog_content = "Tak ada ruang di sini...",
  ui_story_5020_50200702_82_dialog_content = "Aku mau saja, tapi... di dalam sini kan bundar!",
  ui_story_5020_50200702_83_dialog_content = "Tubuhku terus merosot!",
  ui_story_5020_50200702_84_dialog_content = "Sigh... Aku tidak percaya kau menemukan sesuatu yang konyol seperti bersembunyi di dalam drum...",
  ui_story_5020_50200702_85_dialog_content = "Apa? Ini kan ide Anzu dan Momo! Tak ada hubungannya denganku!",
  ui_story_5020_50200702_86_dialog_content = "Heh... Sayangnya, mengingat kondisinya, sepertinya ini pilihan terbaik kita.",
  ui_story_5020_50200702_87_dialog_content = "Kita terima saja untuk sekarang.",
  ui_story_5020_50200702_88_dialog_content = "Hmm...",
  ui_story_5020_50200702_89_dialog_content = "Ssst, mereka ada di sini.",
  ui_story_5020_50200702_90_dialog_content = "Hei, kalian! Apa kalian lihat tiga orang yang tampak panik lewat sini barusan?",
  ui_story_5020_50200702_91_dialog_content = "Salah satu dari mereka mengenakan pakaian pendeta berwarna merah. Kalian tak mungkin melewatkannya.",
  ui_story_5020_50200702_92_dialog_content = "Hah? Mengapa khusus tiga orang?",
  ui_story_5020_50200702_93_dialog_content = "Barusan aku melihat orang berpakaian biru. Itu termasuk, tidak?",
  ui_story_5020_50200702_94_dialog_content = "... Bilang saja kalian lihat atau tidak.",
  ui_story_5020_50200702_95_dialog_content = "Belum melihat mereka!",
  ui_story_5020_50200702_96_dialog_content = "Baiklah. Terima kasih.",
  ui_story_5020_50200702_97_dialog_content = "(Fyuh... Dia percaya...)",
  ui_story_5020_50200702_98_dialog_content = "Tapi... apa yang sedang kalian berdua lakukan di sini?",
  ui_story_5020_50200702_99_dialog_content = "Kenapa kalian tidak mengikuti yang lain?",
  ui_story_5020_50200702_100_dialog_content = "Ah, anu... Begini... Anu...",
  ui_story_5020_50200702_101_dialog_content = "Karena drumnya ada di sini...",
  ui_story_5020_50200702_102_dialog_content = "Drum?",
  ui_story_5020_50200702_103_dialog_content = "(!!!)",
  ui_story_5020_50200702_104_dialog_content = "Bagaimana dengan drumnya?",
  ui_story_5020_50200702_105_dialog_content = "(Mampus, deh...)",
  ui_story_5020_50200702_106_dialog_content = "Ya! Gendang ini!",
  ui_story_5020_50200702_107_dialog_content = "Kami kan penabuhnya!",
  ui_story_5020_50200702_108_dialog_content = "B-benar! Kami sedang bersiap mengumumkan dimulainya Festival Kasuga!",
  ui_story_5020_50200702_109_dialog_content = "Penabuh?",
  ui_story_5020_50200702_110_dialog_content = "Tapi, kalian berdua bertubuh mungil... Memangnya kalian kuat menabuh drum?",
  ui_story_5020_50200702_111_dialog_content = "Tubuh kami memang mungil, tapi...",
  ui_story_5020_50200702_112_dialog_content = "Kami bekerja sama!",
  ui_story_5020_50200702_113_dialog_content = "Bekerja sama?",
  ui_story_5020_50200702_114_dialog_content = "Kedengarannya menarik... Coba kalian peragakan!",
  ui_story_5020_50200702_115_dialog_content = "S-sungguh?",
  ui_story_5020_50200702_116_dialog_content = "M-mungkin lain kali saja, Pak! Kami harus menyusul yang lain...",
  ui_story_5020_50200702_117_dialog_content = "Tak ada yang perlu dicemaskan. Lebih banyak samurai akan kemari, jadi kita aman di sini.",
  ui_story_5020_50200702_118_dialog_content = "Ayo, perlihatkan kebolehan kalian menabuh drum.",
  ui_story_5020_50200702_119_dialog_content = "(...)",
  ui_story_5020_50200702_120_dialog_content = "(... Anzu? Momo? Kalian tidak benar-benar akan...)",
  ui_story_5020_50200702_121_dialog_content = "<size=30>Maafkan kami, PlayerName...</size>",
  ui_story_5020_50200702_122_dialog_content = "<size=30>Cobalah bertahan...</size>",
  ui_story_5020_50200702_123_dialog_content = "(T-tunggu! Pasti ada cara...)",
  ui_story_5020_50200702_124_dialog_content = "Hei!",
  ui_story_5020_50200702_125_dialog_content = "<color=#e8d9bb><size=50>Brak!!!</size></color>",
  ui_story_5020_50200702_126_dialog_content = "Hei!",
  ui_story_5020_50200702_127_dialog_content = "<color=#e8d9bb><size=50>Brak!!!</size></color>",
  ui_story_5020_50200702_128_dialog_content = "Oho! Kalian berdua hebat juga!",
  ui_story_5020_50200702_129_dialog_content = "<anim type=Shake>Haha... Ha...</anim>",
  ui_story_5020_50200702_130_dialog_content = "Anda terlalu memuji, Pak...",
  ui_story_5020_50200702_131_dialog_content = "Jenderal memang bilang Festival Kasuga harus terus berjalan tanpa insiden... Bagus sekali, anak-anak. Bawa drumnya kembali ke Main Castle agar kalian bisa melanjutkan persiapannya.",
  ui_story_5020_50200702_132_dialog_content = "Juga, jika Anda kebetulan melihat ketiganya yang saya sebutkan sebelumnya, beri tahu kami.",
  ui_story_5020_50200702_133_dialog_content = "Bagus!",
  ui_story_5020_50200702_134_dialog_content = "Anu...",
  ui_story_5020_50200702_135_dialog_content = "PlayerName...",
  ui_story_5020_50200702_136_dialog_content = "Kalian bertiga baik-baik saja...?",
  ui_story_5020_50200702_137_dialog_content = "<size=45>Bagaimana menurutmu?!</size>",
  ui_story_5020_50200702_138_dialog_content = "<size=45>Gendang telinga kita hampir pecah!!</size>",
  ui_story_5020_50200702_139_dialog_content = "Pendengaranmu sepertinya baik-baik saja...",
  ui_story_5020_50200702_140_dialog_content = "Aku menggunakan kekuatanku, tahu?! Telingaku benar-benar tuli!",
  ui_story_5020_50200702_141_dialog_content = "Kau mengatakan sesuatu, PlayerName? Kulihat bibirmu bergerak-gerak, tapi...",
  ui_story_5020_50200702_142_dialog_content = "Maaf! Kami benar-benar minta maaf!!!",
  ui_story_5020_50200702_143_dialog_content = "Fiuh...",
  ui_story_5020_50200702_144_dialog_content = "Lupakan saja. Tidak ada pilihan lain.",
  ui_story_5020_50200702_145_dialog_content = "Shh!",
  ui_story_5020_50200702_146_dialog_content = "Ada lebih banyak samurai yang kemari!",
  ui_story_5020_50200702_147_dialog_content = "Semua ini tak pernah berakhir, ya...?",
  ui_story_5020_50200702_148_dialog_content = "Sekarang kita harus bagaimana?",
  ui_story_5020_50200702_149_dialog_content = "Kalian harus tetap sembunyi di dalam drum!",
  ui_story_5020_50200702_150_dialog_content = "Anzu dan saya akan membawa Anda ke suatu tempat dengan lebih sedikit orang, sehingga Anda memiliki kesempatan yang lebih baik untuk melarikan diri!",
  ui_story_5020_50200702_151_dialog_content = "Kurasa... kedengarannya itu ide yang bagus.",
  ui_story_5020_50200702_152_dialog_content = "Benar sekali!",
  ui_story_5020_50200702_153_dialog_content = "Kami selalu bisa mencari cara!",
  ui_story_5020_50200702_154_dialog_content = "Tapi dengarkan...",
  ui_story_5020_50200702_155_dialog_content = "Jangan menabuh lagi! Aku serius!",
  ui_story_5020_50200702_156_dialog_content = "Iya, iya! Jangan menabuh lagi!",
  ui_story_5020_50200702_157_dialog_content = "(Apa yang ingin dicapai Wisp dengan membantu kami melarikan diri?)",
  ui_story_5020_50200702_158_dialog_content = "(Bagaimana keadaan mereka...?)",
  ui_story_5020_50200702_159_dialog_content = "Kami menyerah!",
  ui_story_5020_50200702_160_dialog_content = "... Hei, hentikan! Sudah kubilang kami menyerah!",
  ui_story_5020_50200702_161_dialog_content = "Selama ini Jenderal-lah yang benar! Akhirnya, kami menyadari kesalahan!",
  ui_story_5020_50200702_162_dialog_content = "Wisp bersalah! Kami menerima hukuman kami!",
  ui_story_5020_50200702_163_dialog_content = "...",
  ui_story_5020_50200702_164_dialog_content = "Samurai yang hebat, sebagai anjing peliharaan Jenderal... Eh, bukan! Maksudku, pedang paling tajam Jenderal!",
  ui_story_5020_50200702_165_dialog_content = "Anda sekarang akan menangani hal-hal sesuai dengan hukum ... Benar?",
  ui_story_5020_50200702_166_dialog_content = "Katakan, kenapa kau membantu pendeta itu kabur?",
  ui_story_5020_50200702_167_dialog_content = "Membantunya? Dia kabur sendiri! Tak ada hubungannya dengan kami.",
  ui_story_5020_50200702_168_dialog_content = "Musuh dari musuhmu mungkin bukan temanmu.",
  ui_story_5020_50200702_169_dialog_content = "Jenderal adalah ayah angkatnya. Tidak banyak yang bisa dia lakukan.",
  ui_story_5020_50200702_170_dialog_content = "Bukan masalah! Sekarang mari selesaikan saja masalah ini agar kita bisa menikmati kedamaian!",
  ui_story_5020_50200702_171_dialog_content = "...",
  ui_story_5020_50200702_172_dialog_content = "Ikat mereka lalu bawa ke Main Castle.",
  ui_story_5020_50200801_1_dialog_content = "Petik bunga merah untuk gadis muda itu...",
  ui_story_5020_50200801_2_dialog_content = "Kelopak berguguran seperti butiran salju di atas sebongkah giok.",
  ui_story_5020_50200801_3_dialog_content = "Apa yang akan Anda lakukan selanjutnya, Guru?",
  ui_story_5020_50200801_4_dialog_content = "Oh? Masih mengikutiku, ya?",
  ui_story_5020_50200801_5_dialog_content = "Aku terkejut kau masih betah melakukannya selama ini.",
  ui_story_5020_50200801_6_dialog_content = "Tolong, Guru. Biarkan saya membantu Anda.",
  ui_story_5020_50200801_7_dialog_content = "Membantuku? Membantu apa? Aku tidak butuh bantuan.",
  ui_story_5020_50200801_8_dialog_content = "Ada urusan pribadi yang harus kutangani.",
  ui_story_5020_50200801_9_dialog_content = "Aku akan datang mencarimu setelah aku selesai. Jadilah gadis yang baik.",
  ui_story_5020_50200801_10_dialog_content = "...",
  ui_story_5020_50200801_11_dialog_content = "Master... Kalau kau pergi sendiri, aku...",
  ui_story_5020_50200801_12_dialog_content = "Aku sudah berjanji pada diri sendiri tak akan membiarkannya terjadi lagi.",
  ui_story_5020_50200801_13_dialog_content = "Saya telah tumbuh banyak tanpa kehadiran Anda, Guru. Saya dapat membantu Anda memikul beban Anda.",
  ui_story_5020_50200801_14_dialog_content = "Bukan hanya aku... Tapi, begitu juga dengan seluruh anggota Wisp.",
  ui_story_5020_50200801_15_dialog_content = "Sudah berapa tahun...?",
  ui_story_5020_50200801_16_dialog_content = "Sepuluh tahun.",
  ui_story_5020_50200801_17_dialog_content = "Sepuluh tahun?! Hahaha! Memang sudah lama, ya?",
  ui_story_5020_50200801_18_dialog_content = "Aku ingat bagaimana kamu saat itu... lebih pendek dari pedangku. Saya selalu khawatir angin sepoi-sepoi akan meniup Anda pergi.",
  ui_story_5020_50200801_19_dialog_content = "Sekarang setelah Anda tumbuh dan lebih terampil, saya tidak dapat melepaskan Anda meskipun saya menginginkannya.",
  ui_story_5020_50200801_20_dialog_content = "Master...",
  ui_story_5020_50200801_21_dialog_content = "Sayangnya, sepertinya kau belum bertambah pintar.",
  ui_story_5020_50200801_22_dialog_content = "\"Memikul bebanku\"... Apa maksudmu?",
  ui_story_5020_50200801_23_dialog_content = "M-membantumu untuk mewujudkan cita-citamu.",
  ui_story_5020_50200801_24_dialog_content = "Mengembalikan Koufu-jou ke penguasanya yang berhak.",
  ui_story_5020_50200801_25_dialog_content = "Hahahaha! Begitu rupanya!",
  ui_story_5020_50200801_26_dialog_content = "Jadi, itu alasanmu menyelamatkanku?",
  ui_story_5020_50200801_27_dialog_content = "Kau mau aku mengakhiri semua ini. Iya?",
  ui_story_5020_50200801_28_dialog_content = "Berharap aku bisa memimpinmu dan yang lain dalam pertempuran besar melawan Jenderal, membawakan pedangku, dan menyatakan kastel itu sebagai milikku... Begitukah?",
  ui_story_5020_50200801_29_dialog_content = "K-Dengan bantuanmu, Guru, kami...",
  ui_story_5020_50200801_30_dialog_content = "Cukup.",
  ui_story_5020_50200801_31_dialog_content = "Bayanganmu tentang mastermu sangat tidak realistis, Nak.",
  ui_story_5020_50200801_32_dialog_content = "Aku bukan orang yang suci... Sebenarnya, jauh dari itu.",
  ui_story_5020_50200801_33_dialog_content = "Jangan merantai saya dengan harapan dan impian Anda dan buat saya memainkan gagasan Anda tentang \"keadilan\".",
  ui_story_5020_50200801_34_dialog_content = "...",
  ui_story_5020_50200801_35_dialog_content = "Tapi Guru, semua yang telah Anda lakukan...",
  ui_story_5020_50200801_36_dialog_content = "Ya, saya telah menentang jenderal selama ini.",
  ui_story_5020_50200801_37_dialog_content = "Tapi sebenarnya... Aku melakukan semuanya untuk diriku sendiri. Bukan untuk rakyat, bukan untuk keadilan, atau untuk alasan mulia apa pun yang mungkin Anda yakini.",
  ui_story_5020_50200801_38_dialog_content = "Aku tak pernah bisa memikul beban semacam itu di pundakku.",
  ui_story_5020_50200801_39_dialog_content = "...",
  ui_story_5020_50200801_40_dialog_content = "Sejujurnya, aku selalu merasa tidak pantas menjadi komandan Wisp.",
  ui_story_5020_50200801_41_dialog_content = "Saat kuputuskan untuk memimpin, itu hanya karena tak ada yang lebih kuat dariku.",
  ui_story_5020_50200801_42_dialog_content = "Tapi, tanggung jawab seperti itu hanya membuatku pusing dan lelah.",
  ui_story_5020_50200801_43_dialog_content = "Tidak... Kurasa aku lebih suka menyerbu Main Castle sendirian.",
  ui_story_5020_50200801_44_dialog_content = "Melihat kekuatan kastel itu tercerai-berai untuk menyelamatkan diri sendiri... meskipun tak seorang pun dari mereka bisa menghentikanku.",
  ui_story_5020_50200801_45_dialog_content = "Melakukan apapun yang saya suka... Ya, itulah yang harus saya lakukan.",
  ui_story_5020_50200801_46_dialog_content = "Bagaimana denganmu, Amemori?",
  ui_story_5020_50200801_47_dialog_content = "Apa yang sebenarnya ingin kaulakukan?",
  ui_story_5020_50200801_48_dialog_content = "Aku...",
  ui_story_5020_50200801_49_dialog_content = "Tak pernah memikirkannya, ya?",
  ui_story_5020_50200801_50_dialog_content = "...",
  ui_story_5020_50200801_51_dialog_content = "Saya selalu ingin menjadi seperti Anda, Guru.",
  ui_story_5020_50200801_52_dialog_content = "Oh?",
  ui_story_5020_50200801_53_dialog_content = "Semua orang di Wisp memperlakukan saya sebagai penerus Anda.",
  ui_story_5020_50200801_54_dialog_content = "Aku... telah melakukan apa yang mereka harapkan dariku selama ini, mencoba mengisi ruang yang kau tinggalkan.",
  ui_story_5020_50200801_55_dialog_content = "Tapi tanggung jawabnya terlalu besar untukku... Tidak peduli seberapa keras aku berusaha, aku tidak akan pernah bisa menggantikan posisimu, Guru.",
  ui_story_5020_50200801_56_dialog_content = "...",
  ui_story_5020_50200801_57_dialog_content = "Karena itulah... saat kau akhirnya dibebaskan dari Sealed Ground, aku merasa sangat lega.",
  ui_story_5020_50200801_58_dialog_content = "Kupikir aku sudah menyelesaikan misiku.",
  ui_story_5020_50200801_59_dialog_content = "Oh, gadis bodohku... Kau lebih dari sekadar penggantiku.",
  ui_story_5020_50200801_60_dialog_content = "Di bawah komandoku, Wisp selalu berhadapan dengan masalah dan kekalahan... Tapi, kau memimpin mereka selama sepuluh tahun terakhir.",
  ui_story_5020_50200801_61_dialog_content = "Kau justru melakukannya dengan lebih baik daripada aku.",
  ui_story_5020_50200801_62_dialog_content = "B-bagaimana bisa...?",
  ui_story_5020_50200801_63_dialog_content = "Misimu berikutnya... adalah mencari tahu apa tujuanmu sendiri.",
  ui_story_5020_50200801_64_dialog_content = "Itu tak bisa kuajarkan.",
  ui_story_5020_50200801_65_dialog_content = "...",
  ui_story_5020_50200801_66_dialog_content = "Baiklah sekarang. Jangan berdiri di sana terlihat seperti orang bodoh. Bagaimanapun, Anda adalah murid saya.",
  ui_story_5020_50200801_67_dialog_content = "Pergilah dan urus urusanmu sendiri.",
  ui_story_5020_50200801_68_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_69_dialog_content = "...",
  ui_story_5020_50200801_70_dialog_content = "Kenapa kamu masih mengikutiku?",
  ui_story_5020_50200801_71_dialog_content = "Saya masih belum memutuskan apa yang ingin saya lakukan... Jadi saya memutuskan untuk mengikuti Anda untuk saat ini, Guru.",
  ui_story_5020_50200801_72_dialog_content = "Apa-apaan kau...!",
  ui_story_5020_50200801_73_dialog_content = "*Berdesah* ... Baiklah. Ayo.",
  ui_story_5020_50200801_74_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_75_dialog_content = "Petik bunga merah untuk gadis muda itu...",
  ui_story_5020_50200801_76_dialog_content = "Kelopak bunga...",
  ui_story_5020_50200801_77_dialog_content = "Kelopak berguguran seperti butiran salju di atas sebongkah giok.",
  ui_story_5020_50200801_78_dialog_content = "...",
  ui_story_5020_50200801_79_dialog_content = "Aku baru ingat... Suara nyanyianmu selalu bagus, sejak kecil.",
  ui_story_5020_50200801_80_dialog_content = "Sepertinya suaramu makin merdu saja sekarang.",
  ui_story_5020_50200801_81_dialog_content = "Te-Terima kasih, Guru.",
  ui_story_5020_50200801_82_dialog_content = "Kalau yang satu lagi... Jangankan menyanyikannya dengan merdu, mengingat liriknya saja bahkan tidak bisa.",
  ui_story_5020_50200801_83_dialog_content = "... Sejak itu, makin banyak yang dilupakannya.",
  ui_story_5020_50200801_84_dialog_content = "Aku tahu itu. Bagaimanapun, dia selalu lebih baik dalam belajar dengan tinjunya. Ketika datang untuk bertarung, dia adalah seorang jenius dalam haknya sendiri.",
  ui_story_5020_50200801_85_dialog_content = "Dulu kau tak pernah bisa mengalahkannya... Bagaimana kalau sekarang?",
  ui_story_5020_50200801_86_dialog_content = "...",
  ui_story_5020_50200801_87_dialog_content = "Nah, karena Anda bersikeras mengikuti saya, saya punya pekerjaan untuk Anda.",
  ui_story_5020_50200801_88_dialog_content = "Bantu aku menarik tali ini.",
  ui_story_5020_50200801_89_dialog_content = "T-Tapi Tuan, ini milik orang lain...",
  ui_story_5020_50200801_90_dialog_content = "Aku tahu! Aku hanya pinjam sebentar, tidak bermaksud menyimpannya selamanya!",
  ui_story_5020_50200801_91_dialog_content = "Ayo, kita tarik bersama-sama!",
  ui_story_5020_50200801_92_dialog_content = "<color=#e8d9bb>Wiss... Bruk!</color>",
  ui_story_5020_50200801_93_dialog_content = "Bagus, sekarang bantu aku membawa tali ini.",
  ui_story_5020_50200801_94_dialog_content = "... Baiklah.",
  ui_story_5020_50200801_95_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_96_dialog_content = "Omong-omong...",
  ui_story_5020_50200801_97_dialog_content = "Setelah aku menghilang...",
  ui_story_5020_50200801_98_dialog_content = "Apa Jenderal mengadakan pemakaman?",
  ui_story_5020_50200801_99_dialog_content = "Pemakaman?",
  ui_story_5020_50200801_100_dialog_content = "Kurasa tidak...",
  ui_story_5020_50200801_101_dialog_content = "Oh... Begitu, ya.",
  ui_story_5020_50200801_102_dialog_content = "Untuk siapa pemakaman ini, Guru?",
  ui_story_5020_50200801_103_dialog_content = "...",
  ui_story_5020_50200801_104_dialog_content = "Namanya Tsuki. Kau masih ingat dia?",
  ui_story_5020_50200801_105_dialog_content = "Dia yang membawa kalian berdua padaku bertahun-tahun yang lalu.",
  ui_story_5020_50200801_106_dialog_content = "Ya, aku ingat.",
  ui_story_5020_50200801_107_dialog_content = "Saya percaya dia adalah kakak perempuan Anda ... bukan?",
  ui_story_5020_50200801_108_dialog_content = "Dia yang merawat kami saat kami masih kecil.",
  ui_story_5020_50200801_109_dialog_content = "Seingatku, dia orang yang lembut dan penyayang.",
  ui_story_5020_50200801_110_dialog_content = "Benar... Memang seperti itulah dia.",
  ui_story_5020_50200801_111_dialog_content = "Bagaimana dia meninggal?",
  ui_story_5020_50200801_112_dialog_content = "...",
  ui_story_5020_50200801_113_dialog_content = "Aku membunuhnya.",
  ui_story_5020_50200801_114_dialog_content = "!!!",
  ui_story_5020_50200801_115_dialog_content = "Karena dia pendeta.",
  ui_story_5020_50200801_116_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_117_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_118_dialog_content = "Sejak awal, aku sudah melarangnya jadi pendeta.",
  ui_story_5020_50200801_119_dialog_content = "Tapi Tsuki tidak pernah mendengarkanku. Dia lebih tua dan selalu berpikir dia lebih pintar dari adik perempuannya.",
  ui_story_5020_50200801_120_dialog_content = "Dia bilang seorang pendeta bisa membawa kedamaian ke Cloud Island.",
  ui_story_5020_50200801_121_dialog_content = "Tapi aku selalu menertawakannya, mengatakan bahwa para pendeta hanyalah alat bagi para jenderal... Bahwa satu-satunya cara untuk membawa perdamaian ke Cloud Island adalah dengan pedang.",
  ui_story_5020_50200801_122_dialog_content = "Pada akhirnya, karena tak bisa meyakinkan satu sama lain, kami memutuskan untuk menempuh jalan yang masing-masing yakini.",
  ui_story_5020_50200801_123_dialog_content = "Dia pergi ke pulau utama demi menjalani pelatihan resmi, sedangkan aku... aku mengembara, membantai hantu yang tak terhitung jumlahnya untuk mengasah kemampuan.",
  ui_story_5020_50200801_124_dialog_content = "Beberapa tahun kemudian, dia menjadi pendeta Jenderal, dan aku menjadi Sword of the Underworld.",
  ui_story_5020_50200801_125_dialog_content = "...",
  ui_story_5020_50200801_126_dialog_content = "Lain kali kami bertemu satu sama lain, dia tidak membuang waktu untuk mengenang masa lalu. Yang dia katakan hanyalah dia ingin melihat siapa yang lebih baik dalam membunuh hantu.",
  ui_story_5020_50200801_127_dialog_content = "Saya hampir tidak bisa menahan tawa saya dan dengan senang hati menerima tantangannya.",
  ui_story_5020_50200801_128_dialog_content = "Hal terakhir yang kuharapkan adalah melihatnya dengan percaya diri mengeluarkan pedangnya.",
  ui_story_5020_50200801_129_dialog_content = "Itu adalah pedang terindah yang pernah kulihat. Kekuatan yang dipancarkannya menyala-nyala seperti matahari... Benda itu seolah-olah dibuat untuk membantai iblis dan kegelapan.",
  ui_story_5020_50200801_130_dialog_content = "Tentu saja, aku kalah telak. Heh... Aku ingat Tsuki sangat bangga karena bisa menang. Dia menari-nari di dekatku dan berkata—",
  ui_story_5020_50200801_131_dialog_content = "\"Sudah kubilang, seorang pendeta bisa membawa kedamaian ke Cloud Island!\"",
  ui_story_5020_50200801_132_dialog_content = "Saat itu... Aku benar-benar percaya dia bisa melakukannya.",
  ui_story_5020_50200801_133_dialog_content = "Menakjubkan... Seseorang bahkan bisa mengalahkanmu, Guru...",
  ui_story_5020_50200801_134_dialog_content = "Jika bukan karena pedang itu, dia tidak akan pernah bisa mengalahkanku!",
  ui_story_5020_50200801_135_dialog_content = "Sepotong Surga, Pedang Pembantai Hantu... Bahkan anak berusia tiga tahun bisa menembus sebagian besar hantu dengan pedang di tangan, apalagi adikku.",
  ui_story_5020_50200801_136_dialog_content = "Sayangnya, itu terakhir kali saya melihat Sepotong Surga.",
  ui_story_5020_50200801_137_dialog_content = "Setelah itu, fokusnya beralih dari mengusir hantu. Itu hanya menjadi alat untuk mencapai tujuan.",
  ui_story_5020_50200801_138_dialog_content = "...",
  ui_story_5020_50200801_139_dialog_content = "Dia mulai menggunakan Cloud Mirror agar seolah-olah dia mengusir hantu.",
  ui_story_5020_50200801_140_dialog_content = "Tapi aku tahu itu semua hanya akting.",
  ui_story_5020_50200801_141_dialog_content = "Sepuluh tahun lalu, selama Festival Kasuga... dia menggunakan Cloud Mirror untuk memanggil para hantu hanya agar dia bisa mengalahkan mereka di depan semua orang. Tsuki benar-benar tampak menikmati pertunjukan kecil itu.",
  ui_story_5020_50200801_142_dialog_content = "Tapi, aku tahu yang sebenarnya... Sayangnya, tak seorang pun menyadarinya. Mereka termakan muslihatnya.",
  ui_story_5020_50200801_143_dialog_content = "Mereka semua percaya bahwa pendeta akan membawa kedamaian ke Koufu-jou, dan bahwa Jenderal yang melatihnya memang pantas memimpin kami.",
  ui_story_5020_50200801_144_dialog_content = "Pada saat itu, saya menyadari bahwa hambatan terbesar kami untuk mewujudkan impian perdamaian kami... adalah satu sama lain.",
  ui_story_5020_50200801_145_dialog_content = "Seluruh anggota Wisp mulai lengah, beberapa bahkan benar-benar kehilangan semangat untuk melawan. Mereka memilih untuk menjadi anak buah Jenderal yang penurut dan patuh.",
  ui_story_5020_50200801_146_dialog_content = "Dibandingkan dengan penindasan yang kuat... ini adalah takdir yang jauh lebih menakutkan.",
  ui_story_5020_50200801_147_dialog_content = "Kenapa?",
  ui_story_5020_50200801_148_dialog_content = "Jika sang jenderal membunuh sepuluh dari kita sendiri, anak-anak mereka akan mewarisi kebencian mereka terhadapnya, dan mempertahankan perlawanan hingga masa depan.",
  ui_story_5020_50200801_149_dialog_content = "Tapi, setelah dibodohi oleh pendeta itu, mereka lupa semua kebencian dan apa yang sesungguhnya menjadi hak mereka... Dan, begitulah, mereka menjadi ternak peliharaan sang Jenderal.",
  ui_story_5020_50200801_150_dialog_content = "Wisp tidak takut kalah. Kami tidak pernah benar-benar memenangkan pertempuran apa pun, tetapi kami juga tidak pernah kehilangan keinginan untuk melawan.",
  ui_story_5020_50200801_151_dialog_content = "Yang paling kami takuti adalah rasa puas diri... asimilasi... dan perubahan hati.",
  ui_story_5020_50200801_152_dialog_content = "Sedikit demi sedikit, hal-hal kecil ini melunturkan tekad prajurit untuk bertarung.",
  ui_story_5020_50200801_153_dialog_content = "Dan, saat itu terjadi, tak seorang pun akan ingat siapa kita, atau apa yang sudah kita capai...",
  ui_story_5020_50200801_154_dialog_content = "Meski mungkin masih dikenal dengan nama Cloud Island, pulau ini sudah kehilangan semua jati dirinya.",
  ui_story_5020_50200801_155_dialog_content = "...",
  ui_story_5020_50200801_156_dialog_content = "Karena itulah... aku memberi tahu semua orang, termasuk dirimu, bahwa pendeta itu harus mati.",
  ui_story_5020_50200801_157_dialog_content = "Jenderal tidak pernah bisa benar-benar mengalahkan kita, tetapi pendeta adalah cerita yang berbeda.",
  ui_story_5020_50200801_158_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_159_dialog_content = "Baiklah... Ini dia.",
  ui_story_5020_50200801_160_dialog_content = "Bantu aku. Ambil saja semua <color=#FFB400>anggur</color> di dalam sini.",
  ui_story_5020_50200801_161_dialog_content = "Ikat semua botolnya jadi satu dengan tali itu...",
  ui_story_5020_50200801_162_dialog_content = "... Tapi, Master, ini jelas-jelas...",
  ui_story_5020_50200801_163_dialog_content = "Oh, istirahatlah, ya? Saya kebetulan tahu pemilik toko ini! Kami kembali bertahun-tahun!",
  ui_story_5020_50200801_164_dialog_content = "Saya meninggalkan catatan di atas meja yang mengatakan bahwa kami akan membayarnya nanti.",
  ui_story_5020_50200801_165_dialog_content = "Sekarang mari kita bergerak.",
  ui_story_5020_50200801_166_dialog_content = "...",
  ui_story_5020_50200801_167_dialog_content = "<color=#e8d9bb>Hmm...</color>",
  ui_story_5020_50200801_168_dialog_content = "Fiuh...",
  ui_story_5020_50200801_169_dialog_content = "Begini mestinya cukup! Rapi dan kencang!",
  ui_story_5020_50200801_170_dialog_content = "Sekarang, angkut semua dan ikuti aku.",
  ui_story_5020_50200801_171_dialog_content = "Kalau terlalu berat, bilang saja padaku. Aku bisa membantumu membawanya.",
  ui_story_5020_50200801_172_dialog_content = "Aku... aku bisa mengatasinya.",
  ui_story_5020_50200801_173_dialog_content = "Yakin? Dari sini, jalan kita akan makin sulit.",
  ui_story_5020_50200801_174_dialog_content = "Kita mau ke mana?",
  ui_story_5020_50200801_175_dialog_content = "Ke <color=#FFB400>Main Castle</color>.",
  ui_story_5020_50200801_176_dialog_content = "Ke Main Castle?!",
  ui_story_5020_50200801_177_dialog_content = "Ya.",
  ui_story_5020_50200801_178_dialog_content = "Sudah pernah naik ke atap kastel itu? Pemandangan dari sana luar biasa... Tempat yang sempurna untuk duduk-duduk sambil minum-minum.",
  ui_story_5020_50200801_179_dialog_content = "Menyerbu kastil seharusnya tidak terlalu menjadi masalah bagi muridku tersayang, kan?",
  ui_story_5020_50200801_180_dialog_content = "Tentu saja...",
  ui_story_5020_50200801_181_dialog_content = "Ke mana pun Master pergi, aku akan ikut.",
  ui_story_5020_50200801_182_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat, pit-pat...</color>",
  ui_story_5020_50200801_183_dialog_content = "Ke sini lagi, ya?",
  ui_story_5020_50200801_184_dialog_content = "Sepuluh tahun yang lalu, saya berjalan di jalan yang sama ini, menyaksikan kastil semakin besar dan semakin besar saat saya mendekatinya.",
  ui_story_5020_50200801_185_dialog_content = "Itu berdiri sangat tinggi sehingga menutupi matahari dan bulan, dan membuat orang bertanya-tanya apakah mereka bisa menemukan jalan keluar begitu mereka menginjakkan kaki di dalamnya.",
  ui_story_5020_50200801_186_dialog_content = "Tapi Anda tidak pernah bermaksud menemukan jalan keluar saat itu, bukan?",
  ui_story_5020_50200801_187_dialog_content = "Kau bahkan meninggalkan Rebellion dan Ryojin Jade untuk kami.",
  ui_story_5020_50200801_188_dialog_content = "Heh... Kau memang benar.",
  ui_story_5020_50200801_189_dialog_content = "Batu giok Pemberontakan dan Ryojin terlalu berharga untuk berisiko jatuh ke tangan sang jenderal.",
  ui_story_5020_50200801_190_dialog_content = "Meski sudah tahu risikonya... kau tetap memilih untuk membunuhnya?",
  ui_story_5020_50200801_191_dialog_content = "Kakakmu sendiri...",
  ui_story_5020_50200801_192_dialog_content = "Benar... Kakakku sendiri.",
  ui_story_5020_50200801_193_dialog_content = "Kurasa kami berdua sudah tahu bahwa hal itu memang sudah ditakdirkan untuk terjadi hari itu.",
  ui_story_5020_50200801_194_dialog_content = "Saya siap mati, dan dia siap mati di tangan saya.",
  ui_story_5020_50200801_195_dialog_content = "Saya pikir kami berdua akan menemui tujuan kami di Cloud Pavilion hari itu, keduanya mati demi mengejar perdamaian untuk Cloud Island.",
  ui_story_5020_50200801_196_dialog_content = "Tapi tak disangka...",
  ui_story_5020_50200801_197_dialog_content = "Dia tidak ingin aku mati...",
  ui_story_5020_50200801_198_dialog_content = "Dan saya juga tidak ingin mati lagi.",
  ui_story_5020_50200801_199_dialog_content = "?!",
  ui_story_5020_50200801_200_dialog_content = "Ada satu orang lagi yang harus saya bawa.",
  ui_story_5020_50200801_201_dialog_content = "...",
  ui_story_5020_50200801_202_dialog_content = "Apakah itu... Jenderal Fujikumo?",
  ui_story_5020_50200801_203_dialog_content = "Tentu saja. Memangnya siapa lagi?",
  ui_story_5020_50200801_204_dialog_content = "Pada hari Tsuki mati, aku akhirnya sadar apa yang selama itu membuatnya berubah begitu banyak.",
  ui_story_5020_50200801_205_dialog_content = "Dia menaruh kepercayaannya pada seseorang, dan memercayai mereka sampai nafas terakhirnya.",
  ui_story_5020_50200801_206_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_207_dialog_content = "Aku ingin percaya bahwa dia sudah gila atau terpaksa menjalankan tugasnya...",
  ui_story_5020_50200801_208_dialog_content = "Tapi... dia benar-benar waras dan bersedia membiarkan Fujikumo menipunya.",
  ui_story_5020_50200801_209_dialog_content = "Meskipun dia tahu tindakannya salah, dia terus percaya padanya dan kebohongannya.",
  ui_story_5020_50200801_210_dialog_content = "Seseorang... telah menyandera rasa benar dan salah kakakku.",
  ui_story_5020_50200801_211_dialog_content = "Aku benci itu.",
  ui_story_5020_50200801_212_dialog_content = "Aku benci Fujikumo memanfaatkan cinta Tsuki.",
  ui_story_5020_50200801_213_dialog_content = "Saya pikir saya sudah menyebutkannya sebelumnya. Saya selalu melakukan apapun yang saya inginkan.",
  ui_story_5020_50200801_214_dialog_content = "Antara dia dan aku, setidaknya salah satu dari kami sekarat.",
  ui_story_5020_50200801_215_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50200801_216_dialog_content = "Kita sudah sampai.",
  ui_story_5020_50200801_217_dialog_content = "Mestinya sekarang kau sudah cukup mahir memanjat, 'kan?",
  ui_story_5020_50200801_218_dialog_content = "Ya.",
  ui_story_5020_50200801_219_dialog_content = "Baiklah! Coba kita lihat siapa yang bisa sampai ke atas duluan!",
  ui_story_5020_50200801_220_dialog_content = "... Saya masih membawa semua alkohol ini, Guru.",
  ui_story_5020_50200801_221_dialog_content = "Aku hanya bercanda! Kau juga pastinya tak mau balapan melawan Mastermu, 'kan?",
  ui_story_5020_50200801_222_dialog_content = "...",
  ui_story_5020_50200801_223_dialog_content = "<color=#e8d9bb>Pit... Pat... Pit... Pat...</color>",
  ui_story_5020_50200801_224_dialog_content = "Master... Apa kau pernah merasa menyesal karena sudah membunuh Tsuki?",
  ui_story_5020_50200801_225_dialog_content = "Tentu saja tidak. Aku tak pernah menyesal.",
  ui_story_5020_50200801_226_dialog_content = "Kalau begitu, kenapa kau tak bertanya tentang pemakamannya?",
  ui_story_5020_50200801_227_dialog_content = "...",
  ui_story_5020_50200801_228_dialog_content = "Aku memang tidak menyesal sudah membunuhnya, tapi...",
  ui_story_5020_50200801_229_dialog_content = "Tetap saja, dia kakakku. Mestinya akulah yang menguburkannya.",
  ui_story_5020_50200801_230_dialog_content = "Begitu rupanya...",
  ui_story_5020_50200801_231_dialog_content = "Dan, ada satu hal lagi.",
  ui_story_5020_50200801_232_dialog_content = "Sepotong Surga adalah miliknya. Jadi jika saya harus menebak, itu mungkin terkubur bersamanya.",
  ui_story_5020_50200801_233_dialog_content = "Lagi pula, pedang itu dibuat untuk membasmi hantu. Tak ada gunanya untuk sang Jenderal.",
  ui_story_5020_50200801_234_dialog_content = "Anda ingin menemukan Sepotong Surga, Guru?",
  ui_story_5020_50200801_235_dialog_content = "Benar.",
  ui_story_5020_50200801_236_dialog_content = "Tsuki pasti akan gelisah di dalam kuburnya kalau sampai dia tahu bahwa pedang kesayangannya dibiarkan berkarat di bawah onggokan tanah.",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>Pit... Pat...</color>",
  ui_story_5020_50200801_238_dialog_content = "Fyuh! Sudah lama sekali aku tak memanjat ke sini!",
  ui_story_5020_50200801_239_dialog_content = "Baiklah, Nak, lepas ikatan botol itu, lalu ulurkan satu untukku.",
  ui_story_5020_50200801_240_dialog_content = "Coba kita lihat apa minuman milik teman lamaku ini bertambah sedap dalam satu dekade terakhir.",
  ui_story_5020_50200801_241_dialog_content = "Ya...",
  ui_story_5020_50200801_242_dialog_content = "Eh... Memangnya kau sudah cukup umur untuk minum minuman beralkohol?",
  ui_story_5020_50200801_243_dialog_content = "Aku... Aku tidak bisa minum alkohol.",
  ui_story_5020_50200801_244_dialog_content = "Membosankan sekali.",
  ui_story_5020_50200801_245_dialog_content = "Ah, sudahlah. Ulurkan saja sebotol untukku, dan <color=#FFB400>hancurkan</color> saja sisanya.",
  ui_story_5020_50200801_246_dialog_content = "Hancurkan? Tapi, kenapa...?",
  ui_story_5020_50200801_247_dialog_content = "Kau berani menyanggahku? Kalau kusuruh kau untuk menghancurkan botol-botol itu, hancurkan saja langsung! Paham?",
  ui_story_5020_50200801_248_dialog_content = "... Baiklah.",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>Krak!!</color>",
  ui_story_5020_50200801_252_dialog_content = "Hahahahaha! Nah, begitu, dong!",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>Glug... Glug...</anim>",
  ui_story_5020_50200801_254_dialog_content = "Fuaaahh! Ini baru minuman enak!",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>Pit... Pat... Pit... Pat...</color>",
  ui_story_5020_50200801_256_dialog_content = "Tolong cobalah untuk tidak jatuh, Guru.",
  ui_story_5020_50200801_257_dialog_content = "Hah! Memangnya kaukira aku ini siapa, hah?",
  ui_story_5020_50200801_258_dialog_content = "Nah, sekarang, lihat ke bawah sana, Amemori.",
  ui_story_5020_50200801_259_dialog_content = "Kaulihat pria yang berjalan di sana? Menurutmu, siapa dia?",
  ui_story_5020_50200801_260_dialog_content = "...",
  ui_story_5020_50200801_261_dialog_content = "Itu Fujikumo.",
  ui_story_5020_50200801_262_dialog_content = "Sedang apa dia?",
  ui_story_5020_50200801_263_dialog_content = "Aku akan memberitahumu sesuatu. Musuh paling memahami satu sama lain.",
  ui_story_5020_50200801_264_dialog_content = "Dari jarak sejauh ini sekalipun, di atas atap bangunan yang terpisah jauh... aku tetap bisa memahami apa yang sedang berkecamuk dalam pikirannya saat ini.",
  ui_story_5020_50200801_265_dialog_content = "Saat ini, dia pasti berpikir bahwa dia sedang menuju perdamaian.",
  ui_story_5020_50200801_266_dialog_content = "Kenapa?",
  ui_story_5020_50200801_267_dialog_content = "Karena aku sendiri juga akan berpikir persis seperti itu.",
  ui_story_5020_50200801_268_dialog_content = "!!!",
  ui_story_5020_50200801_269_dialog_content = "Tapi Guru...",
  ui_story_5020_50200801_270_dialog_content = "Ayolah! Minum-minum sendirian tidak seru, tahu!",
  ui_story_5020_50200801_271_dialog_content = "Jika muridku sendiri tidak mau minum denganku, aku hanya perlu meminta semua Koufu-jou sebagai gantinya!",
  ui_story_5020_50200901_1_dialog_content = "Jenderal! Pasukan utama Wisp berhasil ditangkap. Saat ini, mereka sedang menuju ke kastel.",
  ui_story_5020_50200901_2_dialog_content = "Sudah kuduga.",
  ui_story_5020_50200901_3_dialog_content = "Hari ini, bendera pemberontakan akan dibakar menjadi abu.",
  ui_story_5020_50200901_4_dialog_content = "Beri tahu warga! Perintahkan mereka untuk datang ke kastel dan menyaksikan keadilan ditegakkan atas para pengkhianat itu!",
  ui_story_5020_50200901_5_dialog_content = "Setelah malam mencekam ini, harus ada orang yang bertanggung jawab atas kekacauan yang mengancam kota kita yang tenang ini.",
  ui_story_5020_50200901_6_dialog_content = "Kami masih memiliki Festival Kasuga saat fajar.",
  ui_story_5020_50200901_7_dialog_content = "Siap, Jenderal.",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>Kathunk... Kathunk...</color>",
  ui_story_5020_50200901_9_dialog_content = "Hai! Apakah kita benar-benar pergi ke suatu tempat dengan lebih sedikit orang?",
  ui_story_5020_50200901_10_dialog_content = "Kenapa rasanya situasi malah jadi makin ramai di sini?",
  ui_story_5020_50200901_11_dialog_content = "Kita tak bisa berbuat apa-apa, PlayerName.",
  ui_story_5020_50200901_12_dialog_content = "Mendorong drum besar itu akan terlalu mencolok. Taruhan terbaik kami adalah bersembunyi di kerumunan dan mengikuti mereka.",
  ui_story_5020_50200901_13_dialog_content = "Baiklah, jadi... Sebenarnya kita mau ke mana?",
  ui_story_5020_50200901_14_dialog_content = "Mestinya kita...",
  ui_story_5020_50200901_15_dialog_content = "Tepat di luar kastil.",
  ui_story_5020_50200901_16_dialog_content = "Apa?! Kau mau kita semua mati, ya?!",
  ui_story_5020_50200901_17_dialog_content = "Jangan khawatir, kita akan cari jalan keluarnya!",
  ui_story_5020_50200901_18_dialog_content = "Jika yang terburuk menjadi yang terburuk, Anda hanya perlu bersembunyi sampai akhir Festival Kasuga...",
  ui_story_5020_50200901_19_dialog_content = "Anda benar-benar mencoba membuat kami terbunuh, bukan ?!",
  ui_story_5020_50200901_20_dialog_content = "<size=45>Kosongkan jalan!</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>Minggir dari jalan kami!</size>",
  ui_story_5020_50200901_22_dialog_content = "Sekarang, apa lagi?",
  ui_story_5020_50200901_23_dialog_content = "Samurai itu memimpin sekelompok besar orang kemari!",
  ui_story_5020_50200901_24_dialog_content = "Sebentar, bukankah mereka...?",
  ui_story_5020_50200901_25_dialog_content = "Benar! Itu Wisp!",
  ui_story_5020_50200901_26_dialog_content = "Wisp?!",
  ui_story_5020_50200901_27_dialog_content = "Apa mereka semua tertangkap?",
  ui_story_5020_50200901_28_dialog_content = "Kelihatannya memang begitu...",
  ui_story_5020_50200901_29_dialog_content = "Mereka menuju kastil juga.",
  ui_story_5020_50200901_30_dialog_content = "Kastel... Apa yang akan dilakukan sang Jenderal kepada mereka?",
  ui_story_5020_50200901_31_dialog_content = "Dia akan menggunakan mereka sebagai kambing hitam. Seseorang bagi publik untuk mengarahkan kemarahan dan ketakutan mereka.",
  ui_story_5020_50200901_32_dialog_content = "Tapi, itu kan bukan salah mereka!",
  ui_story_5020_50200901_33_dialog_content = "Apa warga akan percaya padanya?",
  ui_story_5020_50200901_34_dialog_content = "Sang Jenderal punya kendali penuh atas hantu dan bisa memanggil serta mengusir mereka sesuka hatinya.",
  ui_story_5020_50200901_35_dialog_content = "Sekarang Wisp telah ditangkap, dia dapat dengan mudah menghentikan serangan dan membuat orang percaya bahwa para pemberontak bertanggung jawab.",
  ui_story_5020_50200901_36_dialog_content = "Mau tak mau, mereka pasti akan percaya padanya.",
  ui_story_5020_50200901_37_dialog_content = "Tapi, kalau sampai itu terjadi...",
  ui_story_5020_50200901_38_dialog_content = "Kalau sampai itu terjadi...",
  ui_story_5020_50200901_39_dialog_content = "Hah?",
  ui_story_5020_50200901_40_dialog_content = "Maka, tak akan ada lagi hantu yang perlu diusir dari Koufu-jou...",
  ui_story_5020_50200901_41_dialog_content = "Bukankah itu... bagus?",
  ui_story_5020_50200901_42_dialog_content = "Benar juga katamu...",
  ui_story_5020_50200901_43_dialog_content = "Ini adalah taktik penguasa yang dingin dan tanpa ampun.",
  ui_story_5020_50200901_44_dialog_content = "Dia berkorban dan mengkhianati orang lain tanpa ragu-ragu.",
  ui_story_5020_50200901_45_dialog_content = "Tapi, pada akhirnya... situasi akan tampak lebih baik, setidaknya di luarnya.",
  ui_story_5020_50200901_46_dialog_content = "...",
  ui_story_5020_50200901_47_dialog_content = "Tapi, hanya di luarnya, 'kan?",
  ui_story_5020_50200901_48_dialog_content = "Orang-orang di Cloud Island percaya akan keberadaan jiwa dengan sepenuh hati.",
  ui_story_5020_50200901_49_dialog_content = "Jika semuanya berjalan seperti yang saya perkirakan, semua orang akan hidup di dunia ilusi sang jenderal, bahagia dan tanpa beban.",
  ui_story_5020_50200901_50_dialog_content = "Tetapi jiwa yang hidup dalam ketidaktahuan yang berdosa akan kebenaran yang begitu mengerikan tidak berbeda dengan kematian.",
  ui_story_5020_50200901_51_dialog_content = "Aku yakin, siapa pun yang tahu kebenarannya tak akan tinggal diam dan menerima mentah-mentah.",
  ui_story_5020_50200901_52_dialog_content = "Itu benar! Bagaimana bisa seluruh kota hidup di bawah ilusi kebohongan seperti itu?",
  ui_story_5020_50200901_53_dialog_content = "Semua orang harus tahu kebenarannya!",
  ui_story_5020_50200901_54_dialog_content = "...",
  ui_story_5020_50200901_55_dialog_content = "Kalian berdua benar sekali.",
  ui_story_5020_50200901_56_dialog_content = "Kedamaian yang dibangun di atas gunung kebohongan bukanlah kedamaian sama sekali.",
  ui_story_5020_50200901_57_dialog_content = "Kita harus menunjukkan kebenarannya kepada semua orang.",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>Pit-pat... Pit-pat...</color>",
  ui_story_5020_50200901_59_dialog_content = "Anzu, Momo... Kira-kira, apa kalian bisa menyusul tim Wisp itu?",
  ui_story_5020_50200901_60_dialog_content = "Menyusul mereka?",
  ui_story_5020_50200901_61_dialog_content = "Kalau bisa, berarti kita benar-benar tak punya peluang untuk melarikan diri, tahu.",
  ui_story_5020_50200901_62_dialog_content = "Kita tak akan melarikan diri. Tidak lagi.",
  ui_story_5020_50200901_63_dialog_content = "Aku tak mau melewatkan Festival Kasuga demi apa pun!",
  ui_story_5020_50200901_64_dialog_content = "Kudengar akan ada sejumlah penjahat yang akan diadili... Apa itu benar?",
  ui_story_5020_50200901_65_dialog_content = "Benar! Sang Jenderal sendiri yang bilang begitu!",
  ui_story_5020_50200901_66_dialog_content = "Akhirnya, para pengkhianat yang memanggil hantu-hantu itu akan mendapatkan ganjaran!",
  ui_story_5020_50200901_67_dialog_content = "Eh, lihat di sana! Mereka sedang dikawal ke alun-alun!",
  ui_story_5020_50200901_68_dialog_content = "Sebentar, apa itu benar mereka? Banyak sekali dari mereka yang kukenal!",
  ui_story_5020_50200901_69_dialog_content = "Bisa jadi sebenarnya mereka hanya dijadikan kambing hitam...",
  ui_story_5020_50200901_70_dialog_content = "Hmph! Jenderal pasti tahu bagaimana mengamankan posisinya.",
  ui_story_5020_50200901_71_dialog_content = "Yah, siapa pun yang bertanggung jawab atas semua ini memang harus dijatuhi hukuman berat...",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>Brak...!</color>",
  ui_story_5020_50200901_73_dialog_content = "Jenderal!",
  ui_story_5020_50200901_74_dialog_content = "Para pemberontak Wisp sudah tertangkap semua!",
  ui_story_5020_50200901_75_dialog_content = "Kami dengan rendah hati meminta Anda menghakimi mereka atas kejahatan keji mereka!",
  ui_story_5020_50200901_76_dialog_content = "Sudah beberapa dekade berlalu sejak aku pertama kali menjejakkan kaki di Koufu-jou.",
  ui_story_5020_50200901_77_dialog_content = "Saya sudah bosan dengan pertempuran terus-menerus dan tidak sedap dipandang yang mengelilingi saya sejak saat itu.",
  ui_story_5020_50200901_78_dialog_content = "Itu semua berakhir hari ini. Disini. Sekarang.",
  ui_story_5020_50200901_79_dialog_content = "Aku bisa melihat fajar perdamaian mendekat...",
  ui_story_5020_50200901_80_dialog_content = "Kedamaian...",
  ui_story_5020_50200901_81_dialog_content = "Dulu, saat perang mengancam kehidupan seluruh Koufu-jou, akulah yang mengakhirinya.",
  ui_story_5020_50200901_82_dialog_content = "Saat hantu-hantu mulai mengancam kehidupan kita, aku mulai melatih pendeta untuk membendung gangguan dari roh-roh gentayangan itu.",
  ui_story_5020_50200901_83_dialog_content = "Di bawah pemerintahanku, barulah seluruh Koufu-jou bisa hidup damai dan tenang.",
  ui_story_5020_50200901_84_dialog_content = "Tapi, selalu saja ada orang-orang yang tak pernah puas.",
  ui_story_5020_50200901_85_dialog_content = "Mereka mengusik ketertiban yang selama ini kujaga, dan menuntut lebih tanpa rasa malu sedikit pun!",
  ui_story_5020_50200901_86_dialog_content = "Sekarang, mereka berlutut di depan kita semua.",
  ui_story_5020_50200901_87_dialog_content = "...",
  ui_story_5020_50200901_88_dialog_content = "Wisp pemberontak, apakah Anda menyadari dosa-dosa Anda?",
  ui_story_5020_50200901_89_dialog_content = "Dosa?",
  ui_story_5020_50200901_90_dialog_content = "Sejujurnya, saya tidak tahu.",
  ui_story_5020_50200901_91_dialog_content = "Anda terdengar seperti Anda tahu, mengapa saya tidak memberi Anda kehormatan untuk memberi tahu kami?",
  ui_story_5020_50200901_92_dialog_content = "Tentu saja. Kalau begitu, akan kuberi tahu.",
  ui_story_5020_50200901_93_dialog_content = "Anda berkolusi dengan hantu ganas untuk mengganggu kedamaian dan ketertiban Koufu-jou.",
  ui_story_5020_50200901_94_dialog_content = "Kalian harus dihukum mati!",
  ui_story_5020_50200901_95_dialog_content = "Hah.",
  ui_story_5020_50200901_96_dialog_content = "Fujikumo, kamu tua...",
  ui_story_5020_50200901_97_dialog_content = "(Uh, permisi. Saya benci menyela ucapan Anda yang penuh gairah.)",
  ui_story_5020_50200901_98_dialog_content = "(Tapi, bisakah kau pura-pura bersikap lunak untuk mengulur waktu bagi kami?)",
  ui_story_5020_50200901_99_dialog_content = "(Akan sulit untuk menyelamatkanmu jika kamu langsung dieksekusi.)",
  ui_story_5020_50200901_100_dialog_content = "...",
  ui_story_5020_50200901_101_dialog_content = "(Anzu dan Momo akan melepaskanmu nanti. Ini satu-satunya kesempatan kita.)",
  ui_story_5020_50200901_102_dialog_content = "(Anda harus menaklukkan semua samurai sekaligus, atau kita semua kacau.)",
  ui_story_5020_50200901_103_dialog_content = "(Batuk jika Anda mengerti.)",
  ui_story_5020_50200901_104_dialog_content = "*Batuk-batuk*",
  ui_story_5020_50200901_105_dialog_content = "(Oke. Lanjutkan, buat dia sibuk.)",
  ui_story_5020_50200901_106_dialog_content = "Er... Tuanku, sewalah dengarkan aku.",
  ui_story_5020_50200901_107_dialog_content = "Silakan dan potong satu atau dua anggota badan, tetapi bisakah Anda menjaga kepala saya tetap di leher saya?",
  ui_story_5020_50200901_108_dialog_content = "...",
  ui_story_5020_50200901_109_dialog_content = "Aku punya dua tangan dan dua kaki. Ambil pilihanmu.",
  ui_story_5020_50200901_110_dialog_content = "Tapi saya masih menggunakan kepala saya, jadi saya ingin menyimpannya.",
  ui_story_5020_50200901_111_dialog_content = "Oke, jadi kita punya tiga samurai di sini... dan lima lagi di sana. Ada dua lagi di seberang jalan.",
  ui_story_5020_50200901_112_dialog_content = "Vice, dapatkah kamu mengingat semua itu?",
  ui_story_5020_50200901_113_dialog_content = "Tiga... Dan lima... Dan dua lagi...",
  ui_story_5020_50200901_114_dialog_content = "Anda harus mengingatnya. Kami tidak akan mendapatkan kesempatan kedua!",
  ui_story_5020_50200901_115_dialog_content = "Anzu dan Momo telah mengendurkan drumhead. Kita hanya perlu menyelaminya.",
  ui_story_5020_50200901_116_dialog_content = "Begitu kita keluar melalui drum, kita harus melumpuhkan semua samurai!",
  ui_story_5020_50200901_117_dialog_content = "Ini satu-satunya cara agar Anzu dan Momo bisa melepaskan ikatan Wisp.",
  ui_story_5020_50200901_118_dialog_content = "Siap! Tiga... Dan lima...",
  ui_story_5020_50200901_119_dialog_content = "Dan peran saya adalah menghentikan sang jenderal, bukan?",
  ui_story_5020_50200901_120_dialog_content = "Ya, aduk kekacauan sebanyak yang Anda bisa.",
  ui_story_5020_50200901_121_dialog_content = "Begitu jenderal memerintahkan hantu untuk menghentikan kita, kebenaran akan terungkap!",
  ui_story_5020_50200901_122_dialog_content = "Lalu? Bagaimana cara kita keluar dari sana setelah itu?",
  ui_story_5020_50200901_123_dialog_content = "Saya tidak bisa merencanakan sejauh itu. Kita harus berimprovisasi setelah itu!",
  ui_story_5020_50200901_124_dialog_content = "Anzu, Momo, kalian sudah siap?",
  ui_story_5020_50200901_125_dialog_content = "Yap!",
  ui_story_5020_50200901_126_dialog_content = "Kami memotong talinya, lalu kami lari dengan Wisp. Benar?",
  ui_story_5020_50200901_127_dialog_content = "Benar sekali!",
  ui_story_5020_50200901_128_dialog_content = "Sepertinya mereka tidak dalam kondisi yang baik...",
  ui_story_5020_50200901_129_dialog_content = "Apakah akan berbahaya?",
  ui_story_5020_50200901_130_dialog_content = "Beri tahu kami jika Anda dalam bahaya.",
  ui_story_5020_50200901_131_dialog_content = "Misalnya...",
  ui_story_5020_50200901_132_dialog_content = "Manfaatkan drum ini.",
  ui_story_5020_50200901_133_dialog_content = "Oh, benar! Dipahami.",
  ui_story_5020_50200901_134_dialog_content = "Aku suka menabuh drum!",
  ui_story_5020_50200901_135_dialog_content = "Sekarang kita hanya harus menunggu Vice untuk menghafal semuanya...",
  ui_story_5020_50200901_136_dialog_content = "Aku sudah siap!",
  ui_story_5020_50200901_137_dialog_content = "Baiklah!",
  ui_story_5020_50200901_138_dialog_content = "Siap-siap. Tiga...",
  ui_story_5020_50200901_139_dialog_content = "<size=40>Dua...</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>Satu...</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>Maju!</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>Duar...</size></color>",
  ui_story_5020_50200901_143_dialog_content = "Rapid Torrent!",
  ui_story_5020_50200901_144_dialog_content = "Selamatkan Wisp! Buru-buru!",
  ui_story_5020_50200901_145_dialog_content = "Iya, iya, aku tahu!",
  ui_story_5020_50200901_146_dialog_content = "Tolong! Ada yang berkelahi!",
  ui_story_5020_50200901_147_dialog_content = "Teman-teman, ambil senjata kalian!",
  ui_story_5020_50200901_148_dialog_content = "Pemberontak! Lindungi jenderal!",
  ui_story_5020_50200901_149_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5020_50200901_150_dialog_content = "...",
  ui_story_5020_50200901_151_dialog_content = "...",
  ui_story_5020_50200901_152_dialog_content = "Rinne, Anda telah membuat kesalahan besar.",
  ui_story_5020_50200901_153_dialog_content = "Kenapa?",
  ui_story_5020_50200901_154_dialog_content = "Karena ini salah.",
  ui_story_5020_50200901_155_dialog_content = "Benar dan salah yang Anda ajarkan kepada saya tampaknya sangat berbeda dari keyakinan Anda yang sebenarnya.",
  ui_story_5020_50200901_156_dialog_content = "Aku tak bisa mengajarkan segala hal yang kuketahui. Butuh waktu sampai kau bisa paham.",
  ui_story_5020_50200901_157_dialog_content = "Tak perlu. Akan kucari tahu sendiri.",
  ui_story_5020_50200901_158_dialog_content = "Semua pendeta sebelum saya, yang melakukan apa yang menurut Anda benar, di mana mereka sekarang?",
  ui_story_5020_50200901_159_dialog_content = "Mereka membangun Koufu-jou yang Anda lihat hari ini.",
  ui_story_5020_50200901_160_dialog_content = "Begitukah?",
  ui_story_5020_50200901_161_dialog_content = "Aku ingin melihat Koufu-jou yang berbeda.",
  ui_story_5020_50200901_162_dialog_content = "Dan ini adalah bagaimana Anda memilih untuk melakukannya?",
  ui_story_5020_50200901_163_dialog_content = "Saya telah melihat terlalu banyak pemberontakan dalam hidup saya. Mereka tidak pernah membawa perubahan—hanya kehancuran.",
  ui_story_5020_50200901_164_dialog_content = "Saya yakin ada hal-hal yang belum Anda lihat juga.",
  ui_story_5020_50200901_165_dialog_content = "Seperti pendeta wanita yang mengarahkan pisau ke arahmu.",
  ui_story_5020_50200901_166_dialog_content = "Aku tidak peduli kemana kau arahkan pedangmu.",
  ui_story_5020_50200901_167_dialog_content = "Aku hanya ingin kau memikirkannya.",
  ui_story_5020_50200901_168_dialog_content = "Saya selalu mengira hantu adalah satu-satunya musuh saya.",
  ui_story_5020_50200901_169_dialog_content = "Tapi, sekarang, aku justru menghadapimu.",
  ui_story_5020_50200901_170_dialog_content = "Dan untuk pertama kalinya saya merasakan kebencian yang kuat terhadap orang yang masih hidup.",
  ui_story_5020_50200901_171_dialog_content = "Kau harusnya takut pada kebencian itu.",
  ui_story_5020_50200901_172_dialog_content = "Heheh.",
  ui_story_5020_50200901_173_dialog_content = "Aku lebih senang daripada takut.",
  ui_story_5020_50200902_1_dialog_content = "Bunuh mereka!",
  ui_story_5020_50200902_2_dialog_content = "Dasar pemberontak nekat!",
  ui_story_5020_50200902_3_dialog_content = "Ahhh! Mereka membunuh orang!",
  ui_story_5020_50200902_4_dialog_content = "Jangan panik!",
  ui_story_5020_50200902_5_dialog_content = "Menyusun kembali! Kelilingi para pemberontak!",
  ui_story_5020_50200902_6_dialog_content = "Mengelilingi kami? Hmph!",
  ui_story_5020_50200902_7_dialog_content = "Samurai, saya tidak berpikir Anda memahami situasinya.",
  ui_story_5020_50200902_8_dialog_content = "Tanpa hantu untuk membantu Anda, Anda tidak dapat memimpin medan perang ini!",
  ui_story_5020_50200902_9_dialog_content = "Benar-benar lelucon.",
  ui_story_5020_50200902_10_dialog_content = "Kapan Anda Wisp pernah memenangkan pertarungan, baik melawan yang hidup atau yang mati?",
  ui_story_5020_50200902_11_dialog_content = "Kami akan kali ini.",
  ui_story_5020_50200902_12_dialog_content = "Haruskah kita lari? aku tidak ingin mati...",
  ui_story_5020_50200902_13_dialog_content = "Kemana? Jika kita pergi, kita mungkin akan bertemu hantu...",
  ui_story_5020_50200902_14_dialog_content = "Hantu pertama membunuh orang, sekarang orang membunuh orang juga...",
  ui_story_5020_50200902_15_dialog_content = "Berapa banyak nyawa yang akan terenggut hari ini?",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5020_50200902_17_dialog_content = "!!!",
  ui_story_5020_50200902_18_dialog_content = "!!!",
  ui_story_5020_50200902_19_dialog_content = "Tadi itu...",
  ui_story_5020_50200902_20_dialog_content = "Oh, tidak.",
  ui_story_5020_50200902_21_dialog_content = "Awan emas telah muncul, menyinari dunia. Semua hantu dan roh tunduk pada raja mereka.",
  ui_story_5020_50200902_22_dialog_content = "...",
  ui_story_5020_50200902_23_dialog_content = "Jenderal, tampaknya Anda akhirnya akan mengajari saya cara menggunakan Cloud Mirror.",
  ui_story_5020_50200902_24_dialog_content = "Yang saya inginkan hanyalah kedamaian.",
  ui_story_5020_50200902_25_dialog_content = "Anda mendapat manfaat dari kedamaian tetapi Anda tidak memahaminya.",
  ui_story_5020_50200902_26_dialog_content = "Aku tak punya waktu untuk mengajarimu apa-apa lagi.",
  ui_story_5020_50200902_27_dialog_content = "Hari ini, Koufu-jou akan mengenal kedamaian.",
  ui_story_5020_50200902_28_dialog_content = "Apakah Anda suka atau tidak.",
  ui_story_5020_50200902_29_dialog_content = "...",
  ui_story_5020_50200902_30_dialog_content = "...",
  ui_story_5020_50200902_31_dialog_content = "Hantu... Hantu datang!",
  ui_story_5020_50200902_32_dialog_content = "Berhenti berkelahi! Berurusan dengan hantu dulu!",
  ui_story_5020_50200902_33_dialog_content = "Berhenti? Hmph!",
  ui_story_5020_50200902_34_dialog_content = "Samurai akhirnya merasa ingin bertarung, karena bala bantuan mereka ada di sini.",
  ui_story_5020_50200902_35_dialog_content = "...",
  ui_story_5020_50200902_36_dialog_content = "Tentara!",
  ui_story_5020_50200902_37_dialog_content = "Blokir semua jalan.",
  ui_story_5020_50200902_38_dialog_content = "Tidak ada yang meninggalkan tempat ini kecuali sang jenderal memerintahkannya!",
  ui_story_5020_50200902_39_dialog_content = "Apa?",
  ui_story_5020_50200902_40_dialog_content = "Apa maksudmu tidak ada yang pergi? Para hantu datang!",
  ui_story_5020_50200902_41_dialog_content = "Apa kau...",
  ui_story_5020_50200902_42_dialog_content = "Teman-temanku! Wisp tidak menerima perintah dari sang jenderal!",
  ui_story_5020_50200902_43_dialog_content = "Buka jalan dan bawa warga ke tempat yang aman!",
  ui_story_5020_50200902_44_dialog_content = "Siap!",
  ui_story_5020_50200902_45_dialog_content = "Cepat! Ikuti Wisp!",
  ui_story_5020_50200902_46_dialog_content = "Itulah yang saya katakan, Anda selalu dapat mengandalkan penduduk asli Cloud Island!",
  ui_story_5020_50200902_47_dialog_content = "Jelas, jenderal itu berkolusi dengan para hantu!",
  ui_story_5020_50200902_48_dialog_content = "Hmph! Seekor serigala berbulu domba!",
  ui_story_5020_50200902_49_dialog_content = "Anda menyegel jalan? Bagaimana dengan warga sipil?",
  ui_story_5020_50200902_50_dialog_content = "Aku menjaga ketertiban demi mereka.",
  ui_story_5020_50200902_51_dialog_content = "Warga yang mematuhi tata tertib akan hidup damai. Dan warga yang mengusik ketertiban akan dihukum.",
  ui_story_5020_50200902_52_dialog_content = "Menjaga ketertiban dengan memanggil hantu-hantu itu?",
  ui_story_5020_50200902_53_dialog_content = "Anda telah kehilangan itu ...",
  ui_story_5020_50200902_54_dialog_content = "Hantu, manusia... Mereka tidak terlalu berbeda.",
  ui_story_5020_50200902_55_dialog_content = "Rinne, pikiranmu kini jadi dangkal.",
  ui_story_5020_50200902_56_dialog_content = "Apa-apaan kau ini...!",
  ui_story_5020_50200902_57_dialog_content = "Rinne, lupakan dia untuk saat ini.",
  ui_story_5020_50200902_58_dialog_content = "Wisp berusaha menerobos bersama warga, tapi...",
  ui_story_5020_50200902_59_dialog_content = "Mereka kalah jumlah, mereka mungkin tidak berhasil.",
  ui_story_5020_50200902_60_dialog_content = "... Apa kaupunya rencana?",
  ui_story_5020_50200902_61_dialog_content = "Ya.",
  ui_story_5020_50200902_62_dialog_content = "Kaubantu mereka.",
  ui_story_5020_50200902_63_dialog_content = "Aku? Lalu bagaimana dengan situasi di sini?",
  ui_story_5020_50200902_64_dialog_content = "Aku dan Vice akan menangani sang Jenderal.",
  ui_story_5020_50200902_65_dialog_content = "Hah? Kami akan?",
  ui_story_5020_50200902_66_dialog_content = "Ya. Aku tak yakin berapa lama kita bisa bertahan di sini. Kita tak boleh buang-buang waktu.",
  ui_story_5020_50200902_67_dialog_content = "Rinne, tidak ada yang bisa melawan hantu lebih baik darimu. Itu harus kamu.",
  ui_story_5020_50200902_68_dialog_content = "Aku hanya tidak yakin kamu akan bisa...",
  ui_story_5020_50200902_69_dialog_content = "Jangan khawatir! Kami bisa menanganinya!",
  ui_story_5020_50200902_70_dialog_content = "Waktu hampir habis, lanjutkan!",
  ui_story_5020_50200902_71_dialog_content = "... Baiklah.",
  ui_story_5020_50200902_72_dialog_content = "Berhati-hatilah, oke?",
  ui_story_5020_50200902_73_dialog_content = "... PlayerName, apakah Anda yakin ini ide yang bagus?",
  ui_story_5020_50200902_74_dialog_content = "Kita berdua melawan sang Jenderal?",
  ui_story_5020_50200902_75_dialog_content = "Kita tak mungkin bisa mengalahkannya.",
  ui_story_5020_50200902_76_dialog_content = "<size=45>Saya pikir Anda punya rencana!</size>",
  ui_story_5020_50200902_77_dialog_content = "Tenanglah. Ada yang bisa membantu kita.",
  ui_story_5020_50200902_78_dialog_content = "Mereka sedang dalam perjalanan.",
  ui_story_5020_50200902_79_dialog_content = "Ah! Jalan buntu lagi!",
  ui_story_5020_50200902_80_dialog_content = "Siapa yang mengira membangun rumah serumit ini adalah ide yang bagus?",
  ui_story_5020_50200902_81_dialog_content = "Saya mungkin harus menghabiskan malam di sini ...",
  ui_story_5020_50200902_82_dialog_content = "Tanpa makanan atau air...",
  ui_story_5020_50200902_83_dialog_content = "Dan di tengah panasnya uap...",
  ui_story_5020_50200902_84_dialog_content = "Hmm? Apa selama ini panas?",
  ui_story_5020_50200902_85_dialog_content = "Woah!",
  ui_story_5020_50200902_86_dialog_content = "F-Api! Apa ada orang di sini?",
  ui_story_5020_50200902_87_dialog_content = "Saya tidak bisa tinggal di sini lagi... Sekarang saya harus keluar!",
  ui_story_5020_50200902_88_dialog_content = "<color=#e8d9bb>Dug...</color>",
  ui_story_5020_50200902_89_dialog_content = "Ah! Bukan jalan buntu lagi!",
  ui_story_5020_50200902_90_dialog_content = "Apa yang harus saya lakukan? Bagaimana dengan jendela ini?",
  ui_story_5020_50200902_91_dialog_content = "Itu terlalu tinggi!",
  ui_story_5020_50200902_92_dialog_content = "Tidak mungkin... Jika aku melompat ke sini...",
  ui_story_5020_50200902_93_dialog_content = "Aaaahhhh!",
  ui_story_5020_50200902_94_dialog_content = "Saya kira itu tidak terlalu tinggi!",
  ui_story_5020_50200902_95_dialog_content = "Tidak apa-apa. Selama saya tidak mendarat di kepala saya, saya akan baik-baik saja!",
  ui_story_5020_50200902_96_dialog_content = "Siap...",
  ui_story_5020_50200902_97_dialog_content = "Satu, dua...",
  ui_story_5020_50200902_98_dialog_content = "Tiga!",
  ui_story_5020_50200902_99_dialog_content = "<anim type=Shake><size=45>Wahhhhhhhhhhhhhhhhh!</size></anim>",
  ui_story_5020_50200902_100_dialog_content = "<color=#e8d9bb>Brak...</color>",
  ui_story_5020_50200902_101_dialog_content = "Aduh! pantatku...",
  ui_story_5020_50200902_102_dialog_content = "Apakah itu... Yao?",
  ui_story_5020_50200902_103_dialog_content = "Yap!",
  ui_story_5020_50200902_104_dialog_content = "Wow! Vice! PlayerName!",
  ui_story_5020_50200902_105_dialog_content = "Sudah lama sekali!",
  ui_story_5020_50200902_106_dialog_content = "... Bisakah Anda membantu saya?",
  ui_story_5020_50200902_107_dialog_content = "... Kemarilah. Pegang erat-erat.",
  ui_story_5020_50200902_108_dialog_content = "PlayerName, apakah ini salah satu pembantu yang kamu bicarakan?",
  ui_story_5020_50200902_109_dialog_content = "Saya pikir dia bisa menggunakan bantuan sendiri.",
  ui_story_5020_50200902_110_dialog_content = "Anu... Dia salah satu dari orang-orang yang kumaksud itu.",
  ui_story_5020_50200902_111_dialog_content = "Minggir!",
  ui_story_5020_50200902_112_dialog_content = "Fujikumo, saatnya kamu membayar.",
  ui_story_5020_50200902_113_dialog_content = "Siapa kamu? Saya tidak ingat berutang apa pun kepada Anda.",
  ui_story_5020_50200902_114_dialog_content = "Kau berutang nyawamu pada Cloud Island.",
  ui_story_5020_50200902_115_dialog_content = "Amemori! Senang bisa melihatmu!",
  ui_story_5020_50200902_116_dialog_content = "Aku sudah menonton dari menara gerbang.",
  ui_story_5020_50200902_117_dialog_content = "Saya berencana untuk menikmati pertunjukan tetapi kalian tidak banyak bertengkar.",
  ui_story_5020_50200902_118_dialog_content = "Betapa lucunya.",
  ui_story_5020_50200902_119_dialog_content = "Apakah Anda benar-benar berpikir bahwa mengumpulkan beberapa tikus lagi akan cukup untuk menggulingkan saya?",
  ui_story_5020_50200902_120_dialog_content = "Hahahahahaha!",
  ui_story_5020_50200902_121_dialog_content = "Jangan memandang rendah tikus. Mereka punya gigi!",
  ui_story_5020_50200902_122_dialog_content = "Beri mereka satu dekade atau, bahkan lebih baik, satu abad...",
  ui_story_5020_50200902_123_dialog_content = "Dan mereka bahkan dapat meruntuhkan kastil tertinggi!",
  ui_story_5020_50200902_124_dialog_content = "Seluruh kota terbakar!",
  ui_story_5020_50200902_125_dialog_content = "Baiklah. Itu sebabnya saya melompat ...",
  ui_story_5020_50200902_126_dialog_content = "Fujikumo, apakah kamu pernah melihat menara gerbang yang lebih indah?",
  ui_story_5020_50200902_127_dialog_content = "Itu berdiri begitu tinggi, menutupi sudut langit yang cukup besar.",
  ui_story_5020_50200902_128_dialog_content = "Tapi ini pertama kalinya benar-benar terlihat cantik, diselimuti aroma anggur dan panasnya api.",
  ui_story_5020_50200902_129_dialog_content = "Saya percaya segala sesuatu di dunia ada untuk satu momen mulia itu.",
  ui_story_5020_50200902_130_dialog_content = "Dan ini adalah akhir terbaik yang pernah ada.",
  ui_story_5020_50200902_131_dialog_content = "Sword of the Underworld...",
  ui_story_5020_50200902_132_dialog_content = "Aku tahu kau tak akan kabur. Kebebasan tak akan bisa memuaskanmu.",
  ui_story_5020_50200902_133_dialog_content = "Kau masih pedang jahat yang pernah datang untukku dari neraka...",
  ui_story_5020_50200902_134_dialog_content = "Fujikumo, menurutmu kapan Tsuki terlihat paling cantik?",
  ui_story_5020_50200902_135_dialog_content = "... Anda tidak layak menyebut namanya!",
  ui_story_5020_50200902_136_dialog_content = "Ketika saya masih kecil, saya pikir dia sangat cantik ketika dia mengajari saya bernyanyi.",
  ui_story_5020_50200902_137_dialog_content = "Seiring bertambahnya usia, saya merasa dia semakin cantik ketika dia memberi tahu saya bahwa pendeta wanita dapat membawa kedamaian ke dunia ini.",
  ui_story_5020_50200902_138_dialog_content = "Tebak ketika saya berpikir dia adalah yang paling cantik sekarang.",
  ui_story_5020_50200902_139_dialog_content = "Cukup!",
  ui_story_5020_50200902_140_dialog_content = "Dia yang paling cantik ketika dia meninggal di pelukanku.",
  ui_story_5020_50200902_141_dialog_content = "...",
  ui_story_5020_50200902_142_dialog_content = "Dia sangat cantik sampai-sampai aku tak bisa menahan amarah dan kebencianku.",
  ui_story_5020_50200902_143_dialog_content = "Karena kaulah yang memiliki setiap keping kecantikannya.",
  ui_story_5020_50200902_144_dialog_content = "Sudah sepuluh tahun, penguasa Koufu-jou.",
  ui_story_5020_50200902_145_dialog_content = "Mari kita uji tekad.",
  ui_story_5020_50200902_146_dialog_content = "Apakah Anda lebih bertekad untuk menyingkirkan saya, atau apakah saya lebih bertekad untuk membunuh Anda?",
  ui_story_5020_50201001_1_dialog_content = "Berani-beraninya kau bicara seperti itu kepadaku!",
  ui_story_5020_50201001_2_dialog_content = "Berani-beraninya kausebut namanya!",
  ui_story_5020_50201001_3_dialog_content = "Ketidaktahuanmu menghancurkan dunia sempurna yang dia ciptakan.",
  ui_story_5020_50201001_4_dialog_content = "Mestinya kau meminta ampun kepadanya di neraka!",
  ui_story_5020_50201001_5_dialog_content = "!!!",
  ui_story_5020_50201001_6_dialog_content = "... Fujikumo, kamu benar-benar gila.",
  ui_story_5020_50201001_7_dialog_content = "Aku tak akan rugi apa-apa.",
  ui_story_5020_50201001_8_dialog_content = "...",
  ui_story_5020_50201001_9_dialog_content = "Hei, kalian berdua. Jangan hanya berdiri di sana dan menonton.",
  ui_story_5020_50201001_10_dialog_content = "Master! Aku siap membantumu!",
  ui_story_5020_50201001_11_dialog_content = "Aku tak minta dibantu.",
  ui_story_5020_50201001_12_dialog_content = "Aku ingin kau melarikan diri, secepat mungkin.",
  ui_story_5020_50201001_13_dialog_content = "Tapi... Guru...",
  ui_story_5020_50201001_14_dialog_content = "Lari, kataku!",
  ui_story_5020_50201001_15_dialog_content = "Aku tak punya waktu untuk ini!",
  ui_story_5020_50201001_16_dialog_content = "Jangan buat situasi jadi makin buruk untukku!",
  ui_story_5020_50201001_17_dialog_content = "Master...",
  ui_story_5020_50201001_18_dialog_content = "B-baiklah!",
  ui_story_5020_50201001_19_dialog_content = "Ayo pergi, Amemori. Guru punya ini!",
  ui_story_5020_50201001_20_dialog_content = "...",
  ui_story_5020_50201001_21_dialog_content = "Siap, Master.",
  ui_story_5020_50201001_22_dialog_content = "Itu benar, magang yang baik melakukan seperti yang dikatakan tuannya!",
  ui_story_5020_50201001_23_dialog_content = "Baiklah, Pedang Dunia Bawah, aku tidak pernah menyangka akan melihat pengorbanan diri di dalam dirimu.",
  ui_story_5020_50201001_24_dialog_content = "Hah. Aku hanya ingin melanjutkan legenda Sword of the Underworld.",
  ui_story_5020_50201001_25_dialog_content = "Sebagai master pedang yang dikenal suka berburu hantu, aku tidak bisa melewatkan kesempatan untuk melawan pria yang memilih untuk menjadi salah satunya...",
  ui_story_5020_50201001_26_dialog_content = "Dan mati di tangannya.",
  ui_story_5020_50201001_27_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5020_50201001_28_dialog_content = "Suaranya sangat menakutkan...",
  ui_story_5020_50201001_29_dialog_content = "Apakah ini benar-benar pertarungan dua orang?",
  ui_story_5020_50201001_30_dialog_content = "Melarikan diri jelas merupakan keputusan yang tepat... Bahkan kita semua bersama masih bukan tandingannya.",
  ui_story_5020_50201001_31_dialog_content = "Apa yang terjadi di kota?",
  ui_story_5020_50201001_32_dialog_content = "Dimana Rinne? Kenapa dia tidak bersamamu?",
  ui_story_5020_50201001_33_dialog_content = "Anu... Panjang ceritanya.",
  ui_story_5020_50201001_34_dialog_content = "Jenderal itu menyulap hantu untuk memulihkan ketertiban. Mereka bergabung dengan samurai, berusaha untuk tetap mengendalikan semua warga Koufu-jou.",
  ui_story_5020_50201001_35_dialog_content = "Untungnya, sebagian besar warga sipil telah berkumpul bersama. Wisp dan Rinne mengantar mereka ke tempat yang aman.",
  ui_story_5020_50201001_36_dialog_content = "Wiski?",
  ui_story_5020_50201001_37_dialog_content = "Wisp!",
  ui_story_5020_50201001_38_dialog_content = "Sebuah kekuatan yang terdiri dari penduduk lokal Cloud Island. Guru dan saya adalah bagian dari mereka.",
  ui_story_5020_50201001_39_dialog_content = "Benar!",
  ui_story_5020_50201001_40_dialog_content = "Dulu, kau juga anggota kami.",
  ui_story_5020_50201001_41_dialog_content = "Jadi, Wisp ini adalah pihak yang baik?",
  ui_story_5020_50201001_42_dialog_content = "... Begitulah.",
  ui_story_5020_50201001_43_dialog_content = "Tapi, kenapa si pendeta ikut bergabung dengan Wisp?",
  ui_story_5020_50201001_44_dialog_content = "Apakah mereka menculiknya?",
  ui_story_5020_50201001_45_dialog_content = "Penculik! Wisp itu jahat!",
  ui_story_5020_50201001_46_dialog_content = "Tidak, tidak... Sesuatu terjadi, dan Rinne bertarung berdampingan dengan Wisp.",
  ui_story_5020_50201001_47_dialog_content = "Untuk saat ini anggap saja mereka ada di pihak kita.",
  ui_story_5020_50201001_48_dialog_content = "Wisp dan si pendeta itu ada di pihak yang sama?",
  ui_story_5020_50201001_49_dialog_content = "Semua ini sangat sulit untuk dicerna...",
  ui_story_5020_50201001_50_dialog_content = "Err... Sebagai Rinne dikatakan sebelumnya, hantu adalah satu-satunya musuh pendeta.",
  ui_story_5020_50201001_51_dialog_content = "Jadi dia memenuhi tugasnya.",
  ui_story_5020_50201001_52_dialog_content = "... Baik, begitu.",
  ui_story_5020_50201001_53_dialog_content = "Dia akan menjaga keamanan warga sipil, setidaknya untuk sementara.",
  ui_story_5020_50201001_54_dialog_content = "Aku harus pergi mencari sesuatu.",
  ui_story_5020_50201001_55_dialog_content = "Benda apa?",
  ui_story_5020_50201001_56_dialog_content = "Pedang pembunuh hantu—<color=#FFB400>Sepotong Surga</color>.",
  ui_story_5020_50201001_57_dialog_content = "Menurut Guru... Itu mungkin bisa membalikkan keadaan.",
  ui_story_5020_50201001_58_dialog_content = "Saya pikir Wisp juga menyebutkannya! Itu senjata dongeng, kan?",
  ui_story_5020_50201001_59_dialog_content = "Tapi keberadaannya adalah misteri ...",
  ui_story_5020_50201001_60_dialog_content = "Itu dimakamkan dengan mantan pendeta wanita.",
  ui_story_5020_50201001_61_dialog_content = "Ah! itu bisa jadi petunjuk!",
  ui_story_5020_50201001_62_dialog_content = "Tapi kita akan membutuhkan lebih dari itu...",
  ui_story_5020_50201001_63_dialog_content = "Kita bisa menggali semua kuburan di dekat kota.",
  ui_story_5020_50201001_64_dialog_content = "Tunggu! Itu sedikit berlebihan!",
  ui_story_5020_50201001_65_dialog_content = "Lalu apa yang Anda sarankan? Hanya surga yang tahu kuburan mana yang menjadi milik mantan pendeta ...",
  ui_story_5020_50201001_66_dialog_content = "Anu...",
  ui_story_5020_50201001_67_dialog_content = "Bukankah Tsuki adalah pendeta wanita sebelumnya?",
  ui_story_5020_50201001_68_dialog_content = "Benar.",
  ui_story_5020_50201001_69_dialog_content = "Kau masih ingat dia?",
  ui_story_5020_50201001_70_dialog_content = "Ya, aku ingat.",
  ui_story_5020_50201001_71_dialog_content = "Aku... Aku ingat di mana dia dimakamkan.",
  ui_story_5020_50201001_72_dialog_content = "Apa!?",
  ui_story_5020_50201001_73_dialog_content = "Serius?",
  ui_story_5020_50201001_73X1_dialog_content = "Apa!?",
  ui_story_5020_50201001_73X2_dialog_content = "Yy-kamu... Jika kamu ingat itu... Apakah itu berarti...",
  ui_story_5020_50201001_73X3_dialog_content = "Ingatanmu sudah kembali?",
  ui_story_5020_50201001_73X4_dialog_content = "Iya. Aku sudah ingat semuanya.",
  ui_story_5020_50201001_73X5_dialog_content = "Luar biasa!",
  ui_story_5020_50201001_73X6_dialog_content = "Saya tidak berharap itu terjadi sekarang, tapi ...",
  ui_story_5020_50201001_73X7_dialog_content = "Akhirnya, tujuan kedatangan kita ke Cloud Island tercapai!",
  ui_story_5020_50201001_73X8_dialog_content = "Haha. Benar, akhirnya tercapai juga!",
  ui_story_5020_50201001_73X9_dialog_content = "Tapi... Rasanya aku tidak benar-benar bahagia...",
  ui_story_5020_50201001_73X10_dialog_content = "Ya, terutama dengan Koufu-jou di negara bagian itu...",
  ui_story_5020_50201001_73X11_dialog_content = "Bagaimana caranya ingatanmu bisa kembali?",
  ui_story_5020_50201001_73X12_dialog_content = "Saya menemukan sebuah lemari pakaian di Cloud Pavilion, tempat Guru dipenjarakan.",
  ui_story_5020_50201001_73X13_dialog_content = "Ingatan-ingatan itu tiba-tiba kembali. Di sanalah aku kehilangan ingatanku sepuluh tahun lalu.",
  ui_story_5020_50201001_73X14_dialog_content = "Saya bersembunyi di lemari, dan saya melihat Guru membunuh Tsuki.",
  ui_story_5020_50201001_73X15_dialog_content = "Saking ketakutan dan bingungnya, aku...",
  ui_story_5020_50201001_73X16_dialog_content = "Sepertinya ingatanku jadi hilang...",
  ui_story_5020_50201001_73X17_dialog_content = "Ya, itu bukan sesuatu yang bisa kusebut kenangan indah...",
  ui_story_5020_50201001_73X18_dialog_content = "Selama ini, aku mencari rasa sakit yang kucoba lupakan...",
  ui_story_5020_50201001_73X19_dialog_content = "Sekarang semuanya tampak... sia-sia.",
  ui_story_5020_50201001_73X20_dialog_content = "Cobalah memikirkannya dengan cara yang berbeda.",
  ui_story_5020_50201001_73X21_dialog_content = "Yang Anda lakukan hanyalah mempercayakan ingatan itu kepada versi diri Anda yang tumbuh dan lebih dewasa.",
  ui_story_5020_50201001_73X22_dialog_content = "Ingatan telah menunggumu untuk tumbuh dewasa, dan untuk kembali menghadapi takdir yang kau hindari sepuluh tahun yang lalu.",
  ui_story_5020_50201001_73X23_dialog_content = "Hah?",
  ui_story_5020_50201001_73X24_dialog_content = "Aku... tidak tahu kamu sangat pandai menghibur orang.",
  ui_story_5020_50201001_73X25_dialog_content = "...",
  ui_story_5020_50201001_73X26_dialog_content = "Apakah Anda mendengar mereka mengatakan di mana mereka menguburkan Tsuki?",
  ui_story_5020_50201001_74_dialog_content = "Hmm...",
  ui_story_5020_50201001_75_dialog_content = "Jenderal mengatakan dia akan mengubur Tsuki di <color=#FFB400>pegunungan di sebelah barat Koufu-jou.</color>",
  ui_story_5020_50201001_76_dialog_content = "Pegunungan di sebelah barat Koufu-jou...",
  ui_story_5020_50201001_77_dialog_content = "Oh, begitu.",
  ui_story_5020_50201001_78_dialog_content = "Ikuti aku, kita keluar dari kota.",
  ui_story_5020_50201001_79_dialog_content = "Keluar kota? Tidak akan mudah untuk keluar...",
  ui_story_5020_50201001_80_dialog_content = "Mereka menemukan kami.",
  ui_story_5020_50201001_81_dialog_content = "!!!",
  ui_story_5020_50201001_82_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5020_50201001_83_dialog_content = "<anim type=Shake>...</anim>",
  ui_story_5020_50201001_84_dialog_content = "<anim type=Shake>Tidak ada yang... pergi!</anim>",
  ui_story_5020_50201002_1_dialog_content = "Ayah...",
  ui_story_5020_50201002_2_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50201002_3_dialog_content = "*Hiks*",
  ui_story_5020_50201002_4_dialog_content = "Hah!",
  ui_story_5020_50201002_5_dialog_content = "Serang!",
  ui_story_5020_50201002_6_dialog_content = "Wow!",
  ui_story_5020_50201002_7_dialog_content = "Jangan lari-lari, Nak! Di luar sana berbahaya!",
  ui_story_5020_50201002_8_dialog_content = "Kembali ke yang lain!",
  ui_story_5020_50201002_9_dialog_content = "Baik!",
  ui_story_5020_50201002_10_dialog_content = "Bagaimana dengan kalian?",
  ui_story_5020_50201002_11_dialog_content = "Masih ada urusan yang harus kami tangani!",
  ui_story_5020_50201002_12_dialog_content = "Cukup sudah, Anzu. Cepat!",
  ui_story_5020_50201002_13_dialog_content = "<color=#e8d9bb>Kathunk... Kathunk...</color>",
  ui_story_5020_50201002_14_dialog_content = "Oh!",
  ui_story_5020_50201002_15_dialog_content = "Drum ini besar sekali!",
  ui_story_5020_50201002_16_dialog_content = "Keren, 'kan?",
  ui_story_5020_50201002_17_dialog_content = "Kenapa kau membawanya bersamamu?",
  ui_story_5020_50201002_18_dialog_content = "Karena itu milik kita!",
  ui_story_5020_50201002_19_dialog_content = "Tapi, bukankah di luar sana berbahaya?",
  ui_story_5020_50201002_20_dialog_content = "Ini sangat besar, sepertinya beban ...",
  ui_story_5020_50201002_21_dialog_content = "Sama sekali tidak! Itu baru saja menyelamatkan Wisp sebelumnya!",
  ui_story_5020_50201002_22_dialog_content = "Benar. Sebentar lagi, drum ini mungkin juga akan menyelamatkan lebih banyak nyawa!",
  ui_story_5020_50201002_23_dialog_content = "<color=#e8d9bb>Klik... Klik...</color>",
  ui_story_5020_50201002_24_dialog_content = "Chief, kurasa kita tak akan bisa menerobos keluar dari sini!",
  ui_story_5020_50201002_25_dialog_content = "Kami terlalu lelah untuk melawan mereka...",
  ui_story_5020_50201002_26_dialog_content = "Haruskah kita mencoba cara lain?",
  ui_story_5020_50201002_27_dialog_content = "Kita tak punya pilihan lain. Sebentar lagi, musuh pasti akan mengepung kita.",
  ui_story_5020_50201002_28_dialog_content = "Kita harus membuat celah, dan cepat.",
  ui_story_5020_50201002_29_dialog_content = "Tapi...",
  ui_story_5020_50201002_30_dialog_content = "Saya tahu bahwa kita semua kelelahan setelah berjuang sepanjang malam.",
  ui_story_5020_50201002_31_dialog_content = "Tapi pertempuran ini berbeda dengan yang pernah kita lakukan sebelumnya.",
  ui_story_5020_50201002_32_dialog_content = "Kami tidak hanya berjuang untuk hidup kami. Kami memiliki semua Cloud Island di belakang kami.",
  ui_story_5020_50201002_33_dialog_content = "Kita sama sekali tak boleh menyerah.",
  ui_story_5020_50201002_34_dialog_content = "Jika kita mati, kita akan bertarung sebagai hantu!",
  ui_story_5020_50201002_35_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5020_50201002_36_dialog_content = "Siapa yang memberimu izin untuk menjadi hantu?",
  ui_story_5020_50201002_37_dialog_content = "Saya punya cukup banyak hal untuk ditangani sebagaimana adanya.",
  ui_story_5020_50201002_38_dialog_content = "Pendeta?",
  ui_story_5020_50201002_39_dialog_content = "Sedang apa kau di sini?",
  ui_story_5020_50201002_40_dialog_content = "PlayerName berutang budi padamu...",
  ui_story_5020_50201002_41_dialog_content = "Aku kemari untuk membayarnya.",
  ui_story_5020_50201002_42_dialog_content = "...",
  ui_story_5020_50201002_43_dialog_content = "Baiklah.",
  ui_story_5020_50201002_44_dialog_content = "Kalau begitu, aku akan mempercayaimu untuk mengurus para hantu.",
  ui_story_5020_50201002_45_dialog_content = "Dan saya harap Anda sudah menguasai taktiknya.",
  ui_story_5020_50201002_46_dialog_content = "Anda akan mengetahui bahwa Wisp lebih dapat diandalkan daripada jenderal itu.",
  ui_story_5020_50201002_47_dialog_content = "Setiap orang! Bersiaplah untuk serangan habis-habisan! Ayo keluar dari pengepungan!",
  ui_story_5020_50201002_48_dialog_content = "Lindungi warga sipil! Kami menuju ke arah <color=#FFB400>pelabuhan</color>!",
  ui_story_5020_50201002_49_dialog_content = "<anim type=Shake>Batuk...</anim>",
  ui_story_5020_50201002_50_dialog_content = "Apakah Anda menyesal tinggal di belakang, Nagi?",
  ui_story_5020_50201002_51_dialog_content = "Menyesal? Itu istilah baru bagiku.",
  ui_story_5020_50201002_52_dialog_content = "Anda seorang pejuang. Pernahkah Anda membayangkan kematian Anda?",
  ui_story_5020_50201002_53_dialog_content = "Hanya sekali, sepuluh tahun yang lalu.",
  ui_story_5020_50201002_54_dialog_content = "Kupikir Tsuki dan aku akan mati bersama.",
  ui_story_5020_50201002_55_dialog_content = "Tapi, Tsuki ingin kau tetap hidup.",
  ui_story_5020_50201002_56_dialog_content = "Hutang Anda padanya lebih besar dari yang bisa Anda bayar.",
  ui_story_5020_50201002_57_dialog_content = "Saya hanya berdoa agar Anda tidak menjadi saudara perempuannya di kehidupan selanjutnya.",
  ui_story_5020_50201002_58_dialog_content = "Uhuk... Hahah...",
  ui_story_5020_50201002_59_dialog_content = "Kehidupan berikutnya... Kedengarannya sangat menyedihkan, datang darimu.",
  ui_story_5020_50201002_60_dialog_content = "Berapa lama lagi hatimu bertahan, Fujikumo?",
  ui_story_5020_50201002_61_dialog_content = "Siapa yang mungkin bisa membimbing jiwa busukmu menuju kelahiran kembali?",
  ui_story_5020_50201002_62_dialog_content = "...",
  ui_story_5020_50201002_63_dialog_content = "Saya tahu apa yang menanti saya dalam kematian.",
  ui_story_5020_50201002_64_dialog_content = "Tapi aku kehilangan hatiku sejak lama, ketika aku kehilangan dia.",
  ui_story_5020_50201002_65_dialog_content = "Jadi, mengapa saya takut menjadi hantu? Tidak ada apa pun di dunia fana ini yang enggan saya tinggalkan.",
  ui_story_5020_50201002_66_dialog_content = "Kedengarannya benar ...",
  ui_story_5020_50201002_67_dialog_content = "Meninggal karena usia tua di Paviliun Salju... bukan untukmu.",
  ui_story_5020_50201002_68_dialog_content = "Kau tak pantas mendapatkan akhir yang damai.",
  ui_story_5020_50201002_69_dialog_content = "Saya tidak melihat diri saya menyedihkan sama sekali.",
  ui_story_5020_50201002_70_dialog_content = "Saya seorang pejuang, dan saya baru saja mengalahkan saingan yang sangat kuat.",
  ui_story_5020_50201002_71_dialog_content = "Tapi, Fujikumo...",
  ui_story_5020_50201002_72_dialog_content = "Pertempuran kita berakhir sepuluh tahun yang lalu...",
  ui_story_5020_50201002_73_dialog_content = "Anda harus berterima kasih kepada Tsuki untuk sepuluh tahun ekstra kehidupan ini.",
  ui_story_5020_50201002_74_dialog_content = "Jangan lupa mengapa pertempuran ini terjadi lagi...",
  ui_story_5020_50201002_75_dialog_content = "...",
  ui_story_5020_50201002_76_dialog_content = "Itu karena petarung baru siap mengambil alih medan perang!",
  ui_story_5020_50201002_77_dialog_content = "<anim type=Shake>Hah... hah...</anim>",
  ui_story_5020_50201002_78_dialog_content = "<size=45><anim type=Shake>Hahahahah!</anim></size>",
  ui_story_5020_50201101_1_dialog_content = "<anim type=Shake>Argh…</anim>",
  ui_story_5020_50201101_2_dialog_content = "Fyuh...",
  ui_story_5020_50201101_3_dialog_content = "Begitu banyak hantu samurai...",
  ui_story_5020_50201101_4_dialog_content = "Kali ini, Fujikumo benar-benar berusaha habis-habisan.",
  ui_story_5020_50201101_5_dialog_content = "Siapa peduli! Kami akan mengurus semuanya, satu per satu!",
  ui_story_5020_50201101_6_dialog_content = "Hyaah! Stone Maul!",
  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>Graaagh!</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "I-Hantu-hantu ini tidak mungkin dibunuh!",
  ui_story_5020_50201101_10_dialog_content = "Hanya Rinne yang bisa mengatasi mereka.",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>Graaaaaah!</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "Hyaah!",
  ui_story_5020_50201101_13_dialog_content = "Kita mungkin tidak bisa menghancurkan mereka, tapi kita masih bisa mendorong mereka kembali!",
  ui_story_5020_50201101_14_dialog_content = "Divine Nature -- Bamboo Spikes!",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>Groar...</anim>",
  ui_story_5020_50201101_16_dialog_content = "Namun…",
  ui_story_5020_50201101_17_dialog_content = "PlayerName, lihat kastil ...",
  ui_story_5020_50201101_18_dialog_content = "!!!",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>Groar!</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "B-Bagaimana dia bisa...?!",
  ui_story_5020_50201101_21_dialog_content = "Samurai hantu semuanya melarikan diri dari api di kastil.",
  ui_story_5020_50201101_22_dialog_content = "Fujikumo memanggil begitu banyak dari mereka dalam satu hari...",
  ui_story_5020_50201101_23_dialog_content = "Dia benar-benar tidak menahan diri kali ini.",
  ui_story_5020_50201101_24_dialog_content = "Ninjutsu selamanya!",
  ui_story_5020_50201101_25_dialog_content = "Kita harus keluar dari Sakai sekarang dan singkirkan para pengejar jahat ini.",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>Di dekat area pemakaman di desa di luar Koufu-jou</color>",
  ui_story_5020_50201101_27_dialog_content = "Oh!",
  ui_story_5020_50201101_28_dialog_content = "PlayerName, sebagian ingatanku baru saja muncul kembali!",
  ui_story_5020_50201101_29_dialog_content = "Aku sudah pernah ke sini!",
  ui_story_5020_50201101_30_dialog_content = "Anda memang pernah ke sini sebelumnya ...",
  ui_story_5020_50201101_31_dialog_content = "Di sinilah kami bertemu Rinne Dan Amemori untuk pertama kalinya!",
  ui_story_5020_50201101_32_dialog_content = "Benar. Colossus kita mendarat darurat setelah kami tiba di Cloud Island...",
  ui_story_5020_50201101_32X_dialog_content = "Kita bertemu dengan Rinne di hutan bambu di depan sana, lalu...",
  ui_story_5020_50201101_33_dialog_content = "Amemori, yang harus melawan kita sebelum dia menjadi teman kita!",
  ui_story_5020_50201101_34_dialog_content = "...",
  ui_story_5020_50201101_35_dialog_content = "Hah! Pantas saja semuanya terasa sangat familier!",
  ui_story_5020_50201101_36_dialog_content = "... \"Ikuti sungai ini ke barat melalui Desa Sawah dan Anda akan mencapai kuburan di pegunungan.\"",
  ui_story_5020_50201101_37_dialog_content = "Menurut ingatanku, kita berada di jalur yang benar!",
  ui_story_5020_50201101_38_dialog_content = "Hei, Amemori. Nanti, jangan ganggu aku lagi, ya?",
  ui_story_5020_50201101_39_dialog_content = "Hah! Itu baris saya.",
  ui_story_5020_50201101_40_dialog_content = "Sepotong Surga—pedang pembunuh hantu adalah satu-satunya harapan kita melawan samurai hantu Fujikumo.",
  ui_story_5020_50201101_41_dialog_content = "Saya tidak mengharapkan Anda untuk membantu. Hanya saja, jangan menghalangi.",
  ui_story_5020_50201101_42_dialog_content = "Tunggu! Apa maksudmu?",
  ui_story_5020_50201101_43_dialog_content = "Apakah Anda mencoba mengambil Slice of Heaven untuk diri Anda sendiri?",
  ui_story_5020_50201101_44_dialog_content = "Benar.",
  ui_story_5020_50201101_45_dialog_content = "Tapi... Tapi itu bukan milikmu... Slice of Heaven adalah...",
  ui_story_5020_50201101_46_dialog_content = "Itu milik pendeta, yang meninggal!",
  ui_story_5020_50201101_47_dialog_content = "Saya tidak peduli tentang semua itu. Saya membutuhkannya untuk melindungi orang-orang Koufu-jou yang tidak bersalah.",
  ui_story_5020_50201101_48_dialog_content = "Wow! Kapan Anda menjadi tipe pidato muluk?",
  ui_story_5020_50201101_49_dialog_content = "Apakah Anda akan melakukan hal yang sama jika Tuan tidak membenci pendeta itu?",
  ui_story_5020_50201101_50_dialog_content = "(Saudari ini benar-benar berlawanan...)",
  ui_story_5020_50201101_51_dialog_content = "Kalian berdua... Tolong berhenti berdebat!",
  ui_story_5020_50201101_52_dialog_content = "...Hah?",
  ui_story_5020_50201101_53_dialog_content = "Hmm...?",
  ui_story_5020_50201101_54_dialog_content = "Wah... Salju turun?",
  ui_story_5020_50201101_55_dialog_content = "Tidak, bukan salju. Ini adalah...",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>Sakura putih</color>?",
  ui_story_5020_50201101_57_dialog_content = "Kelopak putih kecil ini berjatuhan dengan sangat lembut... Mereka terlihat seperti kepingan salju!",
  ui_story_5020_50201101_58_dialog_content = "\"Penduduk Cloud Island lebih menyukai bunga sakura yang montok dan berwarna cerah...\"",
  ui_story_5020_50201101_59_dialog_content = "Huh, ini benar-benar berbeda dari buku panduan!",
  ui_story_5020_50201101_60_dialog_content = "Bisa jadi, ini adalah satu-satunya tempat di Cloud Island yang ditumbuhi sakura seperti ini...",
  ui_story_5020_50201101_61_dialog_content = "Kami datang ke kuburan.",
  ui_story_5020_50201101_62_dialog_content = "Hmm... Pantas saja di sini sepi sekali...",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201101_64_dialog_content = "Err... Tidak mungkin...",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>Gaaah!!</anim>",
  ui_story_5020_50201101_66_dialog_content = "Apakah tidak ada tempat di mana hal-hal itu tidak akan pergi?!",
  ui_story_5020_50201101_67_dialog_content = "Yah, itu adalah kuburan, jadi kurasa itu tidak sepenuhnya tidak terduga...",
  ui_story_5020_50201101_68_dialog_content = "Cukup bicara. Sudah waktunya bagi saya untuk melemparkan beberapa pukulan!",
  ui_story_5020_50201201_1_dialog_content = "Rapid Torrent!",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>Argh…</anim>",
  ui_story_5020_50201201_3_dialog_content = "Fiuh... Hal-hal itu sangat mengganggu!",
  ui_story_5020_50201201_4_dialog_content = "Tapi Anda tahu apa yang mereka katakan, tidak bisa mengeluarkan wortel tanpa kotorannya juga!",
  ui_story_5020_50201201_5_dialog_content = "... Siapa yang mengatakan itu, tepatnya?",
  ui_story_5020_50201201_6_dialog_content = "Sumpah adikku! Dia memiliki pepatah untuk setiap kesempatan, dan dia memenangkan setiap argumen dalam keluarga Lin!",
  ui_story_5020_50201201_7_dialog_content = "Tentu saja, dia juga memenangkan setiap pertarungan!",
  ui_story_5020_50201201_8_dialog_content = "Dia terdengar seperti karakter yang cukup ...",
  ui_story_5020_50201201_9_dialog_content = "Oh, begitu. Pantas saja.",
  ui_story_5020_50201201_10_dialog_content = "Hm? Tidak heran apa? Tidak heran aku begitu hebat?",
  ui_story_5020_50201201_11_dialog_content = "Tidak heran Anda ternyata begitu kasar.",
  ui_story_5020_50201201_12_dialog_content = "Sayang sekali melihat pelatihan Guru sia-sia seperti ini.",
  ui_story_5020_50201201_13_dialog_content = "Apa itu tadi? Katakan itu lagi!",
  ui_story_5020_50201201_14_dialog_content = "PlayerName, apakah Anda mendengar bagaimana dia berbicara dengan juniornya?",
  ui_story_5020_50201201_15_dialog_content = "Baiklah, Yao. Sudah cukup.",
  ui_story_5020_50201201_16_dialog_content = "Kau juga, Amemori. Kau tak perlu mengolok-oloknya.",
  ui_story_5020_50201201_17_dialog_content = "Apa? Aku tidak menggoda!",
  ui_story_5020_50201201_18_dialog_content = "Jadi bagaimana jika Anda!?",
  ui_story_5020_50201201_19_dialog_content = "Apa kau bilang kau terlalu takut padaku untuk menggodaku?",
  ui_story_5020_50201201_20_dialog_content = "(Oh tidak, seharusnya aku tidak mengatakan apa-apa!)",
  ui_story_5020_50201201_21_dialog_content = "Izinkan saya menjelaskan satu hal.",
  ui_story_5020_50201201_22_dialog_content = "Saya tidak akan meninggalkan kuburan ini tanpa Sepotong Surga.",
  ui_story_5020_50201201_23_dialog_content = "Anda dapat membuat alasan sebanyak yang Anda inginkan ...",
  ui_story_5020_50201201_24_dialog_content = "Tetapi pada akhirnya, Anda bahkan hampir tidak dapat mengingat Guru. Yang Anda bicarakan hanyalah saudara perempuan Anda yang disumpah itu.",
  ui_story_5020_50201201_25_dialog_content = "Saya dibesarkan oleh Guru.",
  ui_story_5020_50201201_26_dialog_content = "Saya harus mendapatkan Slice of Heaven untuk membantu Guru mengalahkan Fujikumo.",
  ui_story_5020_50201201_27_dialog_content = "(Meskipun Guru tidak pernah meminta saya melakukan apapun untuknya...)",
  ui_story_5020_50201201_28_dialog_content = "Meskipun Tuan tidak memberitahumu rencananya untuk membakar seluruh kota?",
  ui_story_5020_50201201_29_dialog_content = "Ugh...",
  ui_story_5020_50201201_30_dialog_content = "Master pasti punya alasan tersendiri!",
  ui_story_5020_50201201_31_dialog_content = "Tentu saja dia tahu. Tapi berapa banyak yang Anda benar-benar tahu tentang dia?",
  ui_story_5020_50201201_32_dialog_content = "?!",
  ui_story_5020_50201201_33_dialog_content = "Kamu... Apakah kamu ingat sesuatu tentang dia yang tidak aku ketahui?",
  ui_story_5020_50201201_34_dialog_content = "... Saya telah membagikan semua yang saya tahu dengan Anda.",
  ui_story_5020_50201201_35_dialog_content = "Tapi orang yang memiliki Slice of Heaven tentu saja sangat berarti bagi Guru.",
  ui_story_5020_50201201_36_dialog_content = "...",
  ui_story_5020_50201201_37_dialog_content = "Yah... Aku tak paham.",
  ui_story_5020_50201201_37X_dialog_content = "Tuan sangat peduli dengan reputasinya... Mengapa tangannya kotor?",
  ui_story_5020_50201201_38_dialog_content = "Heh. Lebih-lebih lagi...",
  ui_story_5020_50201201_39_dialog_content = "Saya yakin pendeta wanita itu adalah orang yang sangat penting. Aku tahu dari ingatanku.",
  ui_story_5020_50201201_40_dialog_content = "Bagaimana kau bisa yakin?",
  ui_story_5020_50201201_41_dialog_content = "... Intuisi!",
  ui_story_5020_50201201_42_dialog_content = "...",
  ui_story_5020_50201201_43_dialog_content = "Ada apa dengan wajah? Intuisi saya tidak pernah salah!",
  ui_story_5020_50201201_44_dialog_content = "Aku bisa membuktikan bahwa itu memang benar.",
  ui_story_5020_50201201_45_dialog_content = "Suka atau tidak suka, saya mengambil Slice of Heaven.",
  ui_story_5020_50201201_46_dialog_content = "Saya yakin itu akan membantu saya mengingat lebih banyak hal.",
  ui_story_5020_50201201_47_dialog_content = "Hal-hal tentang Guru!",
  ui_story_5020_50201201_48_dialog_content = "Bagaimanapun, saya tidak mengharapkan bantuan dari Anda. Hanya saja, jangan menghalangi jalanku!",
  ui_story_5020_50201201_49_dialog_content = "...",
  ui_story_5020_50201201_50_dialog_content = "... Agh?",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>Wush...</color>",
  ui_story_5020_50201201_52_dialog_content = "Kunai!",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201201_54_dialog_content = "Yao, Anda akan membutuhkan sepuluh dari Anda untuk mengejutkan saya.",
  ui_story_5020_50201201_55_dialog_content = "Hehe! Benar!",
  ui_story_5020_50201201_55X_dialog_content = "Tunggu... Kedengarannya tidak bagus...",
  ui_story_5020_50201201_56_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201201_57_dialog_content = "<size=45><anim type=Shake>Gaaah!</anim></size>",
  ui_story_5020_50201201_58_dialog_content = "Anda mungkin tidak ingin membantu saya, tapi sekarang ...",
  ui_story_5020_50201201_59_dialog_content = "Hyaah!",
  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>Argh…</anim>",
  ui_story_5020_50201201_61_dialog_content = "Prioritas kita seharusnya menyingkirkan hantu-hantu ganas ini!",
  ui_story_5020_50201201_62_dialog_content = "Heh. Seolah-olah aku membutuhkanmu untuk memberitahuku itu.",
  ui_story_5020_50201202_1_dialog_content = "<anim type=Shake>Gaaa...</anim>",
  ui_story_5020_50201202_2_dialog_content = "Hmm! Gampang sekali!",
  ui_story_5020_50201202_3_dialog_content = "Tetap waspada semuanya. Akan ada lebih banyak hantu berkeliaran di dalam kuburan.",
  ui_story_5020_50201202_4_dialog_content = "Aku akan menyelinap masuk untuk memeriksa sekeliling.",
  ui_story_5020_50201202_5_dialog_content = "Terima kasih!",
  ui_story_5020_50201202_6_dialog_content = "Ninjutsu selamanya!",
  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>Desir... Desir...</color>",
  ui_story_5020_50201202_8_dialog_content = "Jantungku berdegup kencang... Kesunyian yang mematikan ini membuatku takut.",
  ui_story_5020_50201202_9_dialog_content = "Jangan takut. Tidak ada masalah yang tidak bisa diselesaikan dengan kepalan tangan!",
  ui_story_5020_50201202_10_dialog_content = "Hmm?",
  ui_story_5020_50201202_11_dialog_content = "... Amemori?",
  ui_story_5020_50201202_12_dialog_content = "Ada yang tidak beres...",
  ui_story_5020_50201202_13_dialog_content = "Apa maksudmu? Amemori... Kau baik-baik saja?",
  ui_story_5020_50201202_14_dialog_content = "... Silakan masuk, semuanya.",
  ui_story_5020_50201202_15_dialog_content = "Tak ada hantu sama sekali di dalam makam.",
  ui_story_5020_50201202_16_dialog_content = "Apa?",
  ui_story_5020_50201202_17_dialog_content = "Anda dapat menurunkan penjaga Anda. Tempat ini benar-benar aman.",
  ui_story_5020_50201202_18_dialog_content = "Semua aku bisa mendengar...",
  ui_story_5020_50201202_19_dialog_content = "Hanya suara bunga sakura yang jatuh.",
  ui_story_5020_50201202_20_dialog_content = "Hanya saja, mekarnya tak seperti bunga-bunga lain...",
  ui_story_5020_50201202_21_dialog_content = "Mereka menyebarkan kelopaknya perlahan, menahan campuran rasa sakit dan kegembiraan yang ditimbulkan oleh mekarnya.",
  ui_story_5020_50201202_22_dialog_content = "Dan ketika saatnya tiba, mereka diam-diam layu dalam diam.",
  ui_story_5020_50201202_23_dialog_content = "Bunga sakura menanggung segalanya dengan sabar. Sekarang saya mengerti mengapa Guru sangat mencintai mereka.",
  ui_story_5020_50201202_24_dialog_content = "Oh, wow... Buku panduan saya tidak menyebutkan semua ini!",
  ui_story_5020_50201202_25_dialog_content = "Aku tidak tahu kenapa, tapi aku sedih memikirkannya...",
  ui_story_5020_50201202_26_dialog_content = "Hah... Aneh sekali...",
  ui_story_5020_50201202_27_dialog_content = "Tempat ini tidak terlihat sepi sama sekali...",
  ui_story_5020_50201202_28_dialog_content = "Lihat, PlayerName!",
  ui_story_5020_50201202_29_dialog_content = "Ah...",
  ui_story_5020_50201202_30_dialog_content = "Ada orang yang sudah membersihkan kelopak sakura dari jalan.",
  ui_story_5020_50201202_31_dialog_content = "... Ada orang yang sudah kemari sebelum kita?",
  ui_story_5020_50201202_32_dialog_content = "Oh tidak! Sepotong Surga...",
  ui_story_5020_50201202_33_dialog_content = "Ah...",
  ui_story_5020_50201202_34_dialog_content = "Wow! Itu...",
  ui_story_5020_50201202_35_dialog_content = "Tidak heran itu disebut pedang pembunuh hantu legendaris ...",
  ui_story_5020_50201202_36_dialog_content = "Lekukannya mulus... Dan bilahnya benar-benar klasik...",
  ui_story_5020_50201202_37_dialog_content = "Bahkan setelah bertahun-tahun, itu masih dalam kondisi sempurna ...",
  ui_story_5020_50201202_38_dialog_content = "Tapi, siapa yang melakukan semua ini?",
  ui_story_5020_50201202_39_dialog_content = "Cara Slice of Heaven ditempatkan...",
  ui_story_5020_50201202_40_dialog_content = "Sepertinya semacam persembahan!",
  ui_story_5020_50201202_41_dialog_content = "Ah! PlayerName, lihat!",
  ui_story_5020_50201202_42_dialog_content = "Ada sesuatu di bawah Slice of Heaven...",
  ui_story_5020_50201202_43_dialog_content = "... Coba saya lihat dulu.",
  ui_story_5020_50201202_44_dialog_content = "Meskipun tidak mungkin seseorang memasang jebakan di sini, lebih baik aman daripada menyesal...",
  ui_story_5020_50201202_45_dialog_content = "Wow! Apa-apaan kau ini?",
  ui_story_5020_50201202_46_dialog_content = "...?",
  ui_story_5020_50201202_47_dialog_content = "Kamu pikir kamu ini siapa untuk memegang Slice of Heaven?",
  ui_story_5020_50201202_48_dialog_content = "... Silakan. Saya tidak punya waktu untuk ini sekarang.",
  ui_story_5020_50201202_49_dialog_content = "Hoi, PlayerName!",
  ui_story_5020_50201202_50_dialog_content = "Apa? Uh, tolong tinggalkan aku dari argumenmu...",
  ui_story_5020_50201202_51_dialog_content = "Anda pergi mengambilnya.",
  ui_story_5020_50201202_52_dialog_content = "A-aku?",
  ui_story_5020_50201202_53_dialog_content = "...",
  ui_story_5020_50201202_54_dialog_content = "Jika itu akan ditutup Yao up, aku baik-baik saja dengan itu.",
  ui_story_5020_50201202_55_dialog_content = "PlayerName, tolong jangan buang waktu saya.",
  ui_story_5020_50201202_56_dialog_content = "... Baiklah.",
  ui_story_5020_50201202_57_dialog_content = "Hmm?",
  ui_story_5020_50201202_58_dialog_content = "Ini...",
  ui_story_5020_50201202_59_dialog_content = "Benda di sebelah Sepotong Surga itu...",
  ui_story_5020_50201202_60_dialog_content = "A... <color=#FFB400>buku catatan</color>?",
  ui_story_5020_50201202_61_dialog_content = "Itu milik...",
  ui_story_5020_50201202_62_dialog_content = "... <color=#FFB400>Tsuki</color>?",
  ui_story_5020_50201202_63_dialog_content = "?!",
  ui_story_5020_50201202_64_dialog_content = "... Itu namanya.",
  ui_story_5020_50201202_65_dialog_content = "Itu buku catatan mantan pendeta.",
  ui_story_5020_50201202_66_dialog_content = "Kondisinya tampak masih sangat bagus. Kurasa buku ini belum lama berada di dalam makam ini.",
  ui_story_5020_50201202_67_dialog_content = "Pengunjung terakhir mungkin meninggalkannya di sini.",
  ui_story_5020_50201202_68_dialog_content = "Yang terakhir... Siapa sih yang datang ke sini sebelum kita?",
  ui_story_5020_50201202_69_dialog_content = "...",
  ui_story_5020_50201202_70_dialog_content = "saya tidak yakin...",
  ui_story_5020_50201202_71_dialog_content = "Tapi siapa pun orang itu, ada ikatan erat antara mereka dan mantan pendeta itu.",
  ui_story_5020_50201202_72_dialog_content = "Dan buku catatan ini...",
  ui_story_5020_50201202_73_dialog_content = "Kita harus membacanya!",
  ui_story_5020_50201202_74_dialog_content = "Saya yakin itu berisi informasi tentang masa lalu Guru.",
  ui_story_5020_50201202_75_dialog_content = "Dan hal-hal lain yang saya lupa!",
  ui_story_5020_50201202_76_dialog_content = "Coba buka pelan-pelan, PlayerName.",
  ui_story_5020_50201202_77_dialog_content = "Langsung buka halaman terakhirnya saja! Cepat!",
  ui_story_5020_50201202_78_dialog_content = "Baiklah, baiklah. Sini, mendekatlah...",
  ui_story_5020_50201301_1_dialog_content = "Lady Priestess, apakah Anda siap?",
  ui_story_5020_50201301_2_dialog_content = "Ya... Tapi, harap tunggu.",
  ui_story_5020_50201301_3_dialog_content = "Tolong bawa ini ke pendeta festival...",
  ui_story_5020_50201301_4_dialog_content = "Mari selamatkan perjalanan para pelayan, Tsuki.",
  ui_story_5020_50201301_5_dialog_content = "Aku akan mengurus ini.",
  ui_story_5020_50201301_6_dialog_content = "Ah... Jenderal Kubou, kukira kau sudah di Festival Kasuga.",
  ui_story_5020_50201301_7_dialog_content = "... Ada masalah kecil di festival.",
  ui_story_5020_50201301_8_dialog_content = "Aku kembali untuk mengambil Cloud Mirror.",
  ui_story_5020_50201301_9_dialog_content = "... Apa yang terjadi?",
  ui_story_5020_50201301_10_dialog_content = "Tak perlu dipikirkan. Fokus saja pada upacaramu.",
  ui_story_5020_50201301_11_dialog_content = "<color=#e8d9bb>Brak... Klang...</color>",
  ui_story_5020_50201301_12_dialog_content = "Ahh...",
  ui_story_5020_50201301_13_dialog_content = "Suara berisik di luar itu apa?",
  ui_story_5020_50201301_14_dialog_content = "Tsuki, jangan khawatir...",
  ui_story_5020_50201301_15_dialog_content = "Heh...",
  ui_story_5020_50201301_16_dialog_content = "...",
  ui_story_5020_50201301_17_dialog_content = "Nah, jika bukan Pendeta, pengkhianat Pulau Cloud.",
  ui_story_5020_50201301_18_dialog_content = "Lihatlah dirimu, semua berpakaian begitu indah. Ini akan menjadi tampilan yang mengerikan bagi saya jika saya menyentuh Anda.",
  ui_story_5020_50201301_19_dialog_content = "Hmm... Tapi saya khawatir saya akan menghentikan Festival Kasuga tahun ini.",
  ui_story_5020_50201301_20_dialog_content = "Apa tuntutan Anda?",
  ui_story_5020_50201301_21_dialog_content = "... Tsuki!",
  ui_story_5020_50201301_22_dialog_content = "Oh?",
  ui_story_5020_50201301_23_dialog_content = "Lugas sekali...",
  ui_story_5020_50201301_24_dialog_content = "Setidaknya kau lebih pintar dari Fujikumo.",
  ui_story_5020_50201301_25_dialog_content = "Aku ingin mengakhiri Festival Kasuga.",
  ui_story_5020_50201301_26_dialog_content = "Semua kejadian yang meningkatkan kekuatan pulau utama harus dihentikan!",
  ui_story_5020_50201301_27_dialog_content = "Dasar orang payah congkak. Tsuki, jangan buang waktumu untuk menanggapi mereka...",
  ui_story_5020_50201301_28_dialog_content = "Baik.",
  ui_story_5020_50201301_29_dialog_content = "Jadi, Anda tidak ingin budaya dan adat istiadat pulau utama tersebar di sini.",
  ui_story_5020_50201301_30_dialog_content = "Saya... Anda bisa mengatakannya seperti itu, ya!",
  ui_story_5020_50201301_31_dialog_content = "Namun pada hari Cloud Island membuka pelabuhannya ke pulau utama, kami memasuki era baru.",
  ui_story_5020_50201301_32_dialog_content = "Sangat normal jika sebagian dari kita dengan cepat beradaptasi dengan aturan baru sementara yang lain menolak untuk menerima status quo baru.",
  ui_story_5020_50201301_33_dialog_content = "Jika pulau itu bisa berbicara, saya yakin itu akan mengatakan bahwa banyak hal telah berubah dengan cepat...",
  ui_story_5020_50201301_34_dialog_content = "Tapi selama Koufu-jou masih berdiri, kamu dan aku berbagi tanah ini bersama.",
  ui_story_5020_50201301_35_dialog_content = "Anda dapat mencegah berlangsungnya Festival Kasuga. Anda bisa menyingkirkan seorang jenderal. Tapi semua itu tidak akan mengubah masa depan pulau itu.",
  ui_story_5020_50201301_36_dialog_content = "...",
  ui_story_5020_50201301_37_dialog_content = "Daripada mengakhiri festival ini, sebaiknya kaupikirkan saja cara...",
  ui_story_5020_50201301_38_dialog_content = "Untuk mengubah Festival Kasuga menjadi acara perayaanmu sendiri.",
  ui_story_5020_50201301_39_dialog_content = "...",
  ui_story_5020_50201301_40_dialog_content = "Lady Priestess, massa tidak menyebabkan gangguan lebih lanjut selama festival.",
  ui_story_5020_50201301_41_dialog_content = "Heheh... Dimana komandan mereka?",
  ui_story_5020_50201301_42_dialog_content = "Maksudmu wanita bernama Nagi?",
  ui_story_5020_50201301_43_dialog_content = "Keberadaannya tidak diketahui, tetapi saya dan anak buah saya sedang mencarinya.",
  ui_story_5020_50201301_43X_dialog_content = "Jika perlu, saya akan mengirim lebih banyak pasukan...",
  ui_story_5020_50201301_44_dialog_content = "Tak perlu.",
  ui_story_5020_50201301_45_dialog_content = "Jika mereka melakukan pemberontakan lagi, itu akan membuat pusing Kubou-sama.",
  ui_story_5020_50201301_46_dialog_content = "Biarkan Nagi menikmati bunga sakura di Festival Kasuga.",
  ui_story_5020_50201301_47_dialog_content = "Lady Priestess... Mohon maafkan saya jika ini di luar batas...",
  ui_story_5020_50201301_48_dialog_content = "Tapi apa yang kamu katakan sebelumnya sepertinya membuat Kubou-sama kesal.",
  ui_story_5020_50201301_49_dialog_content = "Ahh... Kau benar.",
  ui_story_5020_50201301_49X_dialog_content = "Jika aku pergi tanpa berkata apa-apa, Kubou-sama akan membunuh mereka semua.",
  ui_story_5020_50201301_50_dialog_content = "Saya kira pada hari kegembiraan dan perayaan ini, saya tidak ingin...",
  ui_story_5020_50201301_51_dialog_content = "Lihat Kubou-sama membantai semua orang itu.",
  ui_story_5020_50201301_52_dialog_content = "... Membantai mereka?",
  ui_story_5020_50201301_53_dialog_content = "Ya, cukup jelas bahwa ketika Kubou-sama kembali ke kastil untuk mengambil cermin awan...",
  ui_story_5020_50201301_54_dialog_content = "Dia bermaksud menggunakannya untuk melepaskan hantu pada para pemberontak.",
  ui_story_5020_50201301_55_dialog_content = "Tidak baik terlalu mengandalkan cermin...",
  ui_story_5020_50201301_56_dialog_content = "Mengapa itu menyusahkan Anda? Anda memiliki Sepotong Surga—pedang pembunuh hantu!",
  ui_story_5020_50201301_57_dialog_content = "Berarti, kau bisa membasmi mereka semua.",
  ui_story_5020_50201301_58_dialog_content = "...",
  ui_story_5020_50201301_59_dialog_content = "Sepotong Surga dan cermin awan keduanya dijiwai dengan kekuatan para dewa. Yang satu mengusir roh jahat dan yang lain memanggil mereka...",
  ui_story_5020_50201301_60_dialog_content = "Tidak apa-apa menggunakannya untuk upacara, tetapi mereka tidak pernah dimaksudkan untuk menjadi alat dominasi...",
  ui_story_5020_50201301_61_dialog_content = "Saya khawatir kekuatan lain akan dilepaskan... Kekuatan yang tidak bisa ditampung oleh manusia biasa.",
  ui_story_5020_50201301_62_dialog_content = "Tapi, bukankah itu tugasmu?",
  ui_story_5020_50201301_63_dialog_content = "Memegang Sepotong Surga melawan semua roh jahat telah menjadi tugas para pendeta wanita dari pulau utama selama beberapa generasi.",
  ui_story_5020_50201301_64_dialog_content = "Tidak, ini seperti menusuk perisaimu dengan tombakmu sendiri.",
  ui_story_5020_50201301_65_dialog_content = "Slice of Heaven membunuh mereka, dan Cloud Mirror menghidupkan mereka kembali...",
  ui_story_5020_50201301_66_dialog_content = "Ketika dua kekuatan kuat menyeimbangkan satu sama lain, kekuatan orang yang menggunakannya menjadi sangat penting.",
  ui_story_5020_50201301_67_dialog_content = "Tapi... aku tidak bisa mengubah pikiran Kubou-sama...",
  ui_story_5020_50201301_68_dialog_content = "Aku hanyalah alat untuk membantu Cloud Island agar bisa menikmati kedamaian dalam jangka panjang...",
  ui_story_5020_50201301_69_dialog_content = "Lady Priestess... Aku...",
  ui_story_5020_50201301_70_dialog_content = "Kurasa aku belum paham!",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding...</color>",
  ui_story_5020_50201301_72_dialog_content = "Heheh. Lihat! Tandu Kubou-sama dihiasi dengan begitu banyak lonceng!",
  ui_story_5020_50201301_73_dialog_content = "Ah... Jenderal Kubou!",
  ui_story_5020_50201301_74_dialog_content = "Lady Priestess, permisi... Saya harus memastikan keselamatan Kubou-sama!",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>Ding... Ding... Ding...</color>",
  ui_story_5020_50201301_76_dialog_content = "Jangan kejar aku! Jangan kejar aku!",
  ui_story_5020_50201301_77_dialog_content = "Cih... Dasar gadis nakal. Kembalikan Kagura Bell itu kepada Tsuki!",
  ui_story_5020_50201301_78_dialog_content = "Aku ingin kakakku mengejarku! Aku akan mengembalikannya jika dia bisa menangkapku!",
  ui_story_5020_50201301_79_dialog_content = "Kamu... Berapa kali aku harus memberitahumu? Dia Pendeta, bukan adikmu!",
  ui_story_5020_50201301_80_dialog_content = "Oke, baiklah!",
  ui_story_5020_50201301_81_dialog_content = "Tak usah diributkan, Nagi. Dia kan masih anak-anak.",
  ui_story_5020_50201301_82_dialog_content = "Yao hanya memanggilku kakaknya karena dia menyukaiku.",
  ui_story_5020_50201301_83_dialog_content = "... Tapi kamu seperti saudara perempuan bagiku. Yao adalah anak angkatmu.",
  ui_story_5020_50201301_84_dialog_content = "Jika dia juga memanggilmu kakak, apa artinya itu bagiku?",
  ui_story_5020_50201301_85_dialog_content = "Heheheh.",
  ui_story_5020_50201301_86_dialog_content = "Tidak lucu, tahu!",
  ui_story_5020_50201301_87_dialog_content = "Bagus. Aku tahu Yao nakal, tapi Amemori adalah gadis yang baik.",
  ui_story_5020_50201301_88_dialog_content = "Saya meminta Anda untuk membantu saya menjaga mereka berdua dan Anda berbalik Amemori menjadi versi miniatur Anda.",
  ui_story_5020_50201301_89_dialog_content = "Hmm... Dia belajar begitu cepat.",
  ui_story_5020_50201301_90_dialog_content = "Mau tak mau aku ingin mengajarinya hal-hal baru.",
  ui_story_5020_50201301_91_dialog_content = "... Nagi!",
  ui_story_5020_50201301_92_dialog_content = "Jangan khawatir. Saya tidak akan mengajari mereka keterampilan itu tanpa izin Anda.",
  ui_story_5020_50201301_93_dialog_content = "Selain itu, saya pikir Amemori sudah memikul banyak beban di pundak kecilnya...",
  ui_story_5020_50201301_94_dialog_content = "Dia masih sangat muda, namun dia sudah dengan sengaja bertindak tegas dan apatis...",
  ui_story_5020_50201301_95_dialog_content = "Tapi aku tahu pasti bahwa dia belum cukup umur untuk tahu bagaimana menekan perasaannya.",
  ui_story_5020_50201301_96_dialog_content = "Benar.",
  ui_story_5020_50201301_97_dialog_content = "Saya telah membesarkan mereka sebagai milik saya sejak saya mengambilnya.",
  ui_story_5020_50201301_98_dialog_content = "Tapi, tetap saja dia belum bisa dekat denganku, dan dia juga tak tertarik untuk bermain dengan Yao...",
  ui_story_5020_50201301_99_dialog_content = "Tapi entah kenapa dia sangat menyukaimu, Nagi.",
  ui_story_5020_50201301_100_dialog_content = "Dia menyukaiku?",
  ui_story_5020_50201301_101_dialog_content = "Ya. Dia memang tak banyak bicara, tapi dia suka menguntitmu ke mana-mana dan menirukan segala hal yang kaulakukan...",
  ui_story_5020_50201301_102_dialog_content = "Lihat! Bahkan bunga kesukaannya pun sama denganmu.",
  ui_story_5020_50201301_103_dialog_content = "Gadis kecil mana yang bisa memahami keindahan bunga sakura yang berguguran?",
  ui_story_5020_50201301_104_dialog_content = "Hah?",
  ui_story_5020_50201301_105_dialog_content = "Ah... Bunga sakura sudah berguguran.",
  ui_story_5020_50201301_106_dialog_content = "<size=33>... Waktu berlalu cepat. Segera saya akan berangkat ke pulau utama.</size>",
  ui_story_5020_50201301_107_dialog_content = "Apa katamu?",
  ui_story_5020_50201301_108_dialog_content = "Aku... Bukan apa-apa.",
  ui_story_5020_50201301_109_dialog_content = "Nagi, aku harus meninggalkan Cloud Island untuk sementara waktu.",
  ui_story_5020_50201301_110_dialog_content = "Ketika saya kembali, Anda akan menjadi komandan pasukan lokal.",
  ui_story_5020_50201301_111_dialog_content = "Kau mau ke mana? Dan untuk apa? Kenapa kau tak bilang apa-apa sebelumnya?",
  ui_story_5020_50201301_112_dialog_content = "... Apakah ini mengapa Anda mempercayakan Amemori Dan Yao ke dalam perawatan saya?",
  ui_story_5020_50201301_113_dialog_content = "Heheh... Segelintir bukan?",
  ui_story_5020_50201301_114_dialog_content = "Tapi kau tidak membenciku karena itu, kan?",
  ui_story_5020_50201301_115_dialog_content = "... Tentu saja tidak!",
  ui_story_5020_50201301_116_dialog_content = "Ini benar-benar indah...",
  ui_story_5020_50201301_117_dialog_content = "Saya harap Anda akan menjaga hal-hal seperti ini ...",
  ui_story_5020_50201301_118_dialog_content = "Tsuki, apa yang terjadi? Kenapa aku pernah...",
  ui_story_5020_50201301_119_dialog_content = "Hei, tidak apa-apa.",
  ui_story_5020_50201301_120_dialog_content = "Sekarang, tak banyak yang bisa kukatakan padamu. Tapi, percayalah padaku. Aku punya alasan tersendiri.",
  ui_story_5020_50201301_121_dialog_content = "Saat saya pergi, Anda bisa mengajari mereka lagu yang biasa kami nyanyikan.",
  ui_story_5020_50201301_122_dialog_content = "Ayo. Jangan bilang kau lupa kata-katanya!",
  ui_story_5020_50201301_123_dialog_content = "Sama sekali tidak!",
  ui_story_5020_50201301_124_dialog_content = "Lagu itu... Cocok untuk musim ini.",
  ui_story_5020_50201301_125_dialog_content = "Petik bunga merah untuk gadis muda itu...",
  ui_story_5020_50201301_126_dialog_content = "Kelopak berguguran seperti butiran salju di atas sebongkah giok...",
  ui_story_5020_50201301_127_dialog_content = "Nagi, memang ada kelopak ceri di alismu.",
  ui_story_5020_50201301_128_dialog_content = "Aw ... Bantu aku, maukah kamu ...",
  ui_story_5020_50201301_129_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201301_130_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201401_1_dialog_content = "...",
  ui_story_5020_50201401_2_dialog_content = "...",
  ui_story_5020_50201401_3_dialog_content = "Huh, siapa tahu Pendeta akan merekam cerita semacam ini.",
  ui_story_5020_50201401_4_dialog_content = "Sekarang saya mengerti mengapa saya merasa begitu dekat Rinne saat aku melihatnya...",
  ui_story_5020_50201401_5_dialog_content = "Semuanya terasa masuk akal sekarang.",
  ui_story_5020_50201401_6_dialog_content = "Bagaimana Anda sepertinya mengenali pendeta itu... Dan suara lonceng yang familiar...",
  ui_story_5020_50201401_7_dialog_content = "Ini ingatan Yao yang hilang!",
  ui_story_5020_50201401_8_dialog_content = "Tapi, aku…",
  ui_story_5020_50201401_9_dialog_content = "... Yao?",
  ui_story_5020_50201401_10_dialog_content = "Hatiku sakit...",
  ui_story_5020_50201401_11_dialog_content = "Bukankah menemukan ingatan yang hilang adalah hal yang membahagiakan?",
  ui_story_5020_50201401_12_dialog_content = "Saya masih tidak mengerti keputusan Guru.",
  ui_story_5020_50201401_13_dialog_content = "Tapi apa yang akan saya lakukan jika saya berada di posisinya?",
  ui_story_5020_50201401_14_dialog_content = "Ketika pendeta itu kembali dari pulau utama, dia dianggap sebagai pengkhianat yang tak termaafkan di Cloud Island...",
  ui_story_5020_50201401_15_dialog_content = "Ini seharusnya menjadi pilihan sederhana antara yang baik dan yang buruk, tapi...",
  ui_story_5020_50201401_16_dialog_content = "Mengapa saya merasa bahwa saya lebih sedih daripada Guru saat itu?",
  ui_story_5020_50201401_17_dialog_content = "... Banyak hal di dunia ini yang tidak hitam atau putih.",
  ui_story_5020_50201401_18_dialog_content = "Sama saja di mana saja, dari Astra hingga Timur Jauh...",
  ui_story_5020_50201401_19_dialog_content = "Orang menghadapi tantangan yang berbeda, dan posisi serta keyakinan mereka dibentuk oleh pengalaman pribadi mereka.",
  ui_story_5020_50201401_20_dialog_content = "... Begitukah?",
  ui_story_5020_50201401_21_dialog_content = "Hm, mari kita lihat apakah kita dapat menemukan entri terakhir...",
  ui_story_5020_50201401_22_dialog_content = "Coba saya lihat... Seharusnya ada di sekitar sini...",
  ui_story_5020_50201401_22X_dialog_content = "Hah?",
  ui_story_5020_50201401_23_dialog_content = "Ada sepucuk <color=#FFB400>surat</color> terselip di halamannya!",
  ui_story_5020_50201401_24_dialog_content = "Ah. Suratnya masih bersegel.",
  ui_story_5020_50201401_25_dialog_content = "Tertulis, \"Untuk pendeta selanjutnya\"...",
  ui_story_5020_50201401_26_dialog_content = "Wow! Pendeta pergi Rinne sebuah surat!",
  ui_story_5020_50201401_27_dialog_content = "PlayerName, kita berikan saja surat ini kepada Rinne.",
  ui_story_5020_50201401_28_dialog_content = "Hmm... Soalnya, bagian yang saya cari ada di sini, di awal entri!",
  ui_story_5020_50201401_29_dialog_content = "Apa yang dimaksud pendeta wanita dengan apa yang dia katakan kepada Guru sebelum kepergiannya?",
  ui_story_5020_50201401_30_dialog_content = "Apa dia sudah tahu bahwa dia akan menjadi pendeta?",
  ui_story_5020_50201401_31_dialog_content = "Apakah dia sudah meramalkan masa depan yang penuh dengan kebencian dari Guru dan semua penduduk Cloud Island?",
  ui_story_5020_50201401_32_dialog_content = "Tapi... Itu kan pilihannya sendiri.",
  ui_story_5020_50201401_33_dialog_content = "Benarkah itu pilihannya sendiri?",
  ui_story_5020_50201401_34_dialog_content = "Omong-omong... Hmm...",
  ui_story_5020_50201401_35_dialog_content = "Amemori! Aku tahu pendeta itu bukan orang jahat!",
  ui_story_5020_50201401_36_dialog_content = "Dia adalah seorang pendekar yang sepenuh hati peduli dengan kedamaian dan keselamatan Cloud Island!",
  ui_story_5020_50201401_37_dialog_content = "... Amemori?",
  ui_story_5020_50201401_38_dialog_content = "Amemori, kau menangis, ya?",
  ui_story_5020_50201401_39_dialog_content = "Tidak.",
  ui_story_5020_50201401_40_dialog_content = "(Kenapa dia harus mengeksposnya seperti itu!)",
  ui_story_5020_50201401_41_dialog_content = "Saya belum pernah melihat Guru dari sudut ini sebelumnya...",
  ui_story_5020_50201401_42_dialog_content = "Aku tidak pernah mendengar dia berbicara tentang aku kepada orang lain.",
  ui_story_5020_50201401_43_dialog_content = "Aku dulu berpikir aku sama seperti dia.",
  ui_story_5020_50201401_44_dialog_content = "Bahkan Wisp mengatakan itu tentangku.",
  ui_story_5020_50201401_45_dialog_content = "Tapi hanya Guru yang tahu apakah itu benar.",
  ui_story_5020_50201401_46_dialog_content = "Setelah bertahun-tahun berlatih, Guru telah membuat tubuh dan pikirannya menjadi lebih tangguh daripada Fujikumo...",
  ui_story_5020_50201401_47_dialog_content = "Dia sangat tangguh sehingga tidak ada kekerasan yang bisa menyakitinya, termasuk pukulan berat Fujikumo...",
  ui_story_5020_50201401_48_dialog_content = "Dia menerjang pukulan, kekaguman, gosip ...",
  ui_story_5020_50201401_49_dialog_content = "Tapi dorongan lembut dari Tsuki yang sekarat itulah yang mengirimnya ke tanah yang tersegel.",
  ui_story_5020_50201401_50_dialog_content = "Mungkin apa yang dia katakan kepadaku ketika dia melihatku untuk pertama kalinya dalam satu dekade...",
  ui_story_5020_50201401_51_dialog_content = "Kadang kau tampak kejam... Tapi, kau juga menunjukkan kasih dan kelemahanmu lebih sering daripada yang semestinya.",
  ui_story_5020_50201401_52_dialog_content = "Untuk hidup di dunia seperti ini, yang terbaik adalah meninggalkan emosi Anda sepenuhnya.",
  ui_story_5020_50201401_53_dialog_content = "Saya pikir kata-kata itu untuk dirinya sendiri juga.",
  ui_story_5020_50201401_54_dialog_content = "... Apa yang kamu coba katakan? Tentu saja Anda tidak sama dengan Guru.",
  ui_story_5020_50201401_55_dialog_content = "Saya tahu banyak ketika saya melihat Guru untuk pertama kalinya.",
  ui_story_5020_50201401_56_dialog_content = "Apa?",
  ui_story_5020_50201401_57_dialog_content = "Saya akan menjelaskan apa yang saya maksud. Batuk...",
  ui_story_5020_50201401_58_dialog_content = "Guru memiliki gagasan yang sangat jelas tentang apa yang dia inginkan.",
  ui_story_5020_50201401_59_dialog_content = "Bukan hanya Guru. Pendeta itu sama ...",
  ui_story_5020_50201401_60_dialog_content = "Mereka berdua tahu apa yang ingin mereka lakukan pada saat tertentu.",
  ui_story_5020_50201401_61_dialog_content = "Jadi, Amemori... Jika Anda mengesampingkan pengaruh Guru dan semua tekanan yang Anda berikan pada diri Anda sendiri ...",
  ui_story_5020_50201401_62_dialog_content = "Apa yang akan <color=#FFB400>pilihanmu</color> menjadi?",
  ui_story_5020_50201401_63_dialog_content = "...?!",
  ui_story_5020_50201401_64_dialog_content = "Mengesampingkan semua itu, aku...",
  ui_story_5020_50201401_65_dialog_content = "Entahwah...",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>Bum...</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>Bum... Bum!</color>",
  ui_story_5020_50201401_68_dialog_content = "Wah! Suara apa itu?",
  ui_story_5020_50201401_69_dialog_content = "Itu <color=#FFB400>taiko</color>... Itu taiko Momo dan Anzu!",
  ui_story_5020_50201401_70_dialog_content = "Tapi kenapa? Koufu-jou telah jatuh ke dalam kekacauan...",
  ui_story_5020_50201401_71_dialog_content = "Itu tanda. Rinne dalam bahaya!",
  ui_story_5020_50201401_72_dialog_content = "Rinne!",
  ui_story_5020_50201401_73_dialog_content = "Di mana dia?",
  ui_story_5020_50201401_74_dialog_content = "... Saya akan mengirim Wisp untuk membantu!",
  ui_story_5020_50201401_75_dialog_content = "Kurasa kita tak akan butuh ini lagi!",
  ui_story_5020_50201401_75X_dialog_content = "Rinne telah bersama Wisp sejak itu Rinne meninggalkan kami.",
  ui_story_5020_50201401_76_dialog_content = "Saya kira mereka berjuang pertempuran baru bersama-sama.",
  ui_story_5020_50201401_77_dialog_content = "Bersama? Kok bisa begitu?",
  ui_story_5020_50201401_78_dialog_content = "Amemori... Terkadang, satu-satunya pilihan Anda masih berupa pilihan.",
  ui_story_5020_50201401_79_dialog_content = "Pada saat genting ini, Anda harus tahu apa yang benar-benar ingin Anda lakukan!",
  ui_story_5020_50201401_80_dialog_content = "...",
  ui_story_5020_50201401_81_dialog_content = "Suara itu berasal dari pelabuhan.",
  ui_story_5020_50201401_82_dialog_content = "Yao, ulurkan tanganmu.",
  ui_story_5020_50201401_83_dialog_content = "Karena ini berisi ingatan kita dari sepuluh tahun yang lalu, mari kita gunakan untuk mengakhiri cerita yang dimulai saat itu.",
  ui_story_5020_50201401_84_dialog_content = "Hmm! Sesama orang hebat memang punya pemikiran yang sama!",
  ui_story_5020_50201401_85_dialog_content = "Ayo ikuti taiko. Ke <color=#FFB400>pelabuhan</color>!",
  ui_story_5020_50201401_86_dialog_content = "<color=#e8d9bb>Di sebuah jalan di kota kastel Koufu-jou</color>",
  ui_story_5020_50201401_87_dialog_content = "Cepat! Bergegaslah!",
  ui_story_5020_50201401_88_dialog_content = "Kita bisa mengikuti sungai ini ke pelabuhan.",
  ui_story_5020_50201401_89_dialog_content = "Ayo cepat! Mundur, cepat!",
  ui_story_5020_50201401_90_dialog_content = "Orang-orang di pelabuhan akan membawa Anda ke tempat yang aman.",
  ui_story_5020_50201401_91_dialog_content = "Lari dari kastil Koufu-jou, semakin jauh semakin baik!",
  ui_story_5020_50201401_92_dialog_content = "Ini gila...",
  ui_story_5020_50201401_93_dialog_content = "Pasukan sang mantan komandan bekerja sama dengan pendeta sang Jenderal...",
  ui_story_5020_50201401_93X_dialog_content = "... Hah?!",
  ui_story_5020_50201401_94_dialog_content = "Pantatku!",
  ui_story_5020_50201401_95_dialog_content = "Jaga mulutmu! Atau itu tidak akan menjadi gagangnya lain kali!",
  ui_story_5020_50201401_96_dialog_content = "Ayah... Mari kita pergi dengan pendeta! Semua orang menatap kita...",
  ui_story_5020_50201401_97_dialog_content = "Kebakarannya masih besar... Aku tak mau mati...",
  ui_story_5020_50201401_98_dialog_content = "Kenapa kita harus mengikutinya?",
  ui_story_5020_50201401_99_dialog_content = "Dia pengkhianat. Dia akan menjual kita ke pulau utama!",
  ui_story_5020_50201401_100_dialog_content = "Seratus Fujikumo akan menunggu kita di sana!",
  ui_story_5020_50201401_100X_dialog_content = "... Tidaaak!!",
  ui_story_5020_50201401_101_dialog_content = "Aduh... Ahhh! Bahu saya...",
  ui_story_5020_50201401_102_dialog_content = "Ayah!",
  ui_story_5020_50201401_103_dialog_content = "Hei, antek! Apakah Anda mengevakuasi kami atau mencoba membunuh...?",
  ui_story_5020_50201401_104_dialog_content = "Hah?",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>Gaa... Gaaaahh!!</anim>",
  ui_story_5020_50201401_106_dialog_content = "Hantu... Ada hantu di Sakai...",
  ui_story_5020_50201401_107_dialog_content = "Tetap bersama rombongan. Jangan panik!",
  ui_story_5020_50201401_108_dialog_content = "Pendeta, tunjukkan jalannya. Aku akan jaga bagian belakang!",
  ui_story_5020_50201401_109_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201401_110_dialog_content = "<size=45><anim type=Shake>Gaaah!</anim></size>",
  ui_story_5020_50201401_111_dialog_content = "<size=50><anim type=Shake>Gaaah!</anim></size>",
  ui_story_5020_50201401_112_dialog_content = "Teman-teman, hunus senjata kalian!",
  ui_story_5020_50201401_113_dialog_content = "Cacah saja roh-roh jahat itu!",
  ui_story_5020_50201401_114_dialog_content = "Hyaah!",
  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>Di dekat pelabuhan Koufu-jou</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>Bum... Bum!</color>",
  ui_story_5020_50201501_3_dialog_content = "Banyak sekali orang... Di mana gerangan Rinne?",
  ui_story_5020_50201501_4_dialog_content = "Sial!",
  ui_story_5020_50201501_5_dialog_content = "Rinne!",
  ui_story_5020_50201501_6_dialog_content = "Rinne! Apa kau bisa mendengarku?",
  ui_story_5020_50201501_7_dialog_content = "... Yao?",
  ui_story_5020_50201501_8_dialog_content = "Yao!",
  ui_story_5020_50201501_9_dialog_content = "Ah! Dan Amemori, Vice, Dan PlayerName!",
  ui_story_5020_50201501_10_dialog_content = "Ternyata kalian dengar suara taiko itu!",
  ui_story_5020_50201501_11_dialog_content = "PlayerName memiliki telinga yang tajam! Kami datang secepat mungkin.",
  ui_story_5020_50201501_12_dialog_content = "Bagaimana keadaanmu? Apa kau terluka?",
  ui_story_5020_50201501_13_dialog_content = "Saya baik-baik saja. Sebagian besar penduduk Koufu-jou telah dievakuasi.",
  ui_story_5020_50201501_14_dialog_content = "Wisp telah membawa beberapa warga sipil ke tempat aman dengan perahu...",
  ui_story_5020_50201501_15_dialog_content = "Bagaimana denganmu? Apa tadi mereka merepotkanmu?",
  ui_story_5020_50201501_16_dialog_content = "Heheh. Senang mendengar bahwa Anda peduli dengan saya, Yao.",
  ui_story_5020_50201501_17_dialog_content = "Jangan khawatir. Aku baik-baik saja. Bagaimana keadaan kalian semua?",
  ui_story_5020_50201501_18_dialog_content = "Kami saling mendukung, jadi kami semua baik-baik saja! PlayerName, dengan cepat. Tunjukkan padanya <color=#FFB400>benda</color> kami menemukan!",
  ui_story_5020_50201501_19_dialog_content = "Hmm?",
  ui_story_5020_50201501_20_dialog_content = "Hal? Oh, benar!",
  ui_story_5020_50201501_21_dialog_content = "Rinne, ini untukmu.",
  ui_story_5020_50201501_22_dialog_content = "Oh! Ini... Surat di buku catatan?",
  ui_story_5020_50201501_23_dialog_content = "Ini untukku? Tapi, sepertinya aku tak punya kenalan bernama seperti ini...",
  ui_story_5020_50201501_24_dialog_content = "Tsuki adalah mantan pendeta Koufu-jou.",
  ui_story_5020_50201501_25_dialog_content = "... Baiklah.",
  ui_story_5020_50201501_26_dialog_content = "Untuk pendeta berikutnya...",
  ui_story_5020_50201501_27_dialog_content = "Saya memutuskan untuk menuliskan beberapa pemikiran sementara saya menunggunya.",
  ui_story_5020_50201501_28_dialog_content = "Saya merasa tidak nyaman tentang masa depan yang saya tidak akan hidup untuk melihat ...",
  ui_story_5020_50201501_29_dialog_content = "Semakin aku memikirkannya, semakin aku mengkhawatirkanmu, penggantiku.",
  ui_story_5020_50201501_30_dialog_content = "Tidak adil jika Anda harus mengambil posisi ini tanpa mentor.",
  ui_story_5020_50201501_31_dialog_content = "Sudah banyak hal yang tidak adil dan tidak adil yang datang dengan status pendeta.",
  ui_story_5020_50201501_32_dialog_content = "Saya tidak tahu musim apa di Cloud Island saat Anda membuka surat ini...",
  ui_story_5020_50201501_33_dialog_content = "Cloud Island terkenal dengan bunga sakura yang bermekaran seperti awan kemerahan...",
  ui_story_5020_50201501_33X_dialog_content = "Dan jatuh seperti salju.",
  ui_story_5020_50201501_34_dialog_content = "Bagi sebagian besar warga Cloud Island, para pendeta seperti kami ini tak ubahnya seperti bunga sakura, cantik tapi fana.",
  ui_story_5020_50201501_35_dialog_content = "Tapi bagiku, pendeta Cloud Island seperti matahari, sendirian tapi sangat cantik, menjaga tanah ini...",
  ui_story_5020_50201501_36_dialog_content = "Kami berjuang melawan malam yang gelap, tapi kami tidak bisa membiarkan awan dari pulau utama menghalangi sinar kami.",
  ui_story_5020_50201501_37_dialog_content = "Namun, jika Anda telah mempelajari bagian sejarah ini, saya mungkin harus memberi tahu Anda beberapa hal, dari satu pendeta ke pendeta lainnya.",
  ui_story_5020_50201501_38_dialog_content = "Kubou-sama bukan salah satu dari awan gelap itu, setidaknya tidak menurutku.",
  ui_story_5020_50201501_39_dialog_content = "Dia lebih dekat, lebih seperti payung yang melayang di atas kepala kami.",
  ui_story_5020_50201501_40_dialog_content = "Dia bukan orang baik, dan dia belum melakukan banyak hal baik. Nyatanya, dia telah membawa banyak penderitaan dan kesialan ke kota ini...",
  ui_story_5020_50201501_41_dialog_content = "Tapi ini sudah menjadi masa depan terbaik yang bisa dimiliki Koufu-jou, dan dia berjuang keras untuk itu.",
  ui_story_5020_50201501_42_dialog_content = "Maafkan saya karena menulis kepada Anda sebagai orang asing.",
  ui_story_5020_50201501_43_dialog_content = "Saya ragu-ragu untuk beberapa waktu tentang siapa yang harus diletakkan sebagai penerima ...",
  ui_story_5020_50201501_44_dialog_content = "Lagi pula, aku tahu ini akan menjadi perpisahan yang berat dan penuh duka.",
  ui_story_5020_50201501_45_dialog_content = "Jadi, saya memutuskan untuk menyegelnya agar dapat dibuka suatu hari nanti.",
  ui_story_5020_50201501_46_dialog_content = "Tolong bersinar seperti matahari. Semoga sukses.",
  ui_story_5020_50201501_47_dialog_content = "Pendahulumu.",
  ui_story_5020_50201501_48_dialog_content = "...",
  ui_story_5020_50201501_49_dialog_content = "Ini aneh...",
  ui_story_5020_50201501_50_dialog_content = "Pendeta Koufu-jou ditakdirkan untuk hidup dalam kesepian.",
  ui_story_5020_50201501_51_dialog_content = "Tapi aku merasa pendahuluku baru saja meminjamkanku kekuatannya...",
  ui_story_5020_50201501_52_dialog_content = "Semua pendeta Koufu-jou selalu sendirian.",
  ui_story_5020_50201501_53_dialog_content = "Tetapi Rinne, Anda telah mengubahnya. Apakah kamu tidak melihat?",
  ui_story_5020_50201501_54_dialog_content = "Aku?",
  ui_story_5020_50201501_55_dialog_content = "Lady Priestess... Mohon terima ini sebelum kami naik ke kapal...",
  ui_story_5020_50201501_56_dialog_content = "Seluruh tas ini, semuanya untukmu!",
  ui_story_5020_50201501_57_dialog_content = "Dia... <color=#FFB400>Fukumame</color>, untuk mengusir setan dan membawa keberuntungan?",
  ui_story_5020_50201501_58_dialog_content = "Hanya itu yang kita miliki. Semua keberuntungan kami dikemas dalam tas ini!",
  ui_story_5020_50201501_59_dialog_content = "Tolong ambil kacang ini dan gunakan untuk mengalahkan orang jahat!",
  ui_story_5020_50201501_60_dialog_content = "Semoga rejeki kita bisa menjagamu...",
  ui_story_5020_50201501_61_dialog_content = "Lady Priestess, simpan kacang ini dan tetap aman dalam pertempuran.",
  ui_story_5020_50201501_62_dialog_content = "Aku…",
  ui_story_5020_50201501_63_dialog_content = "Anda bisa menyerahkannya kepada saya!",
  ui_story_5020_50201501_64_dialog_content = "Lady Priestess, kapal lain sudah siap. Kita harus bisa memuat warga sipil yang tersisa.",
  ui_story_5020_50201501_65_dialog_content = "Terima kasih. Tolong bawa mereka ke tempat yang aman.",
  ui_story_5020_50201501_66_dialog_content = "Amemori, dari tadi kau diam saja.",
  ui_story_5020_50201501_67_dialog_content = "Jika Anda tidak mengatakan apa-apa, Wisp akan mengambil komandan baru.",
  ui_story_5020_50201501_68_dialog_content = "... Saya tidak punya banyak hal untuk dikatakan Rinne.",
  ui_story_5020_50201501_69_dialog_content = "Aduh... Dingin sekali.",
  ui_story_5020_50201501_70_dialog_content = "Amemori, sudah lama. Apakah kamu merindukan saya?",
  ui_story_5020_50201501_71_dialog_content = "Belum selama itu.",
  ui_story_5020_50201501_72_dialog_content = "Ini bukan waktunya untuk mengenang masa lalu!",
  ui_story_5020_50201501_73_dialog_content = "Ah! Komandan!",
  ui_story_5020_50201501_74_dialog_content = "<size=45>Komandan Amemori!</size>",
  ui_story_5020_50201501_75_dialog_content = "Saya terus mengatakan, jangan panggil saya komandan!",
  ui_story_5020_50201501_76_dialog_content = "Komandan Amemori, kau sudah melatih Wisp dengan sangat baik.",
  ui_story_5020_50201501_77_dialog_content = "Kami bekerja sama dengan sangat baik.",
  ui_story_5020_50201501_78_dialog_content = "Wah, ayolah! Rinne Dan Amemori harus memiliki showdown yang tepat!",
  ui_story_5020_50201501_79_dialog_content = "Pertarungan memperebutkan posisi komandan Wisp akan dimulai sekarang!",
  ui_story_5020_50201501_80_dialog_content = "Aduh! Kepalaku!",
  ui_story_5020_50201501_81_dialog_content = "Lelucon macam apa ini?",
  ui_story_5020_50201501_82_dialog_content = "Baiklah. Sudah cukup bercandanya.",
  ui_story_5020_50201501_83_dialog_content = "Para hantu bergerak dengan cepat. Tidak butuh waktu lama bagi mereka untuk mencapai pelabuhan.",
  ui_story_5020_50201501_84_dialog_content = "PlayerName, ayo berpisah dan bersiap-siap sebelum mereka bisa sampai!",
  ui_story_5020_50201501_85_dialog_content = "Oke. Kemudian...",
  ui_story_5020_50201501_86_dialog_content = "Amemori Dan Yao akan memimpin Wisp untuk menjaga celah antara Sakai dan pelabuhan.",
  ui_story_5020_50201501_87_dialog_content = "Vice Dan PlayerName, harap tetap di sini untuk menjaga siapa pun yang berhasil melewati celah.",
  ui_story_5020_50201501_88_dialog_content = "Aku akan melibatkan para samurai di pelabuhan.",
  ui_story_5020_50201501_89_dialog_content = "Sendiri? Apa kamu yakin?",
  ui_story_5020_50201501_90_dialog_content = "Apakah Anda benar-benar berpikir ini saat yang tepat untuk mempertanyakan keterampilan saya, PlayerName?",
  ui_story_5020_50201501_91_dialog_content = "(Rinne benar-benar sudah berubah...)",
  ui_story_5020_50201501_92_dialog_content = "Ayo pergi kalau begitu!",
  ui_story_5020_50201501_93_dialog_content = "Yap!",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201501_95_dialog_content = "Mereka semakin dekat.",
  ui_story_5020_50201501_96_dialog_content = "Hmph! Tinjuku gatal untuk bertarung!",
  ui_story_5020_50201501_97_dialog_content = "Aku harus pergi ke pelabuhan sekarang.",
  ui_story_5020_50201501_98_dialog_content = "Aman, semuanya. Kita akan melewati perang ini bersama-sama!",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>Jalan masuk ke pelabuhan Koufu-jou</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>Sss... Sss...</color>",
  ui_story_5020_50201601_3_dialog_content = "Hosh... Hosh...",
  ui_story_5020_50201601_4_dialog_content = "Argh... Uhuk!",
  ui_story_5020_50201601_5_dialog_content = "Wanita Amemori!",
  ui_story_5020_50201601_6_dialog_content = "Dia terluka! Tutupi retretnya!",
  ui_story_5020_50201601_7_dialog_content = "Tidak dibutuhkan. Anda terus menuju Sakai ...",
  ui_story_5020_50201601_8_dialog_content = "Kalau diam saja, kita justru akan gagal.",
  ui_story_5020_50201601_9_dialog_content = "Pertahankan kekuatan bersama. Tidak menunjukkan belas kasihan kepada musuh.",
  ui_story_5020_50201601_10_dialog_content = "Jika Anda bertemu seseorang yang terlalu sulit untuk Anda tangani, biarkan mereka lolos ...",
  ui_story_5020_50201601_11_dialog_content = "Sepotong Surga kita akan menyelesaikan semuanya!",
  ui_story_5020_50201601_12_dialog_content = "Tapi Nona Amemori, kamu sudah...",
  ui_story_5020_50201601_13_dialog_content = "Sudahkah saya membuat diri saya jelas ?!",
  ui_story_5020_50201601_14_dialog_content = "Siap!",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>Duk, duk, duk…</color>",
  ui_story_5020_50201601_16_dialog_content = "Hosh... Hosh...",
  ui_story_5020_50201601_17_dialog_content = "Hati-Hati! Amemori—",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>Gaaah!</anim>",
  ui_story_5020_50201601_19_dialog_content = "Ninjutsu - Tanpa henti... Urgh...",
  ui_story_5020_50201601_20_dialog_content = "Amemori!",
  ui_story_5020_50201601_21_dialog_content = "Aku seharusnya... lebih berhati-hati.",
  ui_story_5020_50201601_22_dialog_content = "Yao... Sini, tempelkan punggungmu di punggungku.",
  ui_story_5020_50201601_23_dialog_content = "O-Oke! Tapi kenapa...",
  ui_story_5020_50201601_24_dialog_content = "Ah... Begitu rupanya...",
  ui_story_5020_50201601_25_dialog_content = "Keluarga Lin mengajari saya bahwa seorang pejuang sejati selalu menghadapi musuh secara langsung.",
  ui_story_5020_50201601_26_dialog_content = "Apakah Ninja menggunakan strategi yang sama?",
  ui_story_5020_50201601_27_dialog_content = "Memunggungi musuh Anda adalah larangan besar.",
  ui_story_5020_50201601_28_dialog_content = "Ninja tidak takut dengan serangan diam-diam dari segala arah.",
  ui_story_5020_50201601_29_dialog_content = "Namun, saat ini saya lebih rentan daripada biasanya.",
  ui_story_5020_50201601_30_dialog_content = "Apa aku bisa memercayaimu untuk melindungi punggungku?",
  ui_story_5020_50201601_31_dialog_content = "Hah! Apakah Anda bahkan harus bertanya?",
  ui_story_5020_50201601_32_dialog_content = "Bahkan jika kamu tidak terluka... Bahkan jika kita tidak terikat oleh Rebellion dan Ryojin...",
  ui_story_5020_50201601_33_dialog_content = "Kau tetaplah saudara seperjuanganku...",
  ui_story_5020_50201601_34_dialog_content = "Dan saya akan membantu Anda dengan semua yang saya miliki!",
  ui_story_5020_50201601_35_dialog_content = "Heheh... Kau bisa memotong dramanya.",
  ui_story_5020_50201601_36_dialog_content = "Lebih banyak musuh datang ...",
  ui_story_5020_50201601_37_dialog_content = "Siap, <color=#FFB400>junior</color>?",
  ui_story_5020_50201601_38_dialog_content = "Tentu saja! Saya memiliki banyak kekuatan yang tersisa!",
  ui_story_5020_50201601_39_dialog_content = "Hyaah!",
  ui_story_5020_50201601_40_dialog_content = "Haaa... Hah...",
  ui_story_5020_50201601_41_dialog_content = "Amemori, kamu harus bertahan di sana...",
  ui_story_5020_50201601_42_dialog_content = "Huff... Tentu saja...",
  ui_story_5020_50201601_43_dialog_content = "... Yao, ambil Sepotong Surga!",
  ui_story_5020_50201601_44_dialog_content = "Ada yang tidak beres...",
  ui_story_5020_50201601_45_dialog_content = "Baiklah!",
  ui_story_5020_50201601_46_dialog_content = "Apa yang tidak benar? Apa yang harus kita lakukan?",
  ui_story_5020_50201601_47_dialog_content = "... Ayo bergerak menuju Sakai. Kita harus membeli waktu untuk Rinne dan warga sipil di pelabuhan.",
  ui_story_5020_50201601_48_dialog_content = "Awasi lingkungan Anda.",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201601_51_dialog_content = "(Wisp sedang bertarung melawan sejumlah hantu kelas rendah di arah pukul 2...)",
  ui_story_5020_50201601_52_dialog_content = "(Dan ada langkah kaki manusia pada jam 10...)",
  ui_story_5020_50201601_53_dialog_content = "(Enam burung baru saja lepas landas di hutan pada jam 7...)",
  ui_story_5020_50201601_54_dialog_content = "(Aneh, saya tidak bisa mendengar suara yang tidak biasa. Apa yang terjadi?)",
  ui_story_5020_50201601_55_dialog_content = "...",
  ui_story_5020_50201601_56_dialog_content = "Wah! Amemori, di sebelah sana!",
  ui_story_5020_50201601_57_dialog_content = "Sosok itu...",
  ui_story_5020_50201601_58_dialog_content = "Warga Koufu yang tertinggal?",
  ui_story_5020_50201601_59_dialog_content = "Tapi bagaimana mungkin masih ada orang yang tersisa di kota?",
  ui_story_5020_50201601_60_dialog_content = "... Yao! Hati-hati!",
  ui_story_5020_50201601_61_dialog_content = "Apa?",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>... Gaa ...</anim>",
  ui_story_5020_50201601_63_dialog_content = "Apa katanya?",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>Gaaah...</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>Groar!</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "Apa itu... Fujikumo?!",
  ui_story_5020_50201601_67_dialog_content = "... Tidak!",
  ui_story_5020_50201601_68_dialog_content = "(Bagaimana Fujikumo lolos dari Guru dan berhasil sampai ke pelabuhan dalam keadaan utuh?)",
  ui_story_5020_50201601_69_dialog_content = "(Mungkinkah Guru...)",
  ui_story_5020_50201601_70_dialog_content = "Apa... Monster macam apa itu?",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>Berbaring...</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>Letakkan itu...</anim>",
  ui_story_5020_50201601_73_dialog_content = "Yao, pegang erat-erat Sepotong Surga...",
  ui_story_5020_50201601_74_dialog_content = "Kita mungkin tidak menang...",
  ui_story_5020_50201601_75_dialog_content = "Tapi kita tidak bisa membiarkan Slice of Heaven berada di tangannya!",
  ui_story_5020_50201601_76_dialog_content = "Di mana tuanku?!",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>Membunuh...</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>Membunuh...</anim>",
  ui_story_5020_50201601_79_dialog_content = "Apa?",
  ui_story_5020_50201601_80_dialog_content = "...",
  ui_story_5020_50201601_81_dialog_content = "Aku akan membunuhmu! Ninjutsu - Lacak...",
  ui_story_5020_50201601_82_dialog_content = "Argh... *Uhuk*",
  ui_story_5020_50201601_83_dialog_content = "(... Apa lagi yang bisa saya lakukan? Saya di... batas saya...)",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>Wush... Plak!</color>",
  ui_story_5020_50201601_85_dialog_content = "Rapid Torrent!",
  ui_story_5020_50201601_86_dialog_content = "Penghalang... Sebarkan!",
  ui_story_5020_50201601_87_dialog_content = "Kalian!",
  ui_story_5020_50201601_88_dialog_content = "Kalian berdua sudah bertarung dengan gencar!",
  ui_story_5020_50201601_89_dialog_content = "Kita semua sudah membersihkan area kita! Sekarang, mari kita fokus untuk mempertahankan operan!",
  ui_story_5020_50201601_90_dialog_content = "Bersembunyi di balik penghalang. Biarkan aku...",
  ui_story_5020_50201601_91_dialog_content = "Ah...",
  ui_story_5020_50201601_92_dialog_content = "Ini...",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>Groar!</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>Rinne...</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>Kamu berani...</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>Groar!</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "Itu Jenderal Fujikumo? Apa yang terjadi padanya?",
  ui_story_5020_50201601_98_dialog_content = "*Batuk* Itu tidak penting sekarang!",
  ui_story_5020_50201601_99_dialog_content = "Buru-buru! Bunuh dia dengan Sepotong Surga...",
  ui_story_5020_50201601_100_dialog_content = "Rinne! Tangkap!",
  ui_story_5020_50201601_101_dialog_content = "Siap!",
  ui_story_5020_50201601_102_dialog_content = "(Ini adalah pedang keramat yang diwariskan dari satu pendeta kepada pendeta berikutnya...)",
  ui_story_5020_50201601_103_dialog_content = "(Pendeta akan menggunakannya untuk membunuh hantu, tetapi sang jenderal telah menjauhkannya dari mereka...)",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>Buk... Buk... Buk...</color>",
  ui_story_5020_50201601_105_dialog_content = "(Ah... Jenderal... Kubou... Mungkin aku harus memanggilmu ayah untuk terakhir kalinya...)",
  ui_story_5020_50201601_106_dialog_content = "(Tanganku tidak bisa berhenti gemetar saat aku memegang Slice of Heaven...)",
  ui_story_5020_50201601_107_dialog_content = "(Ketakutan, kegugupan, dan antisipasi menyatu menjadi satu di dalam diriku...)",
  ui_story_5020_50201601_108_dialog_content = "(Ini bukan sesuatu yang pernah Anda ajarkan kepada saya ...)",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>Groar!</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "Ayah...",
  ui_story_5020_50201601_111_dialog_content = "Tolong... Ambil ini!",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>Gaar…</anim>",
  ui_story_5020_50201602_2_dialog_content = "Hyah... Huh...",
  ui_story_5020_50201602_3_dialog_content = "Rinne, sekarang!",
  ui_story_5020_50201602_4_dialog_content = "Hyaah!",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>Uraaaagh!</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>Hiss...</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>Hah... hah... hah...</anim>",
  ui_story_5020_50201602_8_dialog_content = "G-Jenderal?",
  ui_story_5020_50201602_9_dialog_content = "Kita berhasil!",
  ui_story_5020_50201602_10_dialog_content = "Mengusir hantu agar bisa kembali menjadi manusia...",
  ui_story_5020_50201602_11_dialog_content = "Apakah ini kekuatan sebenarnya dari Sepotong Surga?",
  ui_story_5020_50201602_12_dialog_content = "Rinne... Kalian benar-benar mengambil Slice of Heaven...",
  ui_story_5020_50201602_13_dialog_content = "Anda telah melakukannya dengan baik ...",
  ui_story_5020_50201602_14_dialog_content = "Datanglah padaku...",
  ui_story_5020_50201602_15_dialog_content = "Jenderal, kau...",
  ui_story_5020_50201602_16_dialog_content = "Anda telah melakukan terlalu banyak dosa yang tidak dapat saya ampuni ...",
  ui_story_5020_50201602_17_dialog_content = "Anda mungkin pernah merasa frustrasi dan tidak berdaya, tetapi itu tidak membenarkan pengejaran kekuasaan Anda yang kejam.",
  ui_story_5020_50201602_18_dialog_content = "Kebakaran di Koufu-jou sudah berhasil dipadamkan.",
  ui_story_5020_50201602_19_dialog_content = "... Dan inilah saatnya bagi Anda untuk beristirahat.",
  ui_story_5020_50201602_20_dialog_content = "Frustasi dan tak berdaya? Hahaha...",
  ui_story_5020_50201602_21_dialog_content = "Anda membaca surat itu setelah semua.",
  ui_story_5020_50201602_22_dialog_content = "Di luar apa yang Anda lihat, masih ada hal lain yang tidak akan pernah Anda mengerti.",
  ui_story_5020_50201602_23_dialog_content = "Tapi ini bukan kata-kata yang keluar dari mulut seorang anak.",
  ui_story_5020_50201602_24_dialog_content = "Rinne, kamu sudah dewasa.",
  ui_story_5020_50201602_25_dialog_content = "Untuk terakhir kalinya, bisakah kau tak memanggilku Jenderal Kubou?",
  ui_story_5020_50201602_26_dialog_content = "...",
  ui_story_5020_50201602_27_dialog_content = "Hmph! Anda tidak pantas mendapatkan gelar itu!",
  ui_story_5020_50201602_28_dialog_content = "Fujikumo, masa hidupmu sudah habis.",
  ui_story_5020_50201602_29_dialog_content = "Coba lihat sekelilingmu.",
  ui_story_5020_50201602_30_dialog_content = "Melayani Anda dengan benar! Itu yang saya sebut karma.",
  ui_story_5020_50201602_31_dialog_content = "Berlutut... Ya, berlutut... Hahahah! Siapa yang tahu Jenderal Fujikumo yang agung akan melihat hari seperti ini?!",
  ui_story_5020_50201602_32_dialog_content = "Mengapa kita membuang-buang waktu berbicara dengannya? Saudara-saudara, habisi dia! Satu persembahan ekstra untuk Festival Kasuga!",
  ui_story_5020_50201602_33_dialog_content = "Itu benar! Bunuh dia!",
  ui_story_5020_50201602_34_dialog_content = "Hahah... Hahahahahah...",
  ui_story_5020_50201602_35_dialog_content = "Jangan berani-berani!",
  ui_story_5020_50201602_36_dialog_content = "Mundur kamu bodoh! Menyakiti Kubou-sama membuat seluruh pulau utama menjadi musuh!",
  ui_story_5020_50201602_37_dialog_content = "Siapa sih yang peduli dengan pulau utama?",
  ui_story_5020_50201602_38_dialog_content = "Berbalik dan cari sendiri! Berapa banyak samuraimu yang masih bernafas!? Fujikumo, kamu pantas mendapatkan ini!",
  ui_story_5020_50201602_39_dialog_content = "Teman-teman, maju!",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>Ting...</color>",
  ui_story_5020_50201602_41_dialog_content = "Jangan mendekat!",
  ui_story_5020_50201602_42_dialog_content = "Mundur... *Uhuk* Mundurlah...",
  ui_story_5020_50201602_43_dialog_content = "Apa menurutmu Cloud Island akan menjadi tempat yang lebih baik dengan membunuh Jenderal Fujikumo?!",
  ui_story_5020_50201602_44_dialog_content = "...",
  ui_story_5020_50201602_45_dialog_content = "Bahkan jika kau membunuh jenderal saat ini...",
  ui_story_5020_50201602_46_dialog_content = "Seorang jenderal baru dari pulau utama akan menggantikannya dalam waktu setengah bulan.",
  ui_story_5020_50201602_47_dialog_content = "Kepada siapa Anda akan mengarahkan kemarahan Anda saat itu?",
  ui_story_5020_50201602_48_dialog_content = "Bagi Anda para pemberontak, Kubou-sama adalah orang luar yang Anda tuju.",
  ui_story_5020_50201602_49_dialog_content = "Namun kenyataannya, Kubou-sama juga hanyalah boneka yang menari mengikuti irama orang lain.",
  ui_story_5020_50201602_50_dialog_content = "Penjaga... Singkirkan orang ini...",
  ui_story_5020_50201602_51_dialog_content = "(Fujikumo...sepertinya sedang berjuang untuk berbicara...)",
  ui_story_5020_50201602_52_dialog_content = "Tuanku, izinkan kuselesaikan kata-kataku!",
  ui_story_5020_50201602_53_dialog_content = "... Kompromi yang dibuat Kubou-sama untuk menenangkan pulau utama...",
  ui_story_5020_50201602_54_dialog_content = "Upaya yang dia lakukan untuk menjaga Cloud Island tetap damai... Bagaimana mungkin ada di antara kalian yang bisa memahami semuanya?!",
  ui_story_5020_50201602_55_dialog_content = "Anda mungkin menyebutnya brutal... Anda mungkin mengatakan bahwa dia sinting...",
  ui_story_5020_50201602_56_dialog_content = "Tapi apakah Anda benar-benar berpikir apa yang dia cari salah?",
  ui_story_5020_50201602_57_dialog_content = "...",
  ui_story_5020_50201602_58_dialog_content = "Aku tidak suka apa yang dia katakan...",
  ui_story_5020_50201602_59_dialog_content = "Tapi saya pikir dia ada benarnya ...",
  ui_story_5020_50201602_60_dialog_content = "Saya selalu berpikir sebanyak itu, tetapi semua orang di sini terlalu berpikiran sederhana untuk memahami politik yang begitu rumit...",
  ui_story_5020_50201602_61_dialog_content = "Saya bisa mengelola Cloud Island seratus kali lebih baik dari Fujikumo ini!",
  ui_story_5020_50201602_62_dialog_content = "Apa ini? Dia menyanyikan sebuah lagu dan kalian semua mulai menari mengikutinya?!",
  ui_story_5020_50201602_63_dialog_content = "Kalau mau mengatasi musuh, kau harus hadapi aku dulu. Tak ada hal lain yang lebih kubenci daripada pengkhianat!",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>Kicau...Twitter...</color>",
  ui_story_5020_50201602_65_dialog_content = "Heh... Kubou-sama tidak berguna atas simpatimu yang terlambat.",
  ui_story_5020_50201602_66_dialog_content = "Baginya, simpati Anda adalah penghinaan!",
  ui_story_5020_50201602_67_dialog_content = "Diam...",
  ui_story_5020_50201602_68_dialog_content = "Ya! Tutup mulutmu!",
  ui_story_5020_50201602_69_dialog_content = "Hanya sedikit orang yang memahami Kubou-sama...",
  ui_story_5020_50201602_70_dialog_content = "Kubou-sama, tidak ada yang memahamimu lebih baik dariku!",
  ui_story_5020_50201602_71_dialog_content = "Cukup!",
  ui_story_5020_50201602_72_dialog_content = "Sudah cukup omong kosongmu.",
  ui_story_5020_50201602_73_dialog_content = "Memangnya kau ini siapa?",
  ui_story_5020_50201602_74_dialog_content = "...",
  ui_story_5020_50201602_75_dialog_content = "Anda datang...",
  ui_story_5020_50201701_1_dialog_content = "Wanita itu...",
  ui_story_5020_50201701_2_dialog_content = "Dia masih hidup?",
  ui_story_5020_50201701_3_dialog_content = "Ayah... Siapa dia?",
  ui_story_5020_50201701_4_dialog_content = "Ssst!",
  ui_story_5020_50201701_5_dialog_content = "Jangan mengajukan pertanyaan bodoh. Diam!",
  ui_story_5020_50201701_6_dialog_content = "(Master!)",
  ui_story_5020_50201701_7_dialog_content = "Heh...",
  ui_story_5020_50201701_8_dialog_content = "Pidatomu cukup mengharukan.",
  ui_story_5020_50201701_9_dialog_content = "Sebagai bawahan, kau benar-benar tahu cara mempermalukan jenderalmu sendiri.",
  ui_story_5020_50201701_10_dialog_content = "Apa maksudmu?",
  ui_story_5020_50201701_11_dialog_content = "Argh!",
  ui_story_5020_50201701_12_dialog_content = "Minggir.",
  ui_story_5020_50201701_13_dialog_content = "...",
  ui_story_5020_50201701_14_dialog_content = "Fujikumo, sudah terlalu lama kau menantikan datangnya saat ini.",
  ui_story_5020_50201701_15_dialog_content = "Akhirnya.",
  ui_story_5020_50201701_16_dialog_content = "Aku tiba di sini terlalu dini.",
  ui_story_5020_50201701_17_dialog_content = "Mungkin bukan hal yang buruk membiarkanmu menderita siksaan samurai ini lebih lama.",
  ui_story_5020_50201701_18_dialog_content = "Anda tidak membutuhkan simpati atau pengertian. Anda menginginkan kematian.",
  ui_story_5020_50201701_19_dialog_content = "Benar, 'kan?",
  ui_story_5020_50201701_20_dialog_content = "... Heheh.",
  ui_story_5020_50201701_21_dialog_content = "Mati di medan perang akan menjadi akhir yang pas bagi seorang pahlawan.",
  ui_story_5020_50201701_22_dialog_content = "Akhiri saja semua ini untukku...",
  ui_story_5020_50201701_23_dialog_content = "Tidak terlalu buruk untuk mati di tanganmu.",
  ui_story_5020_50201701_24_dialog_content = "Fujikumo, setelah semua transaksi kotor dan kotor yang telah kau lakukan dalam hidupmu...",
  ui_story_5020_50201701_25_dialog_content = "Sekarang setelah Anda menghembuskan nafas terakhir, tiba-tiba Anda peduli dengan kesopanan dan martabat.",
  ui_story_5020_50201701_26_dialog_content = "Hahahahah! Uhuk...",
  ui_story_5020_50201701_27_dialog_content = "Nagi, aku tahu betapa cepatnya sabetan pedangmu...",
  ui_story_5020_50201701_28_dialog_content = "Saya hanya meminta Anda menggunakannya dengan ketegasan Anda yang biasa.",
  ui_story_5020_50201701_29_dialog_content = "Heh. Jangan khawatir tentang itu.",
  ui_story_5020_50201701_30_dialog_content = "<color=#e8d9bb>Ting...</color>",
  ui_story_5020_50201701_31_dialog_content = "...",
  ui_story_5020_50201701_32_dialog_content = "Saya akan mengizinkan Anda untuk mengucapkan kata-kata terakhir Anda.",
  ui_story_5020_50201701_33_dialog_content = "...",
  ui_story_5020_50201701_34_dialog_content = "Tsuki...",
  ui_story_5020_50201701_35_dialog_content = "Apakah ini Koufu-jou yang ingin kamu lihat?",
  ui_story_5020_50201701_36_dialog_content = "...",
  ui_story_5020_50201701_37_dialog_content = "...",
  ui_story_5020_50201701_38_dialog_content = "Apakah... Apakah dia mati?",
  ui_story_5020_50201701_39_dialog_content = "Sepertinya begitu.",
  ui_story_5020_50201701_40_dialog_content = "Sepertinya dia sudah tak bernapas lagi...",
  ui_story_5020_50201701_41_dialog_content = "Dia meninggal! Dia benar-benar mati!",
  ui_story_5020_50201701_42_dialog_content = "Fujikumo sudah mati! Cloud Island tidak lagi memiliki seorang jenderal!",
  ui_story_5020_50201701_43_dialog_content = "<size=50><anim type=Shake>Hore!</anim></size>",
  ui_story_5020_50201701_44_dialog_content = "<size=50><anim type=Shake>Sang Jenderal sudah mati!</anim></size>",
  ui_story_5020_50201701_45_dialog_content = "<size=50><anim type=Shake>Jayalah Cloud Island!</anim></size>",
  ui_story_5020_50201701_46_dialog_content = "<anim type=Shake>Hore...</anim>",
  ui_story_5020_50201701_47_dialog_content = "...",
  ui_story_5020_50201701_48_dialog_content = "Komandan!",
  ui_story_5020_50201701_49_dialog_content = "Kamu hidup!",
  ui_story_5020_50201701_50_dialog_content = "Apa kau benar Master Nagi?",
  ui_story_5020_50201701_51_dialog_content = "Komandan? Komandan! Kau mau ke mana?",
  ui_story_5020_50201701_52_dialog_content = "Tunggu!",
  ui_story_5020_50201701_53_dialog_content = "...?",
  ui_story_5020_50201701_54_dialog_content = "Kau rupanya.",
  ui_story_5020_50201701_55_dialog_content = "Aku benci perpisahan. Buat itu cepat.",
  ui_story_5020_50201701_56_dialog_content = "Master, tunggu!",
  ui_story_5020_50201701_57_dialog_content = "Saya di sini, Guru!",
  ui_story_5020_50201701_58_dialog_content = "Apa... Tentang apa ini?",
  ui_story_5020_50201701_59_dialog_content = "Saya datang jauh-jauh ke Cloud Island dan mengalami banyak kesulitan, semua berkat Anda, Guru!",
  ui_story_5020_50201701_60_dialog_content = "(Kenapa aku merasa dia tidak akan merasa tersanjung...)",
  ui_story_5020_50201701_61_dialog_content = "Berkat Anda, Guru, saya mengalami konflik dan perjuangan generasi Anda.",
  ui_story_5020_50201701_62_dialog_content = "Saya belum pernah melihat yang seperti ini sebelumnya.",
  ui_story_5020_50201701_63_dialog_content = "Jadi, izinkan saya memanggil Anda Guru sekali lagi.",
  ui_story_5020_50201701_64_dialog_content = "Jika Anda membutuhkan bantuan di masa mendatang, hubungi Lin Guild di Umbraton, Astra!",
  ui_story_5020_50201701_65_dialog_content = "Aku akan membantumu tidak peduli seberapa jauh aku harus pergi!",
  ui_story_5020_50201701_66_dialog_content = "Heheh... Terima kasih, Yao.",
  ui_story_5020_50201701_67_dialog_content = "Tapi aku harus menempuh sisa perjalanan ini sendirian.",
  ui_story_5020_50201701_68_dialog_content = "Aku harus mengakhiri kekuasaan pulau utama atas Cloud Island. Itulah satu-satunya cara untuk menyelesaikan semua masalah lama ini.",
  ui_story_5020_50201701_69_dialog_content = "Anda akan pergi ke pulau utama?",
  ui_story_5020_50201701_70_dialog_content = "Guru, tolong...",
  ui_story_5020_50201701_71_dialog_content = "Jaga dirimu. Dan bawalah Cloud Island menuju masa depan yang lebih cerah.",
  ui_story_5020_50201701_72_dialog_content = "Wisp dan aku akan selalu siap bertarung untukmu.",
  ui_story_5020_50201701_73_dialog_content = "Oh? Amemori...",
  ui_story_5020_50201701_74_dialog_content = "Anda akhirnya tumbuh dewasa.",
  ui_story_5020_50201701_75_dialog_content = "Anda adalah komandan Wisp yang lebih baik daripada saya.",
  ui_story_5020_50201701_76_dialog_content = "Master Nagi, jaga dirimu. Semoga kemenangan besertamu!",
  ui_story_5020_50201701_77_dialog_content = "...",
  ui_story_5020_50201701_78_dialog_content = "Sampai jumpa lagi.",
  ui_story_5020_50201701_79_dialog_content = "Ah! Harap tunggu. Ada satu hal lagi...",
  ui_story_5020_50201701_80_dialog_content = "PlayerName, kita harus memberikannya padanya.",
  ui_story_5020_50201701_81_dialog_content = "Kau benar!",
  ui_story_5020_50201701_82_dialog_content = "Apa?",
  ui_story_5020_50201701_83_dialog_content = "Nagi, terimalah buku catatan ini.",
  ui_story_5020_50201701_84_dialog_content = "Dia tidak meninggalkan banyak hal dalam hal instruksi...",
  ui_story_5020_50201701_85_dialog_content = "Tapi saya pikir notebook ini mungkin penting bagi Anda.",
  ui_story_5020_50201701_86_dialog_content = "Jadi, saya pikir Anda harus menjadi orang yang menjaganya.",
  ui_story_5020_50201701_87_dialog_content = "Tsuki... membuat buku harian...",
  ui_story_5020_50201701_88_dialog_content = "Aku tak pernah melihatnya menulis...",
  ui_story_5020_50201701_89_dialog_content = "Aku sudah memutuskan untuk mengesampingkan semuanya dan pergi ke pulau utama.",
  ui_story_5020_50201701_90_dialog_content = "Tolong pegang itu untukku.",
  ui_story_5020_50201701_91_dialog_content = "Apakah Anda yakin tidak ingin membacanya?",
  ui_story_5020_50201701_92_dialog_content = "Agar bisa melangkah maju, kita harus melepaskan masa lalu, bukan lari darinya.",
  ui_story_5020_50201701_93_dialog_content = "Itu mungkin menjawab beberapa pertanyaan Anda, dan menjernihkan beberapa dendam lama.",
  ui_story_5020_50201701_94_dialog_content = "...",
  ui_story_5020_50201701_95_dialog_content = "Baiklah.",
  ui_story_5020_50201701_96_dialog_content = "...",
  ui_story_5020_50201701_97_dialog_content = "...",
  ui_story_5020_50201701_98_dialog_content = "<size=30>Tsuki...</size>",
  ui_story_5020_50201701_99_dialog_content = "Tsuki...",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>Di sebuah jalan di kota kastel Koufu-jou</color>",
  ui_story_5020_50201701_101_dialog_content = "Ahh! Adegan yang sangat harmonis!",
  ui_story_5020_50201701_102_dialog_content = "Panggung dihiasi dengan spanduk warna-warni. Para taiko sudah siap. Orang-orang sedang meraup ikan di bawah pohon ceri...",
  ui_story_5020_50201701_103_dialog_content = "Dan ninja terhormat ini duduk di sini di sebelahku bukannya membuat masalah.",
  ui_story_5020_50201701_104_dialog_content = "Tolong jangan panggil aku seperti itu.",
  ui_story_5020_50201701_105_dialog_content = "Jangan kecewakan Momo dan Anzu. Teh ini sangat sedap.",
  ui_story_5020_50201701_106_dialog_content = "... Aku benci rasa yang berat. Saya tidak akan makan apapun dari warung ini.",
  ui_story_5020_50201701_107_dialog_content = "(Krucuk...)",
  ui_story_5020_50201701_108_dialog_content = "Aduh...!",
  ui_story_5020_50201701_109_dialog_content = "Segera datang! Maaf membuatmu menunggu lama!",
  ui_story_5020_50201701_110_dialog_content = "Silakan cicipi sajian baru kami, Ramen Sayur Kaniya!",
  ui_story_5020_50201701_111_dialog_content = "Kami telah menyempurnakan resep setelah uji rasa yang tak terhitung jumlahnya dengan Prajurit kami yang tak kenal takut Yao!",
  ui_story_5020_50201701_112_dialog_content = "Bersendawa... Saya sangat puas...",
  ui_story_5020_50201701_113_dialog_content = "(Yao koma akibat makanan!)",
  ui_story_5020_50201701_114_dialog_content = "Kalau begitu...",
  ui_story_5020_50201701_115_dialog_content = "Kurasa aku bisa makan satu atau dua gigitan.",
  ui_story_5020_50201701_116_dialog_content = "Kita harus bergegas dan membuat cerita latar untuk hidangan baru!",
  ui_story_5020_50201701_117_dialog_content = "Pelanggan baru tak akan mau datang lagi untuk mendengar cerita lawas!",
  ui_story_5020_50201701_118_dialog_content = "PlayerName, cerita seperti apa yang cocok dengan hidangan ini?",
  ui_story_5020_50201701_119_dialog_content = "Hah? Kalian minta pendapat dariku?",
  ui_story_5020_50201701_120_dialog_content = "Menurut pendapat saya...",
  ui_story_5020_50201701_121_option_content = "Kalian bisa ceritakan kisah tentang tiga kawan lama.",
  ui_story_5020_50201701_122_dialog_content = "Tiga teman lama mendedikasikan hidup mereka untuk melindungi tanah ini dengan cara mereka sendiri.",
  ui_story_5020_50201701_123_dialog_content = "Sepasang kakak beradik ini ditakdirkan untuk berpisah, namun lagu mereka masih dapat didengar di sini.",
  ui_story_5020_50201701_124_dialog_content = "Pendeta dan jenderal yang disalahpahami mengatasi status mereka yang berbeda dan mengembangkan kepercayaan satu sama lain.",
  ui_story_5020_50201701_125_dialog_content = "Kedua pejuang berjuang sampai detik terakhir tetapi akhirnya mencapai saling pengertian dan mengucapkan selamat tinggal satu sama lain.",
  ui_story_5020_50201701_126_dialog_content = "Pada akhirnya, tanah ini berkembang menuju perdamaian seperti yang mereka perkirakan...",
  ui_story_5020_50201701_127_dialog_content = "Kau benar-benar yakin kisah ini bagus untuk diceritakan untuk menemani orang-orang yang makan di sini?",
  ui_story_5020_50201701_128_option_content = "Kalian bisa menceritakan kisah tentang tiga anak kecil.",
  ui_story_5020_50201701_129_dialog_content = "Tiga anak yang tidak biasa memulai perjalanan untuk melawan kejahatan dan monster, masing-masing dengan alasan mereka sendiri...",
  ui_story_5020_50201701_130_dialog_content = "Sepanjang jalan, mereka semua belajar bahwa ada hal-hal yang jauh lebih berharga daripada kemenangan.",
  ui_story_5020_50201701_131_dialog_content = "Si prajurit bertopeng besi jadi mengenal arti persahabatan.",
  ui_story_5020_50201701_132_dialog_content = "Si orang-orangan sawah yang badannya basah kuyup oleh air laut bisa mendapatkan kembali ingatannya yang hilang.",
  ui_story_5020_50201701_133_dialog_content = "Singa yang menyamar menemukan keberanian untuk melawan takdirnya...",
  ui_story_5020_50201701_134_dialog_content = "Jangan menjiplak cerita pengantar tidur anak-anak dari Northland! Itu terlalu banyak!",
  ui_story_5020_50201701_135_dialog_content = "Hmm... Kedengarannya seperti ide bagus!",
  ui_story_5020_50201701_136_dialog_content = "Kami akan menyusun naskah berdasarkan ide dari PlayerName!",
  ui_story_5020_50201701_137_dialog_content = "Tapi pertama-tama, kita membutuhkan akhir yang tepat untuk kisah Cloud Island kita...",
  ui_story_5020_50201701_138_dialog_content = "Akhir yang tepat? Apakah ada sesuatu yang tidak kita sadari?",
  ui_story_5020_50201701_139_dialog_content = "Mmm... Kami baru saja dapat secuil informasi ini dari pekerja paruh waktu kami!",
  ui_story_5020_50201701_140_dialog_content = "Jika Anda benar-benar ingin mendengar ...",
  ui_story_5020_50201701_141_dialog_content = "Semangkuk lagi, ya.",
  ui_story_5020_50201701_142_dialog_content = "Mengapa, pelanggan yang terhormat, Anda seorang profesional, bukan? Kalau begitu ... di mana kita sampai terakhir kali ...",
  ui_story_5020_50201701_143_dialog_content = "Fujikumo dikatakan tidak bisa dihancurkan dengan hati sekeras batu dan sedingin es. Tak seorang pun di Cloud Island tahu titik lemahnya, kecuali...",
  ui_story_5020_50201701_144_dialog_content = "Tada... Kami Kayano!",
  ui_story_5020_50201701_145_dialog_content = "Hah? Itu tidak terduga! A-Apakah kamu berbicara denganku?",
  ui_story_5020_50201701_146_dialog_content = "Kemarilah, pekerja kecil. Memberi tahu PlayerName-sama apa yang Anda lihat ketika Anda bolos kerja hari itu.",
  ui_story_5020_50201701_147_dialog_content = "Aku... Aku juga pergi untuk mengagumi bunga sakura di <color=#FFB400>makam</color> di luar kota hari itu... Ini adalah musim ketika bunga sakura putih berguguran...",
  ui_story_5020_50201701_148_dialog_content = "Aku baru saja sampai di pintu masuk ketika aku melihat sudah ada seseorang di dalam...",
  ui_story_5020_50201701_149_dialog_content = "?!",
  ui_story_5020_50201701_150_dialog_content = "(Orang yang sampai ke kuburan sebelum kita!)",
  ui_story_5020_50201701_151_dialog_content = "Jadi... siapa itu?!",
  ui_story_5020_50201701_152_dialog_content = "Ahh... PlayerName sangat galak dan tak sabaran...",
  ui_story_5020_50201701_153_dialog_content = "Maaf... maafkan aku...",
  ui_story_5020_50201701_154_dialog_content = "Dia tidak memperhatikan saya, tetapi saya melihatnya dengan jelas ...",
  ui_story_5020_50201701_155_dialog_content = "Dulu... <color=#FFB400>Jenderal Fujikumo</color>...",
  ui_story_5020_50201701_156_dialog_content = "...",
  ui_story_5020_50201701_157_dialog_content = "Dia berdiri di depan makam seseorang dalam diam. Tidak ada satupun samurai di dekatnya...",
  ui_story_5020_50201701_158_dialog_content = "Saya pikir dia akan mengambil pedang emas yang tergeletak di depan batu nisan... Tapi dia tidak...",
  ui_story_5020_50201701_159_dialog_content = "Sebaliknya ... dia dengan sungguh-sungguh meletakkan sesuatu sebelum pergi ...",
  ui_story_5020_50201701_160_dialog_content = "Lalu... Lalu dia hampir melihatku... Aku langsung kabur...",
  ui_story_5020_50201701_161_dialog_content = "...",
  ui_story_5020_50201701_162_dialog_content = "Bagaimanapun, itu adalah Fujikumo ...",
  ui_story_5020_50201701_163_dialog_content = "Itu benar! Jenderal yang tidak berperasaan diam-diam memberi penghormatan kepada seorang teman lama di sudut pulau yang terpencil ...",
  ui_story_5020_50201701_164_dialog_content = "Hmm! Ini pasti akan bisa menarik banyak pelanggan baru!",
  ui_story_5020_50201701_165_dialog_content = "Hei! Tapi, ini...",
  ui_story_5020_50201701_166_dialog_content = "Tidak apa-apa, PlayerName.",
  ui_story_5020_50201701_167_dialog_content = "Jika ini menjadi gambar terakhir jenderal dan mantan pendeta Cloud Island...",
  ui_story_5020_50201701_168_dialog_content = "Biarkan itu menjadi halaman penutup dari masa lalu pulau itu.",
  ui_story_5020_50201701_169_dialog_content = "Bagaimanapun, era baru ...",
  ui_story_5020_50201701_170_dialog_content = "Telah mulai!",
  ui_story_5020_50201701_171_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5020_50201701_172_dialog_content = "Bergerak! Jangan mendirikan toko di sini, kami sedang membuka jalan menuju kastil utama.",
  ui_story_5020_50201701_173_dialog_content = "Kastil utama? Kastil apa? Siapa orang luar ini?",
  ui_story_5020_50201701_174_dialog_content = "...",
  ui_story_5020_50201701_175_dialog_content = "Lihat! Pulau utama sudah mengirim pasukan. Seragam itu memiliki pola pulau utama.",
  ui_story_5020_50201701_176_dialog_content = "Sesuai dugaan, mereka tak akan mau begitu saja melepaskan kuasa atas Cloud Island.",
  ui_story_5020_50201701_177_dialog_content = "Rinne, apakah kamu akan tetap di tempat ini?",
  ui_story_5020_50201701_178_dialog_content = "Heheh. Aku sudah membuat rencanaku. Anda sekelompok di sisi lain ...",
  ui_story_5020_50201701_179_dialog_content = "Apa rencana kalian untuk pergi dari sini?",
  ui_story_5020_50201701_180_dialog_content = "Jangan khawatir. Kami akan menerbangkan Colossus dan mengambil jalan yang sama kembali.",
  ui_story_5020_50201701_181_dialog_content = "Omong-omong ... Soroz bisa menggunakan beberapa layanan ...",
  ui_story_5020_50201701_182_dialog_content = "Colossus? Soroz?",
  ui_story_5020_50201701_183_dialog_content = "Ahh... Begitu banyak kata yang belum pernah kudengar sebelumnya...",
  ui_story_5020_50201701_184_dialog_content = "Aku benar-benar harus pergi dan menjelajahi dunia luar.",
  ui_story_5020_50201701_185_dialog_content = "<color=#e8d9bb>Pelabuhan Koufu-jou</color>",
  ui_story_5020_50201701_186_dialog_content = "Baiklah. Saatnya mengucapkan selamat tinggal!",
  ui_story_5020_50201701_187_dialog_content = "Sebentar lagi perahuku akan tiba.",
  ui_story_5020_50201701_188_dialog_content = "Payah.",
  ui_story_5020_50201701_189_dialog_content = "Aku tidak tertarik melihatmu pergi...",
  ui_story_5020_50201701_190_dialog_content = "Tapi, ini bagian dari cara Cloud Island untuk menjamu para tamu.",
  ui_story_5020_50201701_191_dialog_content = "Lady Amemori...",
  ui_story_5020_50201701_192_dialog_content = "Aku...",
  ui_story_5020_50201701_193_dialog_content = "<size=45>Wuuuahhhhh!</size>",
  ui_story_5020_50201701_194_dialog_content = "H-Hei! Apa sih yang kamu lakukan?",
  ui_story_5020_50201701_195_dialog_content = "Wahhhh... Amemori tidak tahan melihatku pergi juga! SAYA...",
  ui_story_5020_50201701_196_dialog_content = "<size=50><anim type=Shake>Saya tidak ingin mengucapkan selamat tinggal ... Wahhh!</anim></size>",
  ui_story_5020_50201701_197_dialog_content = "Sudah, sudah. Yao, jangan menangis.",
  ui_story_5020_50201701_198_dialog_content = "Kita pasti akan berjumpa lagi.",
  ui_story_5020_50201701_199_dialog_content = "* Hiks * A-Apa?",
  ui_story_5020_50201701_200_dialog_content = "Rinne... Anda...",
  ui_story_5020_50201701_201_dialog_content = "<size=50><anim type=Shake>Wahhhhh! Kau tidak ikut denganku?</anim></size>",
  ui_story_5020_50201701_202_dialog_content = "<size=55><anim type=Shake>Wahhhhhhhh...</anim></size>",
  ui_story_5020_50201701_203_dialog_content = "Aduh Buyung...",
  ui_story_5020_50201701_204_dialog_content = "Dengar, Yao.",
  ui_story_5020_50201701_205_dialog_content = "Ada banyak hal yang harus kulakukan di Cloud Island...",
  ui_story_5020_50201701_206_dialog_content = "Pasukan pulau utama sudah bertindak. Saya harus tetap di sini untuk menjaga mereka tetap terkendali.",
  ui_story_5020_50201701_207_dialog_content = "Aku telah menyimpan Cloud Mirror dan Slice of Heaven dengan aman...",
  ui_story_5020_50201701_208_dialog_content = "Mulai sekarang, saya akan menggunakan kekuatan saya sendiri untuk menjaga perdamaian dan ketertiban di Cloud Island.",
  ui_story_5020_50201701_209_dialog_content = "Tentu saja... Amemori dan Wisp akan membantuku juga. Benar?",
  ui_story_5020_50201701_210_dialog_content = "Itu wajar saja.",
  ui_story_5020_50201701_211_dialog_content = "Dengan atau tanpamu, sejak dulu misi Wisp adalah melawan pulau utama.",
  ui_story_5020_50201701_212_dialog_content = "Seperti yang Anda lihat, sayang Yao... Saya harus tinggal dan membawa perubahan ke Cloud Island.",
  ui_story_5020_50201701_213_dialog_content = "Kau percaya padaku?",
  ui_story_5020_50201701_214_dialog_content = "*Hiks*... Aku tahu Rinne bisa melakukan ini...",
  ui_story_5020_50201701_215_dialog_content = "Nah... Rinne, Amemori... Momo, Anzu, dan Kayano...",
  ui_story_5020_50201701_216_dialog_content = "Semuanya, jaga dirimu!",
  ui_story_5020_50201701_217_dialog_content = "Oh, dan PlayerName Dan Vice!",
  ui_story_5020_50201701_218_dialog_content = "Ya?",
  ui_story_5020_50201701_219_dialog_content = "Terima kasih sudah membantuku dan menemaniku pergi ke sini.",
  ui_story_5020_50201701_220_dialog_content = "Kami membuat begitu banyak teman dan kenangan berharga ...",
  ui_story_5020_50201701_221_dialog_content = "Saya telah memperoleh banyak hal dari pulau ini yang akan saya hargai selama sisa hidup saya.",
  ui_story_5020_50201701_222_dialog_content = "*Endus*",
  ui_story_5020_50201701_223_dialog_content = "(Ya ampun... lebih baik aku menghiburnya...)",
  ui_story_5020_50201701_224_dialog_content = "Karena alasan itulah...",
  ui_story_5020_50201701_225_dialog_content = "Sejumlah besar, jauh melebihi 7 digit, akan ditransfer ke akun Anda segera setelah saya kembali ke klan Lin!",
  ui_story_5020_50201701_226_dialog_content = "Hah?!",
  ui_story_5020_50201701_227_dialog_content = "... Tidak baik? Tidak ada cara lain bagi saya untuk mengungkapkan rasa terima kasih saya!",
  ui_story_5020_50201701_228_dialog_content = "Itu berlebihan!",
  ui_story_5020_50201701_229_dialog_content = "Hmm... Bagaimana kita harus membelanjakan uang ini? Kita perlu memperbaiki Colossus... Kemudian...",
  ui_story_5020_50201701_230_dialog_content = "(Kamu benar-benar terburu-buru!)",
  ui_story_5020_50201701_231_dialog_content = "Ah! Ada sesuatu yang perlahan mendekat...",
  ui_story_5020_50201701_232_dialog_content = "<color=#e8d9bb>Bip... Woo...</color>",
  ui_story_5020_50201701_233_dialog_content = "Hmm... Agh...",
  ui_story_5020_50201701_234_dialog_content = "Jadi inilah kekuatan laut...",
  ui_story_5020_50201701_235_dialog_content = "Wow! Kakak, tolong! Anda membuat saya gugup!",
  ui_story_5020_50201701_236_dialog_content = "Jangan bilang siapa-siapa bahwa Ying ternama dari klan Lin yang tersohor itu rupanya tak kuat naik perahu!",
  ui_story_5020_50201701_237_dialog_content = "Berhenti... *blehh* Berhenti berteriak...",
  ui_story_5020_50201701_238_dialog_content = "*Hiks*",
  ui_story_5020_50201701_239_dialog_content = "Pelanggan kehormatan yang mampu menghabiskan tujuh mangkuk ramen dalam sekali kunjungan...",
  ui_story_5020_50201701_240_dialog_content = "Silakan kembali untuk mengunjungi Pulau Cloud ketika Anda menemukan waktu ...",
  ui_story_5020_50201701_241_dialog_content = "Kaniya Ramen siap melayanimu!",
  ui_story_5020_50201701_242_dialog_content = "*Hiks*",
  ui_story_5020_50201701_243_dialog_content = "Emm...bos...",
  ui_story_5020_50201701_244_dialog_content = "Sajian baru yang Warrior Yao dibuat pasti akan menjadi hit besar ...",
  ui_story_5020_50201701_245_dialog_content = "Jangan terlalu kesal...",
  ui_story_5020_50201701_246_dialog_content = "Kau benar!",
  ui_story_5020_50201701_247_dialog_content = "Yao...",
  ui_story_5020_50201701_248_dialog_content = "Hati-hati, ya...",
  ui_story_5020_50201701_249_dialog_content = "Lain kali kita bertemu, jangan membuatku malu.",
  ui_story_5020_50201701_250_dialog_content = "Ah...",
  ui_story_5020_50201701_251_dialog_content = "Kalian...",
  ui_story_5020_50201701_252_dialog_content = "Semoga kita bisa segera bertemu lagi!",
  ui_story_5020_50201701_253_dialog_content = "Yao naik ke perahu. Rinne melambaikan tangan sebagai tanda perpisahan. Amemori berdiri di belakangnya, mengamati dalam diam.",
  ui_story_5020_50201701_254_dialog_content = "Saya pikir mereka menghargai setiap detik dari perpisahan ini sebelum perahu berlayar dari pandangan mereka.",
  ui_story_5020_50201701_255_dialog_content = "Sepuluh tahun yang lalu, satu kematian mencabik-cabik tiga gadis kecil.",
  ui_story_5020_50201701_256_dialog_content = "Hari ini, lagi-lagi kematian memaksa mereka menempuh jalan yang berbeda-beda.",
  ui_story_5020_50201701_257_dialog_content = "Kelopak merah muda pucat mekar dan jatuh seperti salju melintasi Cloud Island selama sepuluh tahun, menjadi saksi reuni dan perpisahan mereka.",
  ui_story_5020_50201701_258_dialog_content = "Menjadi saksi juga almarhum, dipertemukan kembali di akhirat.",
  ui_story_5020_50201701_259_dialog_content = "<color=#e8d9bb>Selesai</color>"
}
return config
